window.CATALOG = {"categories": [{"id": "physics", "name": {"zh": "物理", "en": "Physics"}, "lessons": [{"id": "force-motion", "name": {"zh": "力與運動", "en": "Force & Motion"}, "versions": {"zh": "force-motion-zh", "en": "force-motion-en"}}, {"id": "circuits", "name": {"zh": "電路與歐姆定律", "en": "Circuits & Ohm’s Law"}, "versions": {"zh": "circuits-zh", "en": "circuits-en"}}, {"id": "waves", "name": {"zh": "波動、聲音與光", "en": "Waves, Sound & Light"}, "versions": {"zh": "waves-zh", "en": "waves-en"}}]}, {"id": "chemistry", "name": {"zh": "化學", "en": "Chemistry"}, "lessons": [{"id": "chem-reactions", "name": {"zh": "化學反應與質量守恆", "en": "Chemical Reactions & Conservation of Mass"}, "versions": {"zh": "chem-reactions-zh", "en": "chem-reactions-en"}}, {"id": "chem-acids", "name": {"zh": "酸、鹼、鹽", "en": "Acids, Bases & Salts"}, "versions": {"zh": "chem-acids-zh", "en": "chem-acids-en"}}, {"id": "chem-redox", "name": {"zh": "氧化與還原", "en": "Oxidation & Reduction"}, "versions": {"zh": "chem-redox-zh", "en": "chem-redox-en"}}]}, {"id": "biology", "name": {"zh": "生物", "en": "Biology"}, "lessons": [{"id": "bio-osmosis", "name": {"zh": "細胞：滲透作用", "en": "Cells: Osmosis"}, "versions": {"zh": "bio-osmosis-zh", "en": "bio-osmosis-en"}}, {"id": "bio-genetics", "name": {"zh": "遺傳：顯性與隱性", "en": "Genetics: Dominant & Recessive"}, "versions": {"zh": "bio-genetics-zh", "en": "bio-genetics-en"}}, {"id": "bio-ecology", "name": {"zh": "生態：食物網與能量金字塔", "en": "Ecology: Food Webs & Energy Pyramids"}, "versions": {"zh": "bio-ecology-zh", "en": "bio-ecology-en"}}]}]};
window.DECKS = {"force-motion-zh": {"title": "力與運動", "lang": "zh", "slides": [{"id": "cover", "html": "<section data-transition=\"fade\" id=\"cover\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">物理</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">力與運動</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">東西為什麼會動？為什麼會停？<br/>三條規則就能解釋。</p>\n</div>\n<svg aria-label=\"一隻手把推車往右推；橘色箭頭代表力，藍色箭頭代表推車越來越快\" height=\"480\" viewbox=\"0 0 720 480\" width=\"720\">\n<line stroke=\"#6D7F7B\" stroke-width=\"8\" x1=\"20\" x2=\"700\" y1=\"400\" y2=\"400\"></line>\n<rect fill=\"#F3F5F2\" height=\"130\" rx=\"16\" width=\"260\" x=\"240\" y=\"230\"></rect>\n<rect fill=\"#BFCDC9\" height=\"40\" rx=\"10\" width=\"200\" x=\"270\" y=\"200\"></rect>\n<circle cx=\"300\" cy=\"380\" fill=\"#18262B\" r=\"22\" stroke=\"#F3F5F2\" stroke-width=\"8\"></circle>\n<circle cx=\"440\" cy=\"380\" fill=\"#18262B\" r=\"22\" stroke=\"#F3F5F2\" stroke-width=\"8\"></circle>\n<line stroke=\"#E58A55\" stroke-linecap=\"round\" stroke-width=\"16\" x1=\"40\" x2=\"190\" y1=\"295\" y2=\"295\"></line>\n<polygon fill=\"#E58A55\" points=\"186,265 236,295 186,325\"></polygon>\n<line stroke=\"#7FB0F2\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"530\" x2=\"650\" y1=\"130\" y2=\"130\"></line>\n<polygon fill=\"#7FB0F2\" points=\"646,106 690,130 646,154\"></polygon>\n<line opacity=\"0.6\" stroke=\"#7FB0F2\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"530\" x2=\"610\" y1=\"170\" y2=\"170\"></line>\n<line opacity=\"0.6\" stroke=\"#7FB0F2\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"530\" x2=\"590\" y1=\"90\" y2=\"90\"></line>\n</svg>\n\n</section>", "note": "這一課給完全沒學過物理的同學。我們從生活經驗出發，例如公車煞車時身體往前衝，一步步認識牛頓三大運動定律。"}, {"id": "hook", "html": "<section data-transition=\"fade\" id=\"hook\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">公車煞車時，為什麼你會往前衝？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 3 2 21h20L12 3zM12 10v5M12 18h.01\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">公車停下來</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">煞車推著公車，讓它慢下來。<b style=\"color:#18262B\">沒有東西把你往後推。</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">你的身體繼續往前</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">你的身體原本跟著公車一起跑，<b style=\"color:#18262B\">它想繼續保持運動</b>。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">沒有人推你。這種感覺有個名字，就是今天三條規則裡的第一條。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 2</p>\n\n</section>", "note": "先問學生：是什麼把你往前推？大多數人會說「公車」或「煞車」。答案出乎意料：根本沒有東西往前推你，是你的身體自己繼續往前。這就是慣性，也就是牛頓第一定律。"}, {"id": "goals", "html": "<section data-transition=\"fade\" id=\"goals\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M6 4l14 8-14 8z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">說明慣性</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">解釋為什麼運動的東西會繼續運動、靜止的東西會保持靜止。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">會用 F = ma</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">知道力和質量，就能算出加速度。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">找出作用力與反作用力</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">在一次推或拉之中，找出成對的兩個力。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 3</p>\n\n</section>", "note": "三個目標對應牛頓三大定律。學完定律後，我們會讀一張速度–時間圖，破解一個常見迷思，最後做三題小測驗。"}, {"id": "basics", "html": "<section data-section=\"Before you start: speed, acceleration and force\" data-transition=\"fade\" id=\"basics\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">開始之前</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">先認識四個詞</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">速率</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">每秒走多遠。<b style=\"color:#18262B\">10 m/s</b> 就是每秒走 10 公尺。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">加速度</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">每秒速度變化多少。0 → 10 → 20 m/s 就是 <b style=\"color:#18262B\">10 m/s²</b>。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">力</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">推或拉，單位是<b style=\"color:#18262B\">牛頓（N）</b>。拿著一顆蘋果大約要 1 N。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">合力</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">所有力加起來的結果。向左 5 N ＋ 向右 5 N ＝ <b style=\"color:#18262B\">0 N</b>。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 4</p>\n\n</section>", "note": "藍色卡片描述運動本身，橘色卡片描述造成運動的原因。「合力」是後面三條定律的關鍵：如果推力互相抵消，合力就是零。"}, {"id": "law1", "html": "<section data-section=\"Newton’s three laws of motion\" data-transition=\"fade\" id=\"law1\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">牛頓第一定律</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">慣性：東西會保持原來的樣子</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"快速把桌上杯子底下的卡片抽走，杯子留在原地\" height=\"380\" viewbox=\"0 0 640 380\" width=\"640\">\n<rect fill=\"#18262B\" height=\"20\" width=\"440\" x=\"40\" y=\"250\"></rect>\n<rect fill=\"#18262B\" height=\"90\" width=\"18\" x=\"70\" y=\"270\"></rect>\n<rect fill=\"#18262B\" height=\"90\" width=\"18\" x=\"432\" y=\"270\"></rect>\n<rect fill=\"#9AAAA6\" height=\"12\" width=\"420\" x=\"150\" y=\"238\"></rect>\n<polygon fill=\"#FBFCFA\" points=\"200,120 290,120 280,238 210,238\" stroke=\"#18262B\" stroke-width=\"6\"></polygon>\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"490\" x2=\"580\" y1=\"200\" y2=\"200\"></line>\n<polygon fill=\"#B4521F\" points=\"576,178 616,200 576,222\"></polygon>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">快速抽走卡片：杯子留在原地。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">物體很「懶」。靜止的東西保持靜止，運動的東西會以<b>相同速度沿直線</b>一直走下去。</p>\n<p style=\"font-size:40px;font-weight:800;line-height:1.35;background:#FBFCFA;padding:24px 32px;border-radius:16px\">合力為零 → 運動狀態不變</p>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\"><b style=\"color:#B4521F\">迷思：</b>運動的東西需要一直有人推。<br/><b style=\"color:#2463B8\">事實：</b>冰球會自己滑行，會停下來只是因為摩擦力讓它變慢。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 5</p>\n\n</section>", "note": "可以的話現場示範抽卡片。回到公車：你的身體繼續往前，是因為沒有力讓它停下，所以你往前衝。在幾乎沒有摩擦力的冰面上，冰球可以滑很遠。"}, {"id": "law2", "html": "<section data-transition=\"fade\" id=\"law2\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">牛頓第二定律</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">F</p>\n<p style=\"font-size:32px;color:#BFCDC9\">力（N）</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">m</p>\n<p style=\"font-size:32px;color:#BFCDC9\">質量（kg）</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">a</p>\n<p style=\"font-size:32px;color:#BFCDC9\">加速度（m/s²）</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">推得越用力 → 加速越快。<br/>東西越重 → 加速越慢。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">要求加速度，就倒過來用：<b style=\"color:#7FB0F2\">a = F ÷ m</b></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">力與運動 · 6</p>\n\n</section>", "note": "公式只是把學生已經感覺到的事寫下來。推空的購物車和推裝滿的購物車，是最好的生活例子。大部分題目都問加速度，所以要多練 a = F ÷ m。"}, {"id": "law2b", "html": "<section data-transition=\"fade\" id=\"law2b\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">算算看</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">推力一樣，質量不同</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"兩台推車被同樣大小的橘色箭頭推；空車的藍色箭頭很長，代表加速很快；載滿的推車藍色箭頭很短\" height=\"400\" viewbox=\"0 0 720 400\" width=\"720\">\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"20\" x2=\"120\" y1=\"70\" y2=\"70\"></line>\n<polygon fill=\"#B4521F\" points=\"116,50 150,70 116,90\"></polygon>\n<rect fill=\"#FBFCFA\" height=\"70\" rx=\"10\" stroke=\"#18262B\" stroke-width=\"6\" width=\"160\" x=\"160\" y=\"40\"></rect>\n<circle cx=\"195\" cy=\"128\" fill=\"#18262B\" r=\"16\"></circle><circle cx=\"285\" cy=\"128\" fill=\"#18262B\" r=\"16\"></circle>\n<line stroke=\"#2463B8\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"350\" x2=\"640\" y1=\"75\" y2=\"75\"></line>\n<polygon fill=\"#2463B8\" points=\"636,53 680,75 636,97\"></polygon>\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"20\" x2=\"120\" y1=\"300\" y2=\"300\"></line>\n<polygon fill=\"#B4521F\" points=\"116,280 150,300 116,320\"></polygon>\n<rect fill=\"#FBFCFA\" height=\"70\" rx=\"10\" stroke=\"#18262B\" stroke-width=\"6\" width=\"160\" x=\"160\" y=\"270\"></rect>\n<rect fill=\"#9AAAA6\" height=\"50\" stroke=\"#18262B\" stroke-width=\"4\" width=\"64\" x=\"172\" y=\"220\"></rect>\n<rect fill=\"#9AAAA6\" height=\"50\" stroke=\"#18262B\" stroke-width=\"4\" width=\"64\" x=\"244\" y=\"220\"></rect>\n<rect fill=\"#9AAAA6\" height=\"44\" stroke=\"#18262B\" stroke-width=\"4\" width=\"64\" x=\"208\" y=\"176\"></rect>\n<circle cx=\"195\" cy=\"358\" fill=\"#18262B\" r=\"16\"></circle><circle cx=\"285\" cy=\"358\" fill=\"#18262B\" r=\"16\"></circle>\n<line stroke=\"#2463B8\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"350\" x2=\"440\" y1=\"305\" y2=\"305\"></line>\n<polygon fill=\"#2463B8\" points=\"436,283 480,305 436,327\"></polygon>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:30%;text-align:left\">力</th><th style=\"width:30%;text-align:left\">質量</th><th style=\"width:40%;text-align:left\">加速度</th></tr>\n<tr><td>10 N</td><td>2 kg</td><td><b>5 m/s²</b></td></tr>\n<tr><td>10 N</td><td>5 kg</td><td><b>2 m/s²</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>20 N</b></td><td>5 kg</td><td><b>4 m/s²</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">橘色箭頭：推力（大小相同）。藍色箭頭：每台車加速有多快。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 7</p>\n\n</section>", "note": "先遮住最後一欄，讓學生用 a = F ÷ m 自己算：10 ÷ 2 = 5、10 ÷ 5 = 2、20 ÷ 5 = 4。力變 2 倍，加速度也變 2 倍。"}, {"id": "law3", "html": "<section data-transition=\"fade\" id=\"law3\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">牛頓第三定律</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">你推別人，別人也推你</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"兩個溜冰的人互推；橘色箭頭代表大小相等、方向相反的推力，藍色箭頭代表兩人往反方向滑開\" height=\"380\" viewbox=\"0 0 640 380\" width=\"640\">\n<line stroke=\"#9AAAA6\" stroke-width=\"6\" x1=\"20\" x2=\"620\" y1=\"340\" y2=\"340\"></line>\n<circle cx=\"250\" cy=\"110\" fill=\"#FBFCFA\" r=\"26\" stroke=\"#18262B\" stroke-width=\"6\"></circle>\n<line stroke=\"#18262B\" stroke-width=\"8\" x1=\"250\" x2=\"250\" y1=\"136\" y2=\"250\"></line>\n<line stroke=\"#18262B\" stroke-width=\"8\" x1=\"250\" x2=\"316\" y1=\"170\" y2=\"166\"></line>\n<line stroke=\"#18262B\" stroke-width=\"8\" x1=\"250\" x2=\"226\" y1=\"250\" y2=\"320\"></line>\n<line stroke=\"#18262B\" stroke-width=\"8\" x1=\"250\" x2=\"274\" y1=\"250\" y2=\"320\"></line>\n<circle cx=\"390\" cy=\"110\" fill=\"#FBFCFA\" r=\"26\" stroke=\"#18262B\" stroke-width=\"6\"></circle>\n<line stroke=\"#18262B\" stroke-width=\"8\" x1=\"390\" x2=\"390\" y1=\"136\" y2=\"250\"></line>\n<line stroke=\"#18262B\" stroke-width=\"8\" x1=\"390\" x2=\"324\" y1=\"170\" y2=\"166\"></line>\n<line stroke=\"#18262B\" stroke-width=\"8\" x1=\"390\" x2=\"366\" y1=\"250\" y2=\"320\"></line>\n<line stroke=\"#18262B\" stroke-width=\"8\" x1=\"390\" x2=\"414\" y1=\"250\" y2=\"320\"></line>\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"330\" x2=\"400\" y1=\"60\" y2=\"60\"></line>\n<polygon fill=\"#B4521F\" points=\"396,42 430,60 396,78\"></polygon>\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"310\" x2=\"240\" y1=\"60\" y2=\"60\"></line>\n<polygon fill=\"#B4521F\" points=\"244,42 210,60 244,78\"></polygon>\n<line stroke=\"#2463B8\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"180\" x2=\"80\" y1=\"290\" y2=\"290\"></line>\n<polygon fill=\"#2463B8\" points=\"84,272 46,290 84,308\"></polygon>\n<line stroke=\"#2463B8\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"460\" x2=\"560\" y1=\"290\" y2=\"290\"></line>\n<polygon fill=\"#2463B8\" points=\"556,272 594,290 556,308\"></polygon>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">穿溜冰鞋推朋友一下：兩個人都會滑開。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">你推一個東西，它也會用<b>一樣大</b>的力、朝<b>相反方向</b>推回你。</p>\n<p style=\"font-size:36px;font-weight:800;line-height:1.35;background:#FBFCFA;padding:24px 32px;border-radius:16px\">力總是成對出現：大小相等、方向相反，作用在兩個不同的物體上。</p>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">例子：火箭把氣體往下推，氣體就把火箭往上推。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 8</p>\n\n</section>", "note": "其他例子：走路時，腳把地面往後推，地面就把你往前推。游泳時，你把水往後推，水就把你往前推。"}, {"id": "pairs", "html": "<section data-transition=\"fade\" id=\"pairs\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">常見的混淆</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">作用力與反作用力，還是力平衡？</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">比較</th><th style=\"width:33%;text-align:left\">作用力與反作用力</th><th style=\"width:33%;text-align:left\">力平衡</th></tr>\n<tr><td>作用在</td><td><b>兩個</b>不同物體</td><td><b>同一個</b>物體</td></tr>\n<tr><td>大小相同？</td><td>永遠相同</td><td>平衡時相同</td></tr>\n<tr><td>會互相抵消？</td><td>不會（作用在不同物體）</td><td>會，合力 = 0</td></tr>\n<tr style=\"background:#E1ECFA\"><td>例子</td><td>你推牆，牆推你</td><td>重力把書往下拉，桌子把書往上撐</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">快速判斷：</b>問「每個力作用在哪個物體上？」兩個物體 = 作用力與反作用力；同一個物體 = 力平衡。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 9</p>\n\n</section>", "note": "桌上的書是經典陷阱。重力和桌子的支撐力都作用在書上，所以是力平衡，不是作用力與反作用力。重力的反作用力，是書把地球往上拉。"}, {"id": "vt", "html": "<section data-section=\"Reading a velocity–time graph\" data-transition=\"fade\" id=\"vt\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">速度–時間圖</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">從圖上看懂運動</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:860px 1fr;gap:56px;align-items:center;flex:1\">\n<div style=\"position:relative;width:860px;height:560px\">\n<svg aria-label=\"速度–時間圖：前 5 秒速度從 0 直線上升到每秒 20 公尺，之後保持 20 直到第 10 秒；線下方的面積塗成藍色\" height=\"560\" viewbox=\"0 0 860 560\" width=\"860\">\n<polygon fill=\"#C9DBF2\" points=\"120,460 420,140 720,140 720,460\"></polygon>\n<line stroke=\"#18262B\" stroke-width=\"4\" x1=\"120\" x2=\"790\" y1=\"460\" y2=\"460\"></line>\n<line stroke=\"#18262B\" stroke-width=\"4\" x1=\"120\" x2=\"120\" y1=\"460\" y2=\"60\"></line>\n<line stroke=\"#9AAAA6\" stroke-dasharray=\"8 8\" stroke-width=\"2\" x1=\"120\" x2=\"720\" y1=\"140\" y2=\"140\"></line>\n<line stroke=\"#9AAAA6\" stroke-dasharray=\"8 8\" stroke-width=\"2\" x1=\"420\" x2=\"420\" y1=\"460\" y2=\"140\"></line>\n<polyline fill=\"none\" points=\"120,460 420,140 720,140\" stroke=\"#2463B8\" stroke-linejoin=\"round\" stroke-width=\"8\"></polyline>\n</svg>\n<p style=\"position:absolute;left:40px;top:120px;width:70px;font-size:24px;text-align:right\">20</p>\n<p style=\"position:absolute;left:40px;top:440px;width:70px;font-size:24px;text-align:right\">0</p>\n<p style=\"position:absolute;left:400px;top:476px;width:40px;font-size:24px;text-align:center\">5</p>\n<p style=\"position:absolute;left:695px;top:476px;width:50px;font-size:24px;text-align:center\">10</p>\n<p style=\"position:absolute;left:560px;top:516px;width:260px;font-size:24px;color:#4F5F64\">時間（s）</p>\n<p style=\"position:absolute;left:0px;top:20px;width:300px;font-size:24px;color:#4F5F64\">速度（m/s）</p>\n<p style=\"position:absolute;left:130px;top:170px;width:170px;font-size:24px;font-weight:800;color:#2463B8\">越陡 = 加速度越大</p>\n<p style=\"position:absolute;left:450px;top:270px;width:240px;font-size:24px;font-weight:800\">藍色面積 = 距離</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:32px;line-height:1.5\">線的<b style=\"color:#2463B8\">斜率</b> = 加速度。水平線代表等速。</p>\n<p style=\"font-size:32px;line-height:1.5\">線下方的<b style=\"color:#2463B8\">面積</b> = 移動的距離。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 10</p>\n\n</section>", "note": "用手指沿著線走：前 5 秒往上爬（加速），之後變平（等速）。下一張會把數字算出來。"}, {"id": "example", "html": "<section data-transition=\"fade\" id=\"example\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">例題</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">一輛車 5 秒內從 0 加速到 20 m/s，接著以 20 m/s 再開 5 秒。</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">加速度（前 5 秒）</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">a = 20 ÷ 5<br/>  = 4 m/s²</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">距離：三角形</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">½ × 5 × 20<br/>= 50 m</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">距離：長方形</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">5 × 20<br/>= 100 m</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">10 秒內總距離：50 + 100 = <span style=\"color:#2463B8\">150 m</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 11</p>\n\n</section>", "note": "這就是上一張的圖。加速度是斜率：5 秒內速度增加 20 m/s。距離是面積：分成三角形（加速）和長方形（等速）兩塊來算。"}, {"id": "myth", "html": "<section data-section=\"Myth, quiz and summary\" data-transition=\"fade\" id=\"myth\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">越重的東西掉得越快嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">不會。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">重的東西受到的重力比較大，但它也<b>比較難加速</b>（F = ma），兩個效果剛好抵消。</p>\n<p style=\"font-size:34px;line-height:1.5\">沒有空氣阻力時，鐵鎚和羽毛會<b>同時落地</b>。太空人在 1971 年於月球上示範過。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">力與運動 · 12</p>\n\n</section>", "note": "在地球上羽毛掉得慢，只是因為空氣阻力。課堂上可以試：把一張攤平的紙和一本書一起丟（紙掉得慢），再把紙揉成一團一起丟，兩者幾乎同時落地。月球上的示範是阿波羅 15 號太空人大衛・史考特做的。"}, {"id": "quiz", "html": "<section data-transition=\"fade\" id=\"quiz\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">小測驗 · 是非題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:34px;line-height:1.5\">在地上滾動的球，一定要一直有力推著它。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:34px;line-height:1.5\">用同樣的力推，2 kg 的推車比 4 kg 的推車加速更快。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:34px;line-height:1.5\">馬能把車往前拉，是因為車往後拉馬的力比較小。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">力與運動 · 13</p>\n\n</section>", "note": "先讓學生自己作答。第 3 題最難，先讓他們討論再公布答案。"}, {"id": "answers", "html": "<section data-transition=\"fade\" id=\"answers\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:800\">錯</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">慣性讓它繼續滾，是摩擦力讓它慢下來。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:800\">對</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">a = F ÷ m，質量越小，加速度越大。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:800\">錯</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">作用力與反作用力永遠一樣大。車會動，是因為作用在車上的合力不是零。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">沒有合力，運動狀態就不會改變。<br/><span style=\"color:#E58A55\">F = ma，而且力總是成對出現。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">力與運動 · 14</p>\n\n</section>", "note": "第 3 題：馬拉車和車拉馬的力一樣大。車會往前，是因為馬拉車的力大於擋住車的摩擦力；馬會往前，是因為地面往前推馬的力大於車往後拉馬的力。"}]}, "force-motion-en": {"title": "Force & Motion", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">PHYSICS</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Force &amp;<br>Motion</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">Why do things move, and why do they stop?<br>Three rules explain it all.</p>\n</div>\n<svg aria-label=\"A hand pushes a cart to the right; an orange arrow shows the force and a blue arrow shows the cart speeding up\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<line x1=\"20\" y1=\"400\" x2=\"700\" y2=\"400\" stroke=\"#6D7F7B\" stroke-width=\"8\"/>\n<rect x=\"240\" y=\"230\" width=\"260\" height=\"130\" rx=\"16\" fill=\"#F3F5F2\"/>\n<rect x=\"270\" y=\"200\" width=\"200\" height=\"40\" rx=\"10\" fill=\"#BFCDC9\"/>\n<circle cx=\"300\" cy=\"380\" r=\"22\" fill=\"#18262B\" stroke=\"#F3F5F2\" stroke-width=\"8\"/>\n<circle cx=\"440\" cy=\"380\" r=\"22\" fill=\"#18262B\" stroke=\"#F3F5F2\" stroke-width=\"8\"/>\n<line x1=\"40\" y1=\"295\" x2=\"190\" y2=\"295\" stroke=\"#E58A55\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n<polygon points=\"186,265 236,295 186,325\" fill=\"#E58A55\"/>\n<line x1=\"530\" y1=\"130\" x2=\"650\" y2=\"130\" stroke=\"#7FB0F2\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"646,106 690,130 646,154\" fill=\"#7FB0F2\"/>\n<line x1=\"530\" y1=\"170\" x2=\"610\" y2=\"170\" stroke=\"#7FB0F2\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.6\"/>\n<line x1=\"530\" y1=\"90\" x2=\"590\" y2=\"90\" stroke=\"#7FB0F2\" stroke-width=\"12\" stroke-linecap=\"round\" opacity=\"0.6\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied physics. We start from everyday experiences, like being thrown forward when a bus brakes, and build up to Newton’s three laws."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why do you lurch forward when the bus brakes?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 3 2 21h20L12 3zM12 10v5M12 18h.01\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">The bus stops</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">The brakes push on the bus and slow it down. <b style=\"color:#18262B\">Nothing pushes you backward.</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Your body keeps going</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Your body was moving at the bus’s speed, and it <b style=\"color:#18262B\">wants to keep moving</b>.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">No one shoved you. That feeling has a name, and it’s the first of three rules we’ll learn today.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 2</p>\n\n</section>", "note": "Ask students first: what pushed you forward? Most will say “the bus” or “the brakes.” The surprise is that nothing pushed you forward at all. Your body simply kept moving. That is inertia, Newton’s first law."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M6 4l14 8-14 8z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Explain inertia</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Say why moving things keep moving and still things stay still.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Use F = ma</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Work out acceleration from a force and a mass.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Spot force pairs</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Find the action–reaction pair in a push or a pull.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 3</p>\n\n</section>", "note": "The three goals match Newton’s three laws. After the laws, we read a velocity–time graph, bust a common myth and finish with a quick quiz."}, {"id": "basics", "html": "<section id=\"basics\" data-section=\"Before you start: speed, acceleration and force\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BEFORE YOU START</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Four words you need first</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Speed</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">How far you go each second. <b style=\"color:#18262B\">10 m/s</b> means 10 meters every second.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Acceleration</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">How much speed changes each second. 0 → 10 → 20 m/s is <b style=\"color:#18262B\">10 m/s²</b>.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Force</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">A push or a pull, measured in <b style=\"color:#18262B\">newtons (N)</b>. Holding an apple takes about 1 N.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Net force</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">All the forces added up. 5 N left + 5 N right = <b style=\"color:#18262B\">0 N</b>.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 4</p>\n\n</section>", "note": "Blue cards describe motion; orange cards describe what causes it. “Net force” is the key idea for the laws that follow: if the pushes cancel out, the net force is zero."}, {"id": "law1", "html": "<section id=\"law1\" data-section=\"Newton’s three laws of motion\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">NEWTON’S FIRST LAW</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Inertia: things keep doing what they’re doing</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A card is pulled quickly out from under a cup on a table; the cup stays where it was\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"40\" y=\"250\" width=\"440\" height=\"20\" fill=\"#18262B\"/>\n<rect x=\"70\" y=\"270\" width=\"18\" height=\"90\" fill=\"#18262B\"/>\n<rect x=\"432\" y=\"270\" width=\"18\" height=\"90\" fill=\"#18262B\"/>\n<rect x=\"150\" y=\"238\" width=\"420\" height=\"12\" fill=\"#9AAAA6\"/>\n<polygon points=\"200,120 290,120 280,238 210,238\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"490\" y1=\"200\" x2=\"580\" y2=\"200\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"576,178 616,200 576,222\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Pull the card out fast: the cup stays put.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">Objects are “lazy.” A still object stays still. A moving object keeps going at the <b>same speed in a straight line</b>.</p>\n<p style=\"font-size:40px;font-weight:800;line-height:1.35;background:#FBFCFA;padding:24px 32px;border-radius:16px\">No net force → no change in motion</p>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\"><b style=\"color:#B4521F\">Myth:</b> a moving object needs a constant push.<br><b style=\"color:#2463B8\">Fact:</b> a hockey puck glides on its own. It only stops because friction slows it down.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 5</p>\n\n</section>", "note": "Do the card-and-cup trick live if you can. Back to the bus: your body kept moving because no force stopped it, so you lurched forward. On ice with almost no friction, a puck slides a very long way."}, {"id": "law2", "html": "<section id=\"law2\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">NEWTON’S SECOND LAW</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">F</p>\n<p style=\"font-size:32px;color:#BFCDC9\">force (N)</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">m</p>\n<p style=\"font-size:32px;color:#BFCDC9\">mass (kg)</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">a</p>\n<p style=\"font-size:32px;color:#BFCDC9\">acceleration (m/s²)</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">Push harder → speeds up faster.<br>Heavier object → speeds up slower.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">To find acceleration, flip it around: <b style=\"color:#7FB0F2\">a = F ÷ m</b></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Force &amp; Motion · 6</p>\n\n</section>", "note": "The formula just writes down what students already feel. Pushing an empty shopping cart vs. a full one is the best everyday example. Most problems ask for acceleration, so practice a = F ÷ m."}, {"id": "law2b", "html": "<section id=\"law2b\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">TRY THE NUMBERS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Same push, different mass</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"Two carts each pushed with the same orange force arrow; the empty cart has a long blue arrow showing fast speed-up, the loaded cart has a short blue arrow\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<line x1=\"20\" y1=\"70\" x2=\"120\" y2=\"70\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"116,50 150,70 116,90\" fill=\"#B4521F\"/>\n<rect x=\"160\" y=\"40\" width=\"160\" height=\"70\" rx=\"10\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"195\" cy=\"128\" r=\"16\" fill=\"#18262B\"/><circle cx=\"285\" cy=\"128\" r=\"16\" fill=\"#18262B\"/>\n<line x1=\"350\" y1=\"75\" x2=\"640\" y2=\"75\" stroke=\"#2463B8\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"636,53 680,75 636,97\" fill=\"#2463B8\"/>\n<line x1=\"20\" y1=\"300\" x2=\"120\" y2=\"300\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"116,280 150,300 116,320\" fill=\"#B4521F\"/>\n<rect x=\"160\" y=\"270\" width=\"160\" height=\"70\" rx=\"10\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<rect x=\"172\" y=\"220\" width=\"64\" height=\"50\" fill=\"#9AAAA6\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<rect x=\"244\" y=\"220\" width=\"64\" height=\"50\" fill=\"#9AAAA6\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<rect x=\"208\" y=\"176\" width=\"64\" height=\"44\" fill=\"#9AAAA6\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<circle cx=\"195\" cy=\"358\" r=\"16\" fill=\"#18262B\"/><circle cx=\"285\" cy=\"358\" r=\"16\" fill=\"#18262B\"/>\n<line x1=\"350\" y1=\"305\" x2=\"440\" y2=\"305\" stroke=\"#2463B8\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<polygon points=\"436,283 480,305 436,327\" fill=\"#2463B8\"/>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:30%;text-align:left\">Force</th><th style=\"width:30%;text-align:left\">Mass</th><th style=\"width:40%;text-align:left\">Acceleration</th></tr>\n<tr><td>10 N</td><td>2 kg</td><td><b>5 m/s²</b></td></tr>\n<tr><td>10 N</td><td>5 kg</td><td><b>2 m/s²</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>20 N</b></td><td>5 kg</td><td><b>4 m/s²</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Orange arrows: the push (same size). Blue arrows: how fast each cart speeds up.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 7</p>\n\n</section>", "note": "Cover the last column and let students compute each row with a = F ÷ m: 10 ÷ 2 = 5, 10 ÷ 5 = 2, 20 ÷ 5 = 4. Doubling the force doubles the acceleration."}, {"id": "law3", "html": "<section id=\"law3\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">NEWTON’S THIRD LAW</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Every push gets pushed back</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Two skaters push each other; orange arrows show equal pushes in opposite directions and blue arrows show both skaters sliding apart\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<line x1=\"20\" y1=\"340\" x2=\"620\" y2=\"340\" stroke=\"#9AAAA6\" stroke-width=\"6\"/>\n<circle cx=\"250\" cy=\"110\" r=\"26\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"250\" y1=\"136\" x2=\"250\" y2=\"250\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"250\" y1=\"170\" x2=\"316\" y2=\"166\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"250\" y1=\"250\" x2=\"226\" y2=\"320\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"250\" y1=\"250\" x2=\"274\" y2=\"320\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<circle cx=\"390\" cy=\"110\" r=\"26\" fill=\"#FBFCFA\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"390\" y1=\"136\" x2=\"390\" y2=\"250\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"390\" y1=\"170\" x2=\"324\" y2=\"166\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"390\" y1=\"250\" x2=\"366\" y2=\"320\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"390\" y1=\"250\" x2=\"414\" y2=\"320\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"330\" y1=\"60\" x2=\"400\" y2=\"60\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"396,42 430,60 396,78\" fill=\"#B4521F\"/>\n<line x1=\"310\" y1=\"60\" x2=\"240\" y2=\"60\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"244,42 210,60 244,78\" fill=\"#B4521F\"/>\n<line x1=\"180\" y1=\"290\" x2=\"80\" y2=\"290\" stroke=\"#2463B8\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"84,272 46,290 84,308\" fill=\"#2463B8\"/>\n<line x1=\"460\" y1=\"290\" x2=\"560\" y2=\"290\" stroke=\"#2463B8\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"556,272 594,290 556,308\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Push a friend on skates: you both slide apart.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">When you push something, it pushes back on you <b>just as hard</b>, in the <b>opposite direction</b>.</p>\n<p style=\"font-size:36px;font-weight:800;line-height:1.35;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Forces come in pairs: equal size, opposite direction, on two different objects.</p>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Example: a rocket pushes gas down, and the gas pushes the rocket up.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 8</p>\n\n</section>", "note": "Other examples: when you walk, your foot pushes the ground backward and the ground pushes you forward. When you swim, you push water back and the water pushes you ahead."}, {"id": "pairs", "html": "<section id=\"pairs\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">A COMMON MIX-UP</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Force pair or balanced forces?</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">Compare</th><th style=\"width:33%;text-align:left\">Action–reaction pair</th><th style=\"width:33%;text-align:left\">Balanced forces</th></tr>\n<tr><td>Acts on</td><td><b>Two</b> different objects</td><td><b>One</b> object</td></tr>\n<tr><td>Same size?</td><td>Always</td><td>Yes, when balanced</td></tr>\n<tr><td>Cancel out?</td><td>No (different objects)</td><td>Yes, net force = 0</td></tr>\n<tr style=\"background:#E1ECFA\"><td>Example</td><td>You push the wall, the wall pushes you</td><td>Gravity pulls a book down, the table holds it up</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">Quick test:</b> ask “which object does each force act on?” Two objects = a pair. One object = balanced.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 9</p>\n\n</section>", "note": "The book on a table is the classic trap. Gravity and the table’s push both act on the book, so they are balanced forces, not an action–reaction pair. The book’s reaction partner to gravity is the book pulling Earth up."}, {"id": "vt", "html": "<section id=\"vt\" data-section=\"Reading a velocity–time graph\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">VELOCITY–TIME GRAPH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Read motion from a picture</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:860px 1fr;gap:56px;align-items:center;flex:1\">\n<div style=\"position:relative;width:860px;height:560px\">\n<svg aria-label=\"Velocity–time graph: speed rises in a straight line from 0 to 20 meters per second in the first 5 seconds, then stays flat at 20 until 10 seconds; the area under the line is shaded blue\" width=\"860\" height=\"560\" viewBox=\"0 0 860 560\">\n<polygon points=\"120,460 420,140 720,140 720,460\" fill=\"#C9DBF2\"/>\n<line x1=\"120\" y1=\"460\" x2=\"790\" y2=\"460\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<line x1=\"120\" y1=\"460\" x2=\"120\" y2=\"60\" stroke=\"#18262B\" stroke-width=\"4\"/>\n<line x1=\"120\" y1=\"140\" x2=\"720\" y2=\"140\" stroke=\"#9AAAA6\" stroke-width=\"2\" stroke-dasharray=\"8 8\"/>\n<line x1=\"420\" y1=\"460\" x2=\"420\" y2=\"140\" stroke=\"#9AAAA6\" stroke-width=\"2\" stroke-dasharray=\"8 8\"/>\n<polyline points=\"120,460 420,140 720,140\" fill=\"none\" stroke=\"#2463B8\" stroke-width=\"8\" stroke-linejoin=\"round\"/>\n</svg>\n<p style=\"position:absolute;left:40px;top:120px;width:70px;font-size:24px;text-align:right\">20</p>\n<p style=\"position:absolute;left:40px;top:440px;width:70px;font-size:24px;text-align:right\">0</p>\n<p style=\"position:absolute;left:400px;top:476px;width:40px;font-size:24px;text-align:center\">5</p>\n<p style=\"position:absolute;left:695px;top:476px;width:50px;font-size:24px;text-align:center\">10</p>\n<p style=\"position:absolute;left:560px;top:516px;width:260px;font-size:24px;color:#4F5F64\">time (s)</p>\n<p style=\"position:absolute;left:0px;top:20px;width:300px;font-size:24px;color:#4F5F64\">speed (m/s)</p>\n<p style=\"position:absolute;left:130px;top:170px;width:170px;font-size:24px;font-weight:800;color:#2463B8\">steeper = bigger acceleration</p>\n<p style=\"position:absolute;left:450px;top:270px;width:240px;font-size:24px;font-weight:800\">blue area = distance</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#2463B8\">Slope</b> of the line = acceleration. A flat line means constant speed.</p>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#2463B8\">Area</b> under the line = distance traveled.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 10</p>\n\n</section>", "note": "Trace the line with your finger: it climbs for 5 seconds (speeding up), then goes flat (steady speed). The next slide works out the numbers."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">A car goes from 0 to 20 m/s in 5 s, then cruises at 20 m/s for 5 s.</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Acceleration (first 5 s)</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">a = 20 ÷ 5<br>&#160;&#160;= 4 m/s²</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Distance: triangle</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">½ × 5 × 20<br>= 50 m</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Distance: rectangle</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:30px;line-height:1.6\">5 × 20<br>= 100 m</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Total distance in 10 s: 50 + 100 = <span style=\"color:#2463B8\">150 m</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 11</p>\n\n</section>", "note": "This is the graph from the previous slide. Acceleration is the slope: speed rose by 20 m/s in 5 s. Distance is the area: split it into a triangle (speeding up) and a rectangle (steady speed)."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Do heavier objects fall faster?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">A heavy object gets a bigger pull from gravity, but it is also <b>harder to speed up</b> (F = ma). The two effects cancel out.</p>\n<p style=\"font-size:34px;line-height:1.5\">Without air resistance, a hammer and a feather <b>land together</b>. Astronauts showed this on the Moon in 1971.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Force &amp; Motion · 12</p>\n\n</section>", "note": "On Earth a feather falls slowly only because of air resistance. Try it in class: drop a flat sheet of paper and a book (paper falls slowly), then crumple the paper into a ball and drop both again. They land at almost the same time. The Moon demonstration was by Apollo 15 astronaut David Scott."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK · TRUE OR FALSE?</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">A ball rolling on the floor must have a force pushing it the whole time.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">With the same push, a 2 kg cart speeds up faster than a 4 kg cart.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">A horse pulls a cart forward because the cart pulls back on the horse more weakly.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Force &amp; Motion · 13</p>\n\n</section>", "note": "Let students answer on their own first. Q3 is the hardest; let them argue about it before revealing the answer."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">False</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Inertia keeps it rolling. Friction is what slows it down.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">True</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">a = F ÷ m, so less mass means more acceleration.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">False</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">The pair is always equal. The cart moves because the net force on the cart is not zero.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Things keep moving unless a net force acts.<br><span style=\"color:#E58A55\">F = ma, and every force comes in a pair.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Force &amp; Motion · 14</p>\n\n</section>", "note": "For Q3: the horse pulls the cart and the cart pulls the horse with equal force. The cart moves because the horse’s pull on it is bigger than the friction holding it back. The horse moves because the ground pushes it forward harder than the cart pulls it back."}]}, "circuits-zh": {"title": "電路與歐姆定律", "lang": "zh", "slides": [{"id": "cover", "html": "<section data-transition=\"fade\" id=\"cover\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">物理</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.1;color:#F3F5F2\">電路與<br/>歐姆定律</h1>\n<p style=\"font-size:32px;line-height:1.5;color:#BFCDC9\">從零開始：電是怎麼在電線裡跑的？</p>\n</div>\n<svg aria-label=\"一顆電池接著一顆發亮的燈泡，電子沿著電線繞圈\" height=\"480\" viewbox=\"0 0 720 480\" width=\"720\">\n<path d=\"M90 90 H630 V400 H90 Z\" fill=\"none\" stroke=\"#6D7F7B\" stroke-linejoin=\"round\" stroke-width=\"10\"></path>\n<rect fill=\"#18262B\" height=\"80\" width=\"60\" x=\"60\" y=\"200\"></rect>\n<rect fill=\"#F3F5F2\" height=\"12\" width=\"80\" x=\"50\" y=\"214\"></rect>\n<rect fill=\"#F3F5F2\" height=\"12\" width=\"44\" x=\"68\" y=\"250\"></rect>\n<circle cx=\"360\" cy=\"90\" fill=\"#FFC94D\" r=\"46\" stroke=\"#F3F5F2\" stroke-width=\"6\"></circle>\n<path d=\"M340 100 L352 76 L368 100 L380 76\" fill=\"none\" stroke=\"#18262B\" stroke-linejoin=\"round\" stroke-width=\"5\"></path>\n<line stroke=\"#FFC94D\" stroke-linecap=\"round\" stroke-width=\"8\" x1=\"360\" x2=\"360\" y1=\"22\" y2=\"0\"></line>\n<line stroke=\"#FFC94D\" stroke-linecap=\"round\" stroke-width=\"8\" x1=\"420\" x2=\"438\" y1=\"40\" y2=\"24\"></line>\n<line stroke=\"#FFC94D\" stroke-linecap=\"round\" stroke-width=\"8\" x1=\"300\" x2=\"282\" y1=\"40\" y2=\"24\"></line>\n<line opacity=\"0\" stroke=\"#FFC94D\" stroke-linecap=\"round\" stroke-width=\"8\" x1=\"440\" x2=\"466\" y1=\"90\" y2=\"90\"></line>\n<circle cx=\"200\" cy=\"90\" fill=\"#E58A55\" r=\"12\"></circle>\n<circle cx=\"520\" cy=\"90\" fill=\"#E58A55\" r=\"12\"></circle>\n<circle cx=\"630\" cy=\"220\" fill=\"#E58A55\" r=\"12\"></circle>\n<circle cx=\"500\" cy=\"400\" fill=\"#E58A55\" r=\"12\"></circle>\n<circle cx=\"300\" cy=\"400\" fill=\"#E58A55\" r=\"12\"></circle>\n<circle cx=\"90\" cy=\"340\" fill=\"#E58A55\" r=\"12\"></circle>\n</svg>\n\n</section>", "note": "這一課給完全沒學過電的同學。我們不背公式，先用水管來想像電路，再看一個很有名的公式，最後解開聖誕燈串的謎題。"}, {"id": "hook", "html": "<section data-transition=\"fade\" id=\"hook\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">一顆燈泡壞了，為什麼整串都熄掉？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">老式聖誕燈串</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">其中一顆燈泡壞掉，<b style=\"color:#18262B\">整串全部一起熄滅</b>，要一顆一顆換才找得到是哪顆壞了。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M3 10.5 12 3l9 7.5V21H3zM9 21v-6h6v6\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">家裡的燈和電器</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">房間的燈關掉，<b style=\"color:#18262B\">冰箱、電視照樣運轉</b>，每一個都可以分開開關。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">同樣是接電，差別在<b style=\"color:#B4521F\">「接法」</b>。看完這份簡報，你就知道答案。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 2</p>\n\n</section>", "note": "先讓學生猜：為什麼一個會全滅，一個各管各的？很多人會猜「聖誕燈比較便宜」。答案是接法不同，我們在後半段揭曉。要看懂接法，得先認識電路裡的三個主角。"}, {"id": "goals", "html": "<section data-transition=\"fade\" id=\"goals\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">認識三個主角</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">說出電壓、電流、電阻各自代表什麼。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">會用歐姆定律</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">知道電壓和電阻，就能算出電流。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 10.5 12 3l9 7.5V21H3zM9 21v-6h6v6\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">分辨串聯與並聯</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">解釋聖誕燈串和家裡電器的差別。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 3</p>\n\n</section>", "note": "三個目標對應簡報的三段：水管比喻、歐姆定律、串聯並聯。最後還有一個常見迷思和三題小測驗。"}, {"id": "water", "html": "<section data-section=\"用水管比喻認識電壓、電流、電阻三個主角\" data-transition=\"fade\" id=\"water\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">把電路想成水管</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">電路就像一圈裝滿水的水管</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"一圈水管，左邊有抽水馬達推水，上方有一段變細的管子，水沿著管子繞圈流動\" height=\"420\" viewbox=\"0 0 640 420\" width=\"640\">\n<path d=\"M80 70 H560 V360 H80 Z\" fill=\"none\" stroke=\"#9CC0EA\" stroke-linejoin=\"round\" stroke-width=\"44\"></path>\n<path d=\"M80 70 H560 V360 H80 Z\" fill=\"none\" stroke=\"#2463B8\" stroke-dasharray=\"18 22\" stroke-linejoin=\"round\" stroke-width=\"6\"></path>\n<rect fill=\"#E7EEEA\" height=\"52\" width=\"140\" x=\"250\" y=\"44\"></rect>\n<rect fill=\"#9CC0EA\" height=\"20\" stroke=\"#B4521F\" stroke-width=\"5\" width=\"140\" x=\"250\" y=\"60\"></rect>\n<circle cx=\"80\" cy=\"215\" fill=\"#18262B\" r=\"62\"></circle>\n<path d=\"M58 245 L80 180 L102 245 Z\" fill=\"#E58A55\"></path>\n<polygon fill=\"#2463B8\" points=\"470,345 500,360 470,375\"></polygon>\n<polygon fill=\"#2463B8\" points=\"170,85 140,70 170,55\"></polygon>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">馬達推水，水在管子裡繞圈；上方細管就是燈泡。</p>\n</div>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:42%;text-align:left\">水管世界</th><th style=\"width:58%;text-align:left\">電路世界</th></tr>\n<tr><td>抽水馬達</td><td><b>電池</b></td></tr>\n<tr><td>水管</td><td><b>電線</b></td></tr>\n<tr><td>管子裡的水</td><td><b>電子</b></td></tr>\n<tr><td>一段變細的管子</td><td><b>燈泡</b>（電阻）</td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:24px 32px;border-radius:16px\">重點：電線裡<b style=\"color:#B4521F\">本來就擠滿電子</b>。電池不是生出電子，而是「推」它們。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 4</p>\n\n</section>", "note": "學生常以為電池會「生出」電。強調：金屬電線裡本來就有大量電子，就像水管本來就裝滿水。電池只是負責推。這一點到最後破解迷思時會再用到。"}, {"id": "three", "html": "<section data-transition=\"fade\" id=\"three\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">電路的三個主角</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#B4521F\">V</p>\n<h3 style=\"font-size:44px;font-weight:700\">電壓</h3>\n<p style=\"font-size:32px;color:#4F5F64\">單位：伏特（V）</p>\n<p style=\"font-size:32px;line-height:1.5\"><b>推力</b>：馬達推水的力道，也就是水壓。</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">一顆電池 1.5 V，家裡插座約 110 V。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#2463B8\">I</p>\n<h3 style=\"font-size:44px;font-weight:700\">電流</h3>\n<p style=\"font-size:32px;color:#4F5F64\">單位：安培（A）</p>\n<p style=\"font-size:32px;line-height:1.5\"><b>流量</b>：每秒有多少水流過同一個點。</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">流得越多，燈泡越亮。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #18262B;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#18262B\">R</p>\n<h3 style=\"font-size:44px;font-weight:700\">電阻</h3>\n<p style=\"font-size:32px;color:#4F5F64\">單位：歐姆（Ω）</p>\n<p style=\"font-size:32px;line-height:1.5\"><b>阻擋</b>：管子變細或塞住，水很難通過。</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">燈泡就是一個電阻，燈絲被擠得發熱發亮。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 5</p>\n\n</section>", "note": "一句話記住：電壓是推力、電流是流量、電阻是阻擋。單位分別是伏特、安培、歐姆。"}, {"id": "intuition", "html": "<section data-transition=\"fade\" id=\"intuition\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先用直覺猜猜看</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">推力和阻擋，怎麼影響流量？</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:40px;flex:1;justify-content:center\">\n<div style=\"display:flex;align-items:center;gap:40px\">\n<p style=\"flex:1;font-size:44px;font-weight:700;background:#F7E6DC;padding:40px 48px;border-radius:20px\">馬達推得更用力<br/><span style=\"color:#B4521F\">電壓變大</span></p>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#4F5F64;width:120px;height:60px\"></div>\n<p style=\"flex:1;font-size:44px;font-weight:700;background:#E1ECFA;padding:40px 48px;border-radius:20px\">水流變多<br/><span style=\"color:#2463B8\">電流變大</span></p>\n</div>\n<div style=\"display:flex;align-items:center;gap:40px\">\n<p style=\"flex:1;font-size:44px;font-weight:700;background:#E4E8E6;padding:40px 48px;border-radius:20px\">管子塞得更嚴重<br/><span style=\"color:#18262B\">電阻變大</span></p>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#4F5F64;width:120px;height:60px\"></div>\n<p style=\"flex:1;font-size:44px;font-weight:700;background:#E1ECFA;padding:40px 48px;border-radius:20px\">水流變少<br/><span style=\"color:#2463B8\">電流變小</span></p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">你剛剛用直覺說出的，正是一條物理定律。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 6</p>\n\n</section>", "note": "先讓學生回答兩個問題再翻出答案：馬達推得更用力，水流會怎樣？管子塞得更嚴重呢？大多數人都答得出來，這就是歐姆定律的直覺。"}, {"id": "law", "html": "<section data-section=\"歐姆定律 V = IR，並用一題數字慢慢算\" data-transition=\"fade\" id=\"law\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">歐姆定律</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">V</p>\n<p style=\"font-size:32px;color:#BFCDC9\">電壓</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">I</p>\n<p style=\"font-size:32px;color:#BFCDC9\">電流</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">R</p>\n<p style=\"font-size:32px;color:#BFCDC9\">電阻</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">想求電流？<span style=\"color:#7FB0F2\">I = V ÷ R</span>　推力 ÷ 阻擋 = 流量</p>\n<p style=\"font-size:24px;line-height:1.5;color:#BFCDC9\">為什麼電流用 I 表示？它來自法文的「強度」一詞，是歷史留下來的習慣。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">電路與歐姆定律 · 7</p>\n\n</section>", "note": "德國科學家歐姆在大約兩百年前，把剛才的直覺寫成公式。公式只有三個字母，不用怕。重點是會倒過來用：要找電流，就用電壓除以電阻。"}, {"id": "example", "html": "<section data-transition=\"fade\" id=\"example\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">例題</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.2\">9 伏特的電池接上 3 歐姆的燈泡，電流是多少？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">寫下已知</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">V = 9 V<br/>R = 3 Ω</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">選公式</h3>\n<p style=\"font-size:32px;line-height:1.6\">要找電流，所以用<br/><b style=\"font-family:'JetBrains Mono', 'Courier New', monospace\">I = V ÷ R</b></p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">代入計算</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">I = 9 ÷ 3<br/>  = 3</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">加上單位</h3>\n<p style=\"font-size:32px;line-height:1.6\">電流的單位是安培<br/><b style=\"font-family:'JetBrains Mono', 'Courier New', monospace\">3 A</b></p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">答案：電流是 <span style=\"color:#2463B8\">3 安培</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 8</p>\n\n</section>", "note": "帶學生一步一步做。第一步永遠是先把知道的寫下來，第二步才選公式。最後別忘了單位，電流是安培。"}, {"id": "vary", "html": "<section data-transition=\"fade\" id=\"vary\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">換你試試</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">只改一個數字，電流會怎麼變？</h2>\n</div>\n<table style=\"font-size:36px;color:#18262B\">\n<tr><th style=\"width:20%;text-align:left\">電池電壓</th><th style=\"width:20%;text-align:left\">燈泡電阻</th><th style=\"width:16%;text-align:left\">電流</th><th style=\"width:44%;text-align:left\">發生了什麼</th></tr>\n<tr><td>9 V</td><td>3 Ω</td><td><b>3 A</b></td><td>原本的例題</td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>18 V</b></td><td>3 Ω</td><td><b>6 A</b></td><td>電壓變 2 倍 → 電流也變 2 倍</td></tr>\n<tr style=\"background:#E1ECFA\"><td>9 V</td><td><b>9 Ω</b></td><td><b>1 A</b></td><td>電阻變 3 倍 → 電流變成 1/3</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">公式只是把直覺寫成數學：<br/><span style=\"color:#B4521F\">電壓越大，電流越大；電阻越大，電流越小。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 9</p>\n\n</section>", "note": "先遮住電流那一欄，讓學生自己算：18 除以 3 等於 6；9 除以 9 等於 1。再請他們說出規律。"}, {"id": "series", "html": "<section data-section=\"串聯與並聯：燈泡的兩種接法\" data-transition=\"fade\" id=\"series\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">接法一</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">串聯：只有一條路</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"串聯電路：電池和三顆燈泡排在同一圈電線上，中間那顆燈泡壞掉打叉，三顆燈泡全部熄滅\" height=\"420\" viewbox=\"0 0 760 420\" width=\"760\">\n<path d=\"M70 90 H690 V360 H70 Z\" fill=\"none\" stroke=\"#6D7F7B\" stroke-linejoin=\"round\" stroke-width=\"10\"></path>\n<rect fill=\"#E7EEEA\" height=\"90\" width=\"60\" x=\"40\" y=\"180\"></rect>\n<rect fill=\"#18262B\" height=\"12\" width=\"80\" x=\"30\" y=\"196\"></rect>\n<rect fill=\"#18262B\" height=\"12\" width=\"44\" x=\"48\" y=\"236\"></rect>\n<circle cx=\"220\" cy=\"90\" fill=\"#C9D2CF\" r=\"44\" stroke=\"#18262B\" stroke-width=\"6\"></circle>\n<circle cx=\"380\" cy=\"90\" fill=\"#C9D2CF\" r=\"44\" stroke=\"#18262B\" stroke-width=\"6\"></circle>\n<circle cx=\"540\" cy=\"90\" fill=\"#C9D2CF\" r=\"44\" stroke=\"#18262B\" stroke-width=\"6\"></circle>\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"350\" x2=\"410\" y1=\"60\" y2=\"120\"></line>\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"410\" x2=\"350\" y1=\"60\" y2=\"120\"></line>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">中間那顆壞了，三顆全部熄滅。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:36px;line-height:1.5\">燈泡一個接一個排成一條線，像<b>糖葫蘆</b>串在同一根竹籤上。</p>\n<p style=\"font-size:36px;line-height:1.5\">一顆壞掉，就像水管中間被剪斷：<b style=\"color:#B4521F\">整條路不通，全部熄滅</b>。</p>\n<p style=\"font-size:36px;line-height:1.5\">燈泡越多，阻擋加起來越大，<b>每一顆越暗</b>。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">例子：老式聖誕燈串。（現在很多燈串有設計可以繞過壞掉的燈泡。）</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 10</p>\n\n</section>", "note": "回到開場的謎題。串聯只有一條路，水要依序穿過每個燈泡。中間一顆燈絲斷了，整圈都流不動，所以全部熄滅。"}, {"id": "parallel", "html": "<section data-transition=\"fade\" id=\"parallel\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">接法二</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">並聯：很多條路</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"並聯電路：電池接出上下兩條主線，中間分出三條分支各接一顆燈泡；中間分支的燈泡壞掉打叉，左右兩顆仍然發亮\" height=\"420\" viewbox=\"0 0 760 420\" width=\"760\">\n<path d=\"M70 60 H690 M70 360 H690 M70 60 V360\" fill=\"none\" stroke=\"#6D7F7B\" stroke-linecap=\"round\" stroke-width=\"10\"></path>\n<path d=\"M260 60 V360 M460 60 V360 M660 60 V360\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\"></path>\n<rect fill=\"#E7EEEA\" height=\"90\" width=\"60\" x=\"40\" y=\"160\"></rect>\n<rect fill=\"#18262B\" height=\"12\" width=\"80\" x=\"30\" y=\"176\"></rect>\n<rect fill=\"#18262B\" height=\"12\" width=\"44\" x=\"48\" y=\"216\"></rect>\n<circle cx=\"260\" cy=\"210\" fill=\"#F2B630\" r=\"44\" stroke=\"#18262B\" stroke-width=\"6\"></circle>\n<circle cx=\"460\" cy=\"210\" fill=\"#C9D2CF\" r=\"44\" stroke=\"#18262B\" stroke-width=\"6\"></circle>\n<circle cx=\"660\" cy=\"210\" fill=\"#F2B630\" r=\"44\" stroke=\"#18262B\" stroke-width=\"6\"></circle>\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"430\" x2=\"490\" y1=\"180\" y2=\"240\"></line>\n<line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"490\" x2=\"430\" y1=\"180\" y2=\"240\"></line>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">中間那顆壞了，左右兩顆照樣亮。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:36px;line-height:1.5\">從主線分出很多條分支，像高速公路的<b>交流道</b>，每條分支各接一顆燈泡。</p>\n<p style=\"font-size:36px;line-height:1.5\">一條分支壞了，只有那條沒電：<b style=\"color:#2463B8\">其他照樣亮</b>。</p>\n<p style=\"font-size:36px;line-height:1.5\">每條分支都直接接到電池兩端，<b>每顆燈泡都拿到全部的電壓</b>。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">例子：家裡的燈、冰箱、電視，教室裡的日光燈。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 11</p>\n\n</section>", "note": "關掉房間的燈，冰箱不會停，這不是理所當然，而是因為家裡的電器刻意用並聯接法。"}, {"id": "compare", "html": "<section data-transition=\"fade\" id=\"compare\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一張表看懂</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">串聯和並聯，差在哪裡？</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:36%;text-align:left\">比較</th><th style=\"width:32%;text-align:left\">串聯（糖葫蘆）</th><th style=\"width:32%;text-align:left\">並聯（交流道）</th></tr>\n<tr><td>電流的路有幾條</td><td>一條</td><td>很多條</td></tr>\n<tr><td>一顆燈泡壞掉</td><td><span style=\"color:#B4521F\">全部熄滅</span></td><td><span style=\"color:#2463B8\">其他照樣亮</span></td></tr>\n<tr><td>每顆燈泡的電壓</td><td>大家平分</td><td>全部的電壓</td></tr>\n<tr><td>兩顆相同燈泡的亮度</td><td>比較暗</td><td>比較亮</td></tr>\n<tr><td>生活例子</td><td>老式聖誕燈串</td><td>家裡的電器</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:36px;font-weight:700;line-height:1.4\">一句話記住：串聯是「一條路，一個壞全部停」；並聯是「很多條路，各管各的」。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 12</p>\n\n</section>", "note": "亮度題先讓學生預測：兩顆一樣的燈泡接同一顆電池，並聯的每顆燈泡拿到全部電壓，串聯的要平分，所以並聯比較亮。"}, {"id": "breaker", "html": "<section data-transition=\"fade\" id=\"breaker\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:32px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">延伸題：跳電是因為串聯嗎？不是！</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">為什麼家裡會跳電？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1.25fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:44px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<h3 style=\"font-size:40px;font-weight:700\">原因一：電器開太多</h3>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">家裡電器是並聯。每多開一台，就多一條分支，總電流就變大。</p>\n<table style=\"font-size:26px;color:#18262B\">\n<tr><th style=\"width:62%;text-align:left\">同時開（110 V）</th><th style=\"width:38%;text-align:right\">電流</th></tr>\n<tr><td>吹風機 1500 W</td><td style=\"text-align:right\">約 13.6 A</td></tr>\n<tr><td>電熱水壺 1200 W</td><td style=\"text-align:right\">約 10.9 A</td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>合計：超過 20 A 上限，跳電</b></td><td style=\"text-align:right\"><b>約 24.5 A</b></td></tr>\n</table>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:44px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<h3 style=\"font-size:40px;font-weight:700\">原因二：短路</h3>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">電線直接碰在一起，電流不經過電器，電阻幾乎是 0。</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:36px;font-weight:700;line-height:1.5\">I = V ÷ R<br/>R ≈ 0 → I 暴增</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">斷路器馬上切斷，避免電線過熱起火。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5;background:#E1ECFA;padding:24px 32px;border-radius:16px\"><b>電器之間是並聯</b>，所以能各自開關；<b>斷路器跟整條迴路串聯</b>，所以一跳，整條迴路全部斷電。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 13</p>\n\n</section>", "note": "很多學生以為跳電是因為串聯，其實相反。瓦數換算成電流用的是「電流 = 瓦數 ÷ 電壓」，例如 1500 ÷ 110 約 13.6 安培；這裡只要看懂合計超過上限就好。表中瓦數是常見電器的大約值，實際以電器標示為準；20 安培是常見的單一迴路上限，各家配電不同。"}, {"id": "myth", "html": "<section data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" id=\"myth\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">電流流過燈泡之後，會變少嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.1\">不會。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:36px;line-height:1.5\">串聯電路裡，燈泡前面和後面的電流<b>一樣大</b>。燈泡用掉的是電子帶的<b>能量</b>，不是電子本身。</p>\n<p style=\"font-size:36px;line-height:1.5\">就像水流過水車：水車轉了，<b>水一滴也沒少</b>。電池「沒電」是能量用完了，不是電子跑光了。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">電路與歐姆定律 · 14</p>\n\n</section>", "note": "回扣第 4 張：電線裡本來就擠滿電子，電池只是推它們。電池給電子能量，燈泡把能量變成光和熱，電子繼續繞圈回到電池。"}, {"id": "quiz", "html": "<section data-transition=\"fade\" id=\"quiz\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:36px;line-height:1.5\">電壓、電流、電阻，哪一個是「推力」？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:36px;line-height:1.5\">6 伏特的電池接上 2 歐姆的燈泡，電流是多少？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:36px;line-height:1.5\">教室的燈壞了一支，其他照樣亮。它們是串聯還是並聯？</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">電路與歐姆定律 · 15</p>\n\n</section>", "note": "先讓學生自己作答。第 2 題 提醒他們先寫已知、再選公式、最後加單位。"}, {"id": "answers", "html": "<section data-transition=\"fade\" id=\"answers\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:700\">電壓</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">電壓是推力，電流是流量，電阻是阻擋。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:700\">3 安培</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:28px;line-height:1.5;color:#BFCDC9\">I = V ÷ R = 6 ÷ 2 = 3 A</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:700\">並聯</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">很多條路，各管各的。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:56px;font-weight:900;line-height:1.35\">電壓推、電阻擋、電流流。<br/><span style=\"color:#E58A55\">燈泡用掉的是能量，不是電流。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">電路與歐姆定律 · 16</p>\n\n</section>", "note": "下一課：波動、聲音與光。為什麼聽得到隔壁講話，卻看不到人？"}]}, "circuits-en": {"title": "Circuits & Ohm’s Law", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">PHYSICS</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Circuits &amp;<br>Ohm’s Law</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">How does electricity move through a wire?</p>\n</div>\n<svg aria-label=\"A battery connected to a glowing light bulb, with electrons moving around the wire loop\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<path d=\"M90 90 H630 V400 H90 Z\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linejoin=\"round\"/>\n<rect x=\"60\" y=\"200\" width=\"60\" height=\"80\" fill=\"#18262B\"/>\n<rect x=\"50\" y=\"214\" width=\"80\" height=\"12\" fill=\"#F3F5F2\"/>\n<rect x=\"68\" y=\"250\" width=\"44\" height=\"12\" fill=\"#F3F5F2\"/>\n<circle cx=\"360\" cy=\"90\" r=\"46\" fill=\"#FFC94D\" stroke=\"#F3F5F2\" stroke-width=\"6\"/>\n<path d=\"M340 100 L352 76 L368 100 L380 76\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\" stroke-linejoin=\"round\"/>\n<line x1=\"360\" y1=\"22\" x2=\"360\" y2=\"0\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"420\" y1=\"40\" x2=\"438\" y2=\"24\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"300\" y1=\"40\" x2=\"282\" y2=\"24\" stroke=\"#FFC94D\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<circle cx=\"200\" cy=\"90\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"520\" cy=\"90\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"630\" cy=\"220\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"500\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"300\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n<circle cx=\"90\" cy=\"340\" r=\"12\" fill=\"#E58A55\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied electricity. We skip memorizing formulas at first: we picture a circuit as water pipes, then meet one famous formula, and finally solve the string-lights puzzle."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">One bulb breaks. Why does the whole string go dark?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Old holiday lights</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">One bulb burns out and <b style=\"color:#18262B\">the whole string goes dark</b>. You have to test bulbs one by one to find it.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M3 10.5 12 3l9 7.5V21H3zM9 21v-6h6v6\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Lights at home</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Turn off the bedroom light and <b style=\"color:#18262B\">the fridge and TV keep running</b>. Each one switches on its own.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Both are plugged into electricity. The difference is <b style=\"color:#B4521F\">how they are wired</b>.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 2</p>\n\n</section>", "note": "Let students guess first. Many say “holiday lights are cheaper.” The real answer is the wiring, which we reveal in the second half. First we need to meet the three main characters of a circuit."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M13 2 3 14h9l-1 8 10-12h-9l1-8z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Name the big three</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Explain voltage, current and resistance.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Use V = IR</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Find the current from the voltage and resistance.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 10.5 12 3l9 7.5V21H3zM9 21v-6h6v6\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Series vs. parallel</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Explain holiday lights vs. home wiring.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 3</p>\n\n</section>", "note": "The three goals match the three parts of the deck: the water-pipe model, Ohm’s law, and series vs. parallel. We finish with a myth and a three-question quiz."}, {"id": "water", "html": "<section id=\"water\" data-section=\"Water pipes as a model for voltage, current and resistance\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">THINK OF WATER PIPES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A circuit is like a loop of pipe</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A closed loop of pipe; a pump on the left pushes water around; a narrow section at the top is the bulb\" width=\"640\" height=\"420\" viewBox=\"0 0 640 420\">\n<path d=\"M80 70 H560 V360 H80 Z\" fill=\"none\" stroke=\"#9CC0EA\" stroke-width=\"44\" stroke-linejoin=\"round\"/>\n<path d=\"M80 70 H560 V360 H80 Z\" fill=\"none\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-dasharray=\"18 22\" stroke-linejoin=\"round\"/>\n<rect x=\"250\" y=\"44\" width=\"140\" height=\"52\" fill=\"#E7EEEA\"/>\n<rect x=\"250\" y=\"60\" width=\"140\" height=\"20\" fill=\"#9CC0EA\" stroke=\"#B4521F\" stroke-width=\"5\"/>\n<circle cx=\"80\" cy=\"215\" r=\"62\" fill=\"#18262B\"/>\n<path d=\"M58 245 L80 180 L102 245 Z\" fill=\"#E58A55\"/>\n<polygon points=\"470,345 500,360 470,375\" fill=\"#2463B8\"/>\n<polygon points=\"170,85 140,70 170,55\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">The pump pushes water around. The narrow part is the bulb.</p>\n</div>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:45%;text-align:left\">Water world</th><th style=\"width:55%;text-align:left\">Circuit world</th></tr>\n<tr><td>Pump</td><td><b>Battery</b></td></tr>\n<tr><td>Pipe</td><td><b>Wire</b></td></tr>\n<tr><td>Water in the pipe</td><td><b>Electrons</b></td></tr>\n<tr><td>A narrow section</td><td><b>Bulb</b> (a resistor)</td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Key idea: wires are <b style=\"color:#B4521F\">already full of electrons</b>. A battery doesn’t make them; it pushes them.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 4</p>\n\n</section>", "note": "Students often think a battery “creates” electricity. Stress that metal wires already hold huge numbers of electrons, just as a pipe is already full of water. The battery only pushes. We come back to this when we bust the myth at the end."}, {"id": "three", "html": "<section id=\"three\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">The three main characters</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#B4521F\">V</p>\n<h3 style=\"font-size:44px;font-weight:800\">Voltage</h3>\n<p style=\"font-size:30px;color:#4F5F64\">Unit: volt (V)</p>\n<p style=\"font-size:30px;line-height:1.5\"><b>The push.</b> How hard the pump pushes the water.</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">An AA battery is 1.5 V. A US wall outlet is about 120 V.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#2463B8\">I</p>\n<h3 style=\"font-size:44px;font-weight:800\">Current</h3>\n<p style=\"font-size:30px;color:#4F5F64\">Unit: ampere (A)</p>\n<p style=\"font-size:30px;line-height:1.5\"><b>The flow.</b> How much water passes one point each second.</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">More flow makes a bulb brighter.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-top:12px solid #18262B;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:96px;font-weight:700;line-height:1.1;color:#18262B\">R</p>\n<h3 style=\"font-size:44px;font-weight:800\">Resistance</h3>\n<p style=\"font-size:30px;color:#4F5F64\">Unit: ohm (Ω)</p>\n<p style=\"font-size:30px;line-height:1.5\"><b>The blockage.</b> A narrow or clogged pipe that slows the water.</p>\n<p style=\"font-size:24px;line-height:1.5;color:#4F5F64\">A bulb is a resistor: its thin filament heats up and glows.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 5</p>\n\n</section>", "note": "One line to remember: voltage is the push, current is the flow, resistance is the blockage. Units: volts, amps, ohms."}, {"id": "intuition", "html": "<section id=\"intuition\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">GUESS FIRST</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">How do push and blockage change the flow?</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:40px;flex:1;justify-content:center\">\n<div style=\"display:flex;align-items:center;gap:40px\">\n<p style=\"flex:1;font-size:44px;font-weight:800;background:#F7E6DC;padding:40px 48px;border-radius:20px\">Pump pushes harder<br><span style=\"color:#B4521F\">voltage goes up</span></p>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#4F5F64;width:120px;height:60px\"></div>\n<p style=\"flex:1;font-size:44px;font-weight:800;background:#E1ECFA;padding:40px 48px;border-radius:20px\">More water flows<br><span style=\"color:#2463B8\">current goes up</span></p>\n</div>\n<div style=\"display:flex;align-items:center;gap:40px\">\n<p style=\"flex:1;font-size:44px;font-weight:800;background:#E4E8E6;padding:40px 48px;border-radius:20px\">Pipe gets more clogged<br><span style=\"color:#18262B\">resistance goes up</span></p>\n<div aria-hidden=\"true\" style=\"flex:none;clip-path:polygon(0 32%,62% 32%,62% 0,100% 50%,62% 100%,62% 68%,0 68%);background:#4F5F64;width:120px;height:60px\"></div>\n<p style=\"flex:1;font-size:44px;font-weight:800;background:#E1ECFA;padding:40px 48px;border-radius:20px\">Less water flows<br><span style=\"color:#2463B8\">current goes down</span></p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">What you just guessed is a law of physics.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 6</p>\n\n</section>", "note": "Ask both questions before revealing: if the pump pushes harder, what happens to the flow? If the pipe gets more clogged? Almost everyone gets these right. That intuition is Ohm’s law."}, {"id": "law", "html": "<section id=\"law\" data-section=\"Ohm’s law V = IR, worked step by step\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">OHM’S LAW</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">V</p>\n<p style=\"font-size:32px;color:#BFCDC9\">voltage</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">I</p>\n<p style=\"font-size:32px;color:#BFCDC9\">current</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">R</p>\n<p style=\"font-size:32px;color:#BFCDC9\">resistance</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">Need the current? <span style=\"color:#7FB0F2\">I = V ÷ R</span> (push ÷ blockage = flow)</p>\n<p style=\"font-size:24px;line-height:1.5;color:#BFCDC9\">Why “I” for current? It comes from the French word intensité (intensity). It’s just a tradition.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Circuits &amp; Ohm’s Law · 7</p>\n\n</section>", "note": "Georg Ohm, a German scientist, wrote this intuition down as a formula about 200 years ago. It only has three letters. The key skill is flipping it: to find current, divide voltage by resistance."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">A 9 V battery is connected to a 3 Ω bulb. What is the current?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Write what you know</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">V = 9 V<br>R = 3 Ω</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Pick the formula</h3>\n<p style=\"font-size:30px;line-height:1.6\">We want current, so<br><b style=\"font-family:'JetBrains Mono', 'Courier New', monospace\">I = V ÷ R</b></p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Plug in and solve</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">I = 9 ÷ 3<br>&#160;&#160;= 3</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">Add the unit</h3>\n<p style=\"font-size:30px;line-height:1.6\">Current is in amps<br><b style=\"font-family:'JetBrains Mono', 'Courier New', monospace\">3 A</b></p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Answer: the current is <span style=\"color:#2463B8\">3 amps</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 8</p>\n\n</section>", "note": "Walk through it step by step. Step one is always writing down what you know; only then choose the formula. Don’t forget the unit: current is measured in amps."}, {"id": "vary", "html": "<section id=\"vary\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">YOUR TURN</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Change one number. What happens?</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:20%;text-align:left\">Battery</th><th style=\"width:20%;text-align:left\">Bulb</th><th style=\"width:16%;text-align:left\">Current</th><th style=\"width:44%;text-align:left\">What changed</th></tr>\n<tr><td>9 V</td><td>3 Ω</td><td><b>3 A</b></td><td>The original example</td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>18 V</b></td><td>3 Ω</td><td><b>6 A</b></td><td>Voltage ×2 → current ×2</td></tr>\n<tr style=\"background:#E1ECFA\"><td>9 V</td><td><b>9 Ω</b></td><td><b>1 A</b></td><td>Resistance ×3 → current ÷3</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">The formula just writes down your intuition:<br><span style=\"color:#B4521F\">more voltage, more current; more resistance, less current.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 9</p>\n\n</section>", "note": "Cover the current column and let students work it out: 18 ÷ 3 = 6 and 9 ÷ 9 = 1. Then ask them to state the pattern in their own words."}, {"id": "series", "html": "<section id=\"series\" data-section=\"Series vs. parallel: two ways to wire bulbs\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WIRING STYLE 1</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Series: only one path</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Series circuit: a battery and three bulbs on one loop of wire; the middle bulb is broken and crossed out, and all three bulbs are dark\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<path d=\"M70 90 H690 V360 H70 Z\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linejoin=\"round\"/>\n<rect x=\"40\" y=\"180\" width=\"60\" height=\"90\" fill=\"#E7EEEA\"/>\n<rect x=\"30\" y=\"196\" width=\"80\" height=\"12\" fill=\"#18262B\"/>\n<rect x=\"48\" y=\"236\" width=\"44\" height=\"12\" fill=\"#18262B\"/>\n<circle cx=\"220\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"380\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"540\" cy=\"90\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"350\" y1=\"60\" x2=\"410\" y2=\"120\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"410\" y1=\"60\" x2=\"350\" y2=\"120\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">The middle bulb broke, so all three went dark.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:34px;line-height:1.5\">Bulbs are lined up one after another, like <b>beads on a single string</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">One breaks and it’s like cutting the pipe: <b style=\"color:#B4521F\">the whole loop stops</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">More bulbs add more resistance, so <b>each bulb gets dimmer</b>.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Example: old holiday lights. (Many newer strings have a bypass so one dead bulb doesn’t kill the rest.)</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 10</p>\n\n</section>", "note": "Back to the opening puzzle. In series there is only one path, so the water has to pass through every bulb in turn. When one filament breaks, the whole loop stops flowing and every bulb goes dark."}, {"id": "parallel", "html": "<section id=\"parallel\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WIRING STYLE 2</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Parallel: many paths</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Parallel circuit: a battery feeds a top and bottom wire with three branches between them, each with its own bulb; the middle bulb is broken and crossed out while the other two still glow\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<path d=\"M70 60 H690 M70 360 H690 M70 60 V360\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<path d=\"M260 60 V360 M460 60 V360 M660 60 V360\" fill=\"none\" stroke=\"#6D7F7B\" stroke-width=\"10\"/>\n<rect x=\"40\" y=\"160\" width=\"60\" height=\"90\" fill=\"#E7EEEA\"/>\n<rect x=\"30\" y=\"176\" width=\"80\" height=\"12\" fill=\"#18262B\"/>\n<rect x=\"48\" y=\"216\" width=\"44\" height=\"12\" fill=\"#18262B\"/>\n<circle cx=\"260\" cy=\"210\" r=\"44\" fill=\"#F2B630\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"460\" cy=\"210\" r=\"44\" fill=\"#C9D2CF\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<circle cx=\"660\" cy=\"210\" r=\"44\" fill=\"#F2B630\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"430\" y1=\"180\" x2=\"490\" y2=\"240\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"490\" y1=\"180\" x2=\"430\" y2=\"240\" stroke=\"#B4521F\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">The middle bulb broke; the other two still glow.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:34px;line-height:1.5\">The main wire splits into branches, like <b>exits off a highway</b>. Each branch has its own bulb.</p>\n<p style=\"font-size:34px;line-height:1.5\">If one branch breaks, only that branch stops: <b style=\"color:#2463B8\">the others stay on</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">Every branch connects straight to the battery, so <b>each bulb gets the full voltage</b>.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Examples: lights, fridge and TV at home; classroom ceiling lights.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 11</p>\n\n</section>", "note": "Turning off the bedroom light doesn’t stop the fridge. That isn’t automatic; it’s because home appliances are deliberately wired in parallel."}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ONE TABLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Series vs. parallel</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:36%;text-align:left\">Compare</th><th style=\"width:32%;text-align:left\">Series (one string)</th><th style=\"width:32%;text-align:left\">Parallel (highway exits)</th></tr>\n<tr><td>Number of paths</td><td>One</td><td>Many</td></tr>\n<tr><td>One bulb breaks</td><td><span style=\"color:#B4521F\">All go dark</span></td><td><span style=\"color:#2463B8\">Others stay on</span></td></tr>\n<tr><td>Voltage per bulb</td><td>Shared</td><td>Full voltage</td></tr>\n<tr><td>Two identical bulbs</td><td>Dimmer</td><td>Brighter</td></tr>\n<tr><td>Everyday example</td><td>Old holiday lights</td><td>Home appliances</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:36px;font-weight:800;line-height:1.4\">Remember: series is “one path, one breaks, all stop.” Parallel is “many paths, each on its own.”</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 12</p>\n\n</section>", "note": "Ask students to predict the brightness row first: two identical bulbs on the same battery. In parallel each bulb gets the full voltage; in series they share it, so parallel bulbs are brighter."}, {"id": "breaker", "html": "<section id=\"breaker\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:32px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BONUS: IS IT BECAUSE OF SERIES? NO!</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why does a breaker trip?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1.25fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:44px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<h3 style=\"font-size:40px;font-weight:800\">Cause 1: too much at once</h3>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Home appliances are in parallel. Each one adds a branch, so the total current goes up.</p>\n<table style=\"font-size:26px;color:#18262B\">\n<tr><th style=\"width:62%;text-align:left\">Running together (120 V)</th><th style=\"width:38%;text-align:right\">Current</th></tr>\n<tr><td>Hair dryer, 1500 W</td><td style=\"text-align:right\">12.5 A</td></tr>\n<tr><td>Electric kettle, 1200 W</td><td style=\"text-align:right\">10 A</td></tr>\n<tr style=\"background:#F7E6DC\"><td><b>Total: over the 20 A limit, trips</b></td><td style=\"text-align:right\"><b>22.5 A</b></td></tr>\n</table>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:44px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<h3 style=\"font-size:40px;font-weight:800\">Cause 2: a short circuit</h3>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Two wires touch, the current skips the appliance, and resistance drops to almost zero.</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:36px;font-weight:700;line-height:1.5\">I = V ÷ R<br>R ≈ 0 → I spikes</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">The breaker cuts power before the wires overheat.</p>\n</div>\n</div>\n<p style=\"font-size:30px;line-height:1.5;background:#E1ECFA;padding:20px 32px;border-radius:16px\"><b>Appliances are in parallel</b>, so each switches on its own. <b>The breaker is in series</b> with the whole circuit, so when it trips, everything on that circuit goes off.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 13</p>\n\n</section>", "note": "Many students think breakers trip because of series wiring, or because “there isn’t enough electricity.” Both are wrong: the outlet supplies a fixed voltage, and the appliances decide how much current flows. To convert watts to amps, divide by the voltage: 1500 ÷ 120 = 12.5 A. The wattages are typical values; check each appliance’s label. 15 A and 20 A are common limits for a single US household circuit."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Does a bulb use up current?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">In a series circuit the current is <b>the same before and after</b> the bulb. The bulb uses up the electrons’ <b>energy</b>, not the electrons.</p>\n<p style=\"font-size:34px;line-height:1.5\">Like water turning a waterwheel: the wheel spins, but <b>not one drop is lost</b>. A “dead” battery has run out of energy, not electrons.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Circuits &amp; Ohm’s Law · 14</p>\n\n</section>", "note": "Link back to slide 4: wires are already full of electrons and the battery only pushes them. The battery gives electrons energy, the bulb turns that energy into light and heat, and the electrons keep circling back to the battery."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">Voltage, current or resistance: which one is the “push”?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">A 6 V battery is connected to a 2 Ω bulb. What is the current?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">One classroom light burns out and the rest stay on. Series or parallel?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Circuits &amp; Ohm’s Law · 15</p>\n\n</section>", "note": "Let students answer on their own first. For Q2, remind them: write what you know, pick the formula, then add the unit."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">Voltage</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Voltage pushes, current flows, resistance blocks.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">3 amps</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:28px;line-height:1.5;color:#BFCDC9\">I = V ÷ R = 6 ÷ 2 = 3 A</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">Parallel</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Many paths, each on its own.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Voltage pushes, resistance blocks, current flows.<br><span style=\"color:#E58A55\">A bulb uses up energy, not current.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Circuits &amp; Ohm’s Law · 16</p>\n\n</section>", "note": "Next lesson: waves, sound and light. Why can you hear someone through a wall but not see them?"}]}, "waves-zh": {"title": "波動、聲音與光", "lang": "zh", "slides": [{"id": "cover", "html": "<section data-transition=\"fade\" id=\"cover\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">物理</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.1;color:#F3F5F2\">波動、<br/>聲音與光</h1>\n<p style=\"font-size:32px;line-height:1.5;color:#BFCDC9\">從零開始：聲音和光是怎麼跑到你身邊的？</p>\n</div>\n<svg aria-label=\"三條波：上方是橘色長波，中間是藍色短波，下方是一束黃色光線穿過透鏡聚在一點\" height=\"480\" viewbox=\"0 0 720 480\" width=\"720\">\n<path d=\"M20 110 C 110 20, 200 20, 290 110 S 470 200, 560 110 S 650 20, 700 70\" fill=\"none\" stroke=\"#E58A55\" stroke-linecap=\"round\" stroke-width=\"10\"></path>\n<path d=\"M20 250 C 60 200, 100 200, 140 250 S 220 300, 260 250 S 340 200, 380 250 S 460 300, 500 250 S 580 200, 620 250 S 680 290, 700 270\" fill=\"none\" stroke=\"#7FB0F2\" stroke-linecap=\"round\" stroke-width=\"10\"></path>\n<line stroke=\"#FFC94D\" stroke-width=\"6\" x1=\"20\" x2=\"330\" y1=\"350\" y2=\"350\"></line>\n<line stroke=\"#FFC94D\" stroke-width=\"6\" x1=\"20\" x2=\"330\" y1=\"400\" y2=\"400\"></line>\n<line stroke=\"#FFC94D\" stroke-width=\"6\" x1=\"20\" x2=\"330\" y1=\"450\" y2=\"450\"></line>\n<line stroke=\"#FFC94D\" stroke-width=\"6\" x1=\"330\" x2=\"560\" y1=\"350\" y2=\"400\"></line>\n<line stroke=\"#FFC94D\" stroke-width=\"6\" x1=\"330\" x2=\"560\" y1=\"450\" y2=\"400\"></line>\n<line opacity=\"0.5\" stroke=\"#FFC94D\" stroke-width=\"6\" x1=\"330\" x2=\"700\" y1=\"400\" y2=\"400\"></line>\n<ellipse cx=\"330\" cy=\"400\" fill=\"#7FB0F2\" opacity=\"0.55\" rx=\"22\" ry=\"70\" stroke=\"#F3F5F2\" stroke-width=\"4\"></ellipse>\n<circle cx=\"560\" cy=\"400\" fill=\"#E58A55\" r=\"12\"></circle>\n</svg>\n\n</section>", "note": "這一課從「波」開始。聲音和光都是波，只是個性不同。我們先認識波，再分別看聲音和光，最後學會判斷凸透鏡會成什麼樣的像。"}, {"id": "hook", "html": "<section data-transition=\"fade\" id=\"hook\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">為什麼聽得到隔壁講話，卻看不到人？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">聲音</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">可以從門縫鑽過來、繞過轉角，<b style=\"color:#18262B\">隔著牆也聽得到</b>。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">光</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">幾乎只走直線，<b style=\"color:#18262B\">被牆擋住就過不來</b>，所以看不到隔壁的人。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">聲音和光其實都是<b style=\"color:#B4521F\">「波」</b>，只是個性不同。今天就來認識它們。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 2</p>\n\n</section>", "note": "先讓學生猜原因。答案和「波長」有關：聲波的波長大約幾十公分到幾公尺，跟門縫、轉角差不多大，所以容易繞過去；光的波長非常非常短，所以幾乎只走直線。學完波長之後再回來看這題。"}, {"id": "goals", "html": "<section data-transition=\"fade\" id=\"goals\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">看懂一個波</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">說出波長、頻率，並用 v = fλ 算波速。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">認識聲音</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">分辨聲音三要素，知道聲音為什麼需要介質。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.25\">判斷成像</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">依物距說出凸透鏡會成什麼樣的像。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 3</p>\n\n</section>", "note": "三個目標對應三段：波的基本概念、聲音、光與透鏡。最後有迷思破解和三題小測驗。"}, {"id": "wave", "html": "<section data-section=\"什麼是波：波長、頻率與波速\" data-transition=\"fade\" id=\"wave\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">什麼是波</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">波傳的是能量，不是東西</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"體育館人浪：一排人，中間幾個人站起來舉手，其他人坐著；箭頭表示人浪往右傳，但每個人都留在原位\" height=\"300\" viewbox=\"0 0 1600 300\" width=\"1600\">\n<line stroke=\"#9AAAA6\" stroke-width=\"6\" x1=\"40\" x2=\"1560\" y1=\"270\" y2=\"270\"></line>\n<g fill=\"#4F5F64\">\n<circle cx=\"100\" cy=\"200\" r=\"22\"></circle><rect height=\"48\" rx=\"10\" width=\"40\" x=\"80\" y=\"222\"></rect>\n<circle cx=\"220\" cy=\"200\" r=\"22\"></circle><rect height=\"48\" rx=\"10\" width=\"40\" x=\"200\" y=\"222\"></rect>\n<circle cx=\"340\" cy=\"200\" r=\"22\"></circle><rect height=\"48\" rx=\"10\" width=\"40\" x=\"320\" y=\"222\"></rect>\n<circle cx=\"460\" cy=\"190\" r=\"22\"></circle><rect height=\"58\" rx=\"10\" width=\"40\" x=\"440\" y=\"212\"></rect>\n</g>\n<g fill=\"#B4521F\">\n<circle cx=\"580\" cy=\"150\" r=\"22\"></circle><rect height=\"98\" rx=\"10\" width=\"40\" x=\"560\" y=\"172\"></rect><line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"580\" x2=\"580\" y1=\"128\" y2=\"70\"></line>\n<circle cx=\"700\" cy=\"110\" r=\"22\"></circle><rect height=\"138\" rx=\"10\" width=\"40\" x=\"680\" y=\"132\"></rect><line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"700\" x2=\"700\" y1=\"88\" y2=\"30\"></line>\n<circle cx=\"820\" cy=\"150\" r=\"22\"></circle><rect height=\"98\" rx=\"10\" width=\"40\" x=\"800\" y=\"172\"></rect><line stroke=\"#B4521F\" stroke-linecap=\"round\" stroke-width=\"12\" x1=\"820\" x2=\"820\" y1=\"128\" y2=\"70\"></line>\n</g>\n<g fill=\"#4F5F64\">\n<circle cx=\"940\" cy=\"190\" r=\"22\"></circle><rect height=\"58\" rx=\"10\" width=\"40\" x=\"920\" y=\"212\"></rect>\n<circle cx=\"1060\" cy=\"200\" r=\"22\"></circle><rect height=\"48\" rx=\"10\" width=\"40\" x=\"1040\" y=\"222\"></rect>\n<circle cx=\"1180\" cy=\"200\" r=\"22\"></circle><rect height=\"48\" rx=\"10\" width=\"40\" x=\"1160\" y=\"222\"></rect>\n<circle cx=\"1300\" cy=\"200\" r=\"22\"></circle><rect height=\"48\" rx=\"10\" width=\"40\" x=\"1280\" y=\"222\"></rect>\n</g>\n<line stroke=\"#2463B8\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"1380\" x2=\"1520\" y1=\"120\" y2=\"120\"></line>\n<polygon fill=\"#2463B8\" points=\"1520,96 1560,120 1520,144\"></polygon>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">體育館的人浪：「站起來」這個動作往右傳，但每個人都留在自己的座位上。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:40px\">\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\">波是一個<b>振動</b>，一個推一個地傳出去。傳過去的是<b style=\"color:#B4521F\">能量</b>，東西本身沒有跟著跑。</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\">例子：丟石頭到池塘，漣漪往外擴散，但水面上的葉子只是<b>上下晃</b>，不會被沖走。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 4</p>\n\n</section>", "note": "可以請全班做一次人浪。重點是：每個人只是站起來再坐下，沒有離開座位，但「站起來」這個動作卻傳到了教室另一頭。這就是波：傳能量，不傳東西。"}, {"id": "parts", "html": "<section data-transition=\"fade\" id=\"parts\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">一個波的三個重點</h2>\n<svg aria-label=\"一條波浪線：橘色括號標出兩個波峰之間的距離是波長，藍色直線標出波峰到中線的高度是振幅\" height=\"250\" viewbox=\"0 0 1664 250\" width=\"1664\">\n<line stroke=\"#9AAAA6\" stroke-dasharray=\"12 10\" stroke-width=\"3\" x1=\"0\" x2=\"1560\" y1=\"170\" y2=\"170\"></line>\n<path d=\"M0 170 C 80 50, 170 50, 250 170 S 420 290, 500 170 S 670 50, 750 170 S 920 290, 1000 170 S 1170 50, 1250 170 S 1420 290, 1500 170\" fill=\"none\" stroke=\"#18262B\" stroke-linecap=\"round\" stroke-width=\"8\"></path>\n<line stroke=\"#B4521F\" stroke-width=\"8\" x1=\"125\" x2=\"625\" y1=\"30\" y2=\"30\"></line>\n<line stroke=\"#B4521F\" stroke-width=\"8\" x1=\"125\" x2=\"125\" y1=\"12\" y2=\"48\"></line>\n<line stroke=\"#B4521F\" stroke-width=\"8\" x1=\"625\" x2=\"625\" y1=\"12\" y2=\"48\"></line>\n<line stroke=\"#2463B8\" stroke-width=\"10\" x1=\"1125\" x2=\"1125\" y1=\"82\" y2=\"170\"></line>\n<polygon fill=\"#2463B8\" points=\"1112,96 1125,74 1138,96\"></polygon>\n</svg>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">波長 <span style=\"color:#B4521F\">λ</span></h3>\n<p style=\"font-size:24px;color:#4F5F64\">單位：公尺（m）</p>\n<p style=\"font-size:32px;line-height:1.5\">相鄰兩個<b>波峰</b>之間的距離（橘色括號）。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">振幅</h3>\n<p style=\"font-size:24px;color:#4F5F64\">波的高度</p>\n<p style=\"font-size:32px;line-height:1.5\">波峰離中線<b>有多高</b>（藍色線）。振幅越大，能量越大。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #18262B;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">頻率 <span style=\"color:#4F5F64\">f</span></h3>\n<p style=\"font-size:24px;color:#4F5F64\">單位：赫茲（Hz）</p>\n<p style=\"font-size:32px;line-height:1.5\"><b>每秒振動幾次</b>。100 Hz 就是每秒振動 100 次。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 5</p>\n\n</section>", "note": "波長和振幅可以在圖上直接看到；頻率要用時間來看，就是每秒鐘有幾個波經過。用跳繩舉例：甩得越快，頻率越高；甩得越用力、繩子晃得越高，振幅越大。"}, {"id": "speed", "html": "<section data-transition=\"fade\" id=\"speed\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">波速公式</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">v</p>\n<p style=\"font-size:32px;color:#BFCDC9\">波速 m/s</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">f</p>\n<p style=\"font-size:32px;color:#BFCDC9\">頻率 Hz</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">λ</p>\n<p style=\"font-size:32px;color:#BFCDC9\">波長 m</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4\">例：空氣中聲速約 340 m/s，170 Hz 的聲音<br/>波長 λ = v ÷ f = 340 ÷ 170 = <span style=\"color:#E58A55\">2 公尺</span></p>\n<p style=\"font-size:24px;line-height:1.5;color:#BFCDC9\">同一種波、同一個介質裡波速不變：頻率越高，波長就越短。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">波動、聲音與光 · 6</p>\n\n</section>", "note": "可以這樣理解：每秒振動 f 次，每次前進一個波長 λ，所以每秒前進 f × λ。和歐姆定律一樣，三個量知道兩個就能算第三個。聲速 340 m/s 大約是 15°C 空氣中的值。"}, {"id": "kinds", "html": "<section data-transition=\"fade\" id=\"kinds\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">波的兩種樣子</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">橫波和縱波</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">橫波</h3>\n<svg aria-label=\"橫波：一條繩子上下起伏，藍色箭頭表示往右傳，橘色箭頭表示繩子上下振動\" height=\"200\" viewbox=\"0 0 700 200\" width=\"700\">\n<path d=\"M20 100 C 70 20, 120 20, 170 100 S 270 180, 320 100 S 420 20, 470 100 S 570 180, 620 100\" fill=\"none\" stroke=\"#18262B\" stroke-linecap=\"round\" stroke-width=\"7\"></path>\n<line stroke=\"#2463B8\" stroke-width=\"8\" x1=\"640\" x2=\"680\" y1=\"100\" y2=\"100\"></line>\n<polygon fill=\"#2463B8\" points=\"672,86 698,100 672,114\"></polygon>\n<line stroke=\"#B4521F\" stroke-width=\"6\" x1=\"95\" x2=\"95\" y1=\"70\" y2=\"150\"></line>\n<polygon fill=\"#B4521F\" points=\"84,74 95,54 106,74\"></polygon>\n<polygon fill=\"#B4521F\" points=\"84,146 95,166 106,146\"></polygon>\n</svg>\n<p style=\"font-size:32px;line-height:1.5\">像甩繩子：繩子<b style=\"color:#B4521F\">上下</b>振動，波往<b style=\"color:#2463B8\">右</b>傳，兩個方向互相垂直。</p>\n<p style=\"font-size:28px;color:#4F5F64\">例子：繩波、<b style=\"color:#18262B\">光</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:700\">縱波</h3>\n<svg aria-label=\"縱波：一排直線有的擠在一起、有的分得很開，像彈簧被推拉；藍色箭頭表示往右傳，橘色雙箭頭表示前後振動\" height=\"200\" viewbox=\"0 0 700 200\" width=\"700\">\n<g stroke=\"#18262B\" stroke-width=\"6\">\n<line x1=\"30\" x2=\"30\" y1=\"50\" y2=\"150\"></line><line x1=\"48\" x2=\"48\" y1=\"50\" y2=\"150\"></line><line x1=\"64\" x2=\"64\" y1=\"50\" y2=\"150\"></line><line x1=\"78\" x2=\"78\" y1=\"50\" y2=\"150\"></line>\n<line x1=\"120\" x2=\"120\" y1=\"50\" y2=\"150\"></line><line x1=\"170\" x2=\"170\" y1=\"50\" y2=\"150\"></line><line x1=\"220\" x2=\"220\" y1=\"50\" y2=\"150\"></line>\n<line x1=\"256\" x2=\"256\" y1=\"50\" y2=\"150\"></line><line x1=\"274\" x2=\"274\" y1=\"50\" y2=\"150\"></line><line x1=\"290\" x2=\"290\" y1=\"50\" y2=\"150\"></line><line x1=\"304\" x2=\"304\" y1=\"50\" y2=\"150\"></line>\n<line x1=\"346\" x2=\"346\" y1=\"50\" y2=\"150\"></line><line x1=\"396\" x2=\"396\" y1=\"50\" y2=\"150\"></line><line x1=\"446\" x2=\"446\" y1=\"50\" y2=\"150\"></line>\n<line x1=\"482\" x2=\"482\" y1=\"50\" y2=\"150\"></line><line x1=\"500\" x2=\"500\" y1=\"50\" y2=\"150\"></line><line x1=\"516\" x2=\"516\" y1=\"50\" y2=\"150\"></line><line x1=\"530\" x2=\"530\" y1=\"50\" y2=\"150\"></line>\n<line x1=\"572\" x2=\"572\" y1=\"50\" y2=\"150\"></line><line x1=\"620\" x2=\"620\" y1=\"50\" y2=\"150\"></line>\n</g>\n<line stroke=\"#2463B8\" stroke-width=\"8\" x1=\"640\" x2=\"680\" y1=\"100\" y2=\"100\"></line>\n<polygon fill=\"#2463B8\" points=\"672,86 698,100 672,114\"></polygon>\n<line stroke=\"#B4521F\" stroke-width=\"6\" x1=\"150\" x2=\"250\" y1=\"180\" y2=\"180\"></line>\n<polygon fill=\"#B4521F\" points=\"152,169 132,180 152,191\"></polygon>\n<polygon fill=\"#B4521F\" points=\"248,169 268,180 248,191\"></polygon>\n</svg>\n<p style=\"font-size:32px;line-height:1.5\">像推拉彈簧：彈簧<b style=\"color:#B4521F\">前後</b>擠壓、拉開，波也往<b style=\"color:#2463B8\">右</b>傳，兩個方向相同。</p>\n<p style=\"font-size:28px;color:#4F5F64\">例子：彈簧波、<b style=\"color:#18262B\">聲音</b></p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 7</p>\n\n</section>", "note": "用彈簧玩具示範最清楚：左右甩是橫波，前後推是縱波。聲音是空氣分子前後擠壓的縱波，光則是橫波。"}, {"id": "sound3", "html": "<section data-section=\"聲音：三要素與介質\" data-transition=\"fade\" id=\"sound3\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">聲音</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">聲音的三要素</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:24%;text-align:left\">要素</th><th style=\"width:34%;text-align:left\">由什麼決定</th><th style=\"width:42%;text-align:left\">生活例子</th></tr>\n<tr><td><b>響度</b></td><td><span style=\"color:#2463B8\">振幅</span>：越大越大聲</td><td>輕聲說話 對比 大聲喊叫</td></tr>\n<tr><td><b>音調</b></td><td><span style=\"color:#B4521F\">頻率</span>：越高越尖</td><td>小鳥叫（高）對比 打大鼓（低）</td></tr>\n<tr><td><b>音色</b></td><td>波形：每種樂器不同</td><td>鋼琴和小提琴彈同一個音，還是聽得出差別</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:24px 32px;border-radius:16px\">人耳大約聽得到 <b>20–20,000 Hz</b> 的聲音。比這更高的叫超音波，狗和蝙蝠聽得到。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 8</p>\n\n</section>", "note": "連回上一段：振幅決定大不大聲，頻率決定高不高音。可以用手機的頻率產生器應用程式從低頻慢慢調高，讓學生聽音調變化。"}, {"id": "medium", "html": "<section data-transition=\"fade\" id=\"medium\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">聲音需要介質</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">太空中聽得到爆炸聲嗎？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:56px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<p style=\"font-size:96px;font-weight:900;line-height:1.1;color:#B4521F\">聽不到。</p>\n<p style=\"font-size:32px;line-height:1.5\">聲音靠介質裡的粒子<b>一個推一個</b>傳過去。太空是真空，沒有粒子可以推，聲音就傳不出去。</p>\n<p style=\"font-size:32px;line-height:1.5\">光不需要介質，所以太陽光可以穿過太空照到地球。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:50%;text-align:left\">在什麼裡面</th><th style=\"width:50%;text-align:right\">傳播速度（約）</th></tr>\n<tr><td>空氣中的聲音</td><td style=\"text-align:right\">340 m/s</td></tr>\n<tr><td>水中的聲音</td><td style=\"text-align:right\">1,500 m/s</td></tr>\n<tr><td>鋼鐵中的聲音</td><td style=\"text-align:right\">5,000 m/s</td></tr>\n<tr style=\"background:#E1ECFA\"><td><b>光</b></td><td style=\"text-align:right\"><b>300,000,000 m/s</b></td></tr>\n</table>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">光比聲音快得多，所以打雷時<b style=\"color:#18262B\">先看到閃電，才聽到雷聲</b>。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 9</p>\n\n</section>", "note": "電影裡太空爆炸「轟」的一聲是音效，真實的太空是安靜的。延伸：從看到閃電到聽到雷聲數幾秒，乘以 340，大約就是閃電離你幾公尺。數值都是約略值，聲速會隨溫度和材料改變。"}, {"id": "reflect", "html": "<section data-section=\"光：反射、折射與凸透鏡成像\" data-transition=\"fade\" id=\"reflect\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">光</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">光的反射</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"光的反射：一道光斜斜打到鏡面後反彈出去，中間虛線是法線，左右兩個角度一樣大\" height=\"420\" viewbox=\"0 0 760 420\" width=\"760\">\n<rect fill=\"#9CC0EA\" height=\"24\" stroke=\"#2463B8\" stroke-width=\"4\" width=\"640\" x=\"60\" y=\"340\"></rect>\n<line stroke=\"#18262B\" stroke-width=\"6\" x1=\"60\" x2=\"700\" y1=\"364\" y2=\"364\"></line>\n<line stroke=\"#4F5F64\" stroke-dasharray=\"14 10\" stroke-width=\"4\" x1=\"380\" x2=\"380\" y1=\"40\" y2=\"340\"></line>\n<line stroke=\"#E0A21A\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"140\" x2=\"380\" y1=\"100\" y2=\"340\"></line>\n<polygon fill=\"#E0A21A\" points=\"262,206 290,250 246,236\"></polygon>\n<line stroke=\"#E0A21A\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"380\" x2=\"620\" y1=\"340\" y2=\"100\"></line>\n<polygon fill=\"#E0A21A\" points=\"514,206 530,162 486,178\"></polygon>\n<path d=\"M 380 250 A 90 90 0 0 0 316 276\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"6\"></path>\n<path d=\"M 380 250 A 90 90 0 0 1 444 276\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"6\"></path>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">虛線是垂直鏡面的「法線」，兩個橘色角度一樣大。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:36px;line-height:1.5\">光在同一種物質裡<b>走直線</b>，所以被擋住就會有影子。</p>\n<p style=\"font-size:36px;line-height:1.5\">光打到光滑的表面會<b>反彈</b>，就像球打到牆壁彈回來。</p>\n<p style=\"font-size:44px;font-weight:700;line-height:1.4;color:#B4521F\">入射角 = 反射角</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">例子：照鏡子、平靜湖面的倒影、腳踏車的反光片。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 10</p>\n\n</section>", "note": "用手電筒照鏡子示範：改變照射角度，反射出去的角度也跟著改變，而且兩邊永遠一樣大。角度是從法線開始量，不是從鏡面量。"}, {"id": "refract", "html": "<section data-transition=\"fade\" id=\"refract\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">光</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">光的折射</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"一杯水裡插著一根筷子，筷子在水面的地方看起來像折斷了一樣\" height=\"440\" viewbox=\"0 0 640 440\" width=\"640\">\n<path d=\"M150 60 L180 420 L460 420 L490 60\" fill=\"none\" stroke=\"#4F5F64\" stroke-linejoin=\"round\" stroke-width=\"8\"></path>\n<path d=\"M163 200 L180 420 L460 420 L477 200 Z\" fill=\"#9CC0EA\" opacity=\"0.7\"></path>\n<line stroke=\"#2463B8\" stroke-width=\"5\" x1=\"163\" x2=\"477\" y1=\"200\" y2=\"200\"></line>\n<line stroke=\"#8A5A2B\" stroke-linecap=\"round\" stroke-width=\"16\" x1=\"230\" x2=\"330\" y1=\"20\" y2=\"200\"></line>\n<line stroke=\"#8A5A2B\" stroke-linecap=\"round\" stroke-width=\"16\" x1=\"330\" x2=\"452\" y1=\"200\" y2=\"318\"></line>\n<line opacity=\"0.5\" stroke=\"#8A5A2B\" stroke-dasharray=\"10 10\" stroke-width=\"6\" x1=\"330\" x2=\"430\" y1=\"200\" y2=\"380\"></line>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">實線是看到的筷子；淡淡的虛線是筷子真正的位置。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:36px;line-height:1.5\">光從水進入空氣時<b>速度改變</b>，前進方向就會<b style=\"color:#B4521F\">偏折</b>，這叫做折射。</p>\n<p style=\"font-size:36px;line-height:1.5\">所以筷子在水面的地方看起來<b>像折斷了</b>，其實它還是直的。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">其他例子：游泳池看起來比實際淺；眼鏡和放大鏡都是利用折射讓光轉彎。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 11</p>\n\n</section>", "note": "課堂上直接拿透明杯裝水、插一根筷子，從側面看。提醒學生：反射是光「彈回來」，折射是光「穿過去但轉彎」。透鏡就是利用折射。"}, {"id": "lens", "html": "<section data-transition=\"fade\" id=\"lens\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">凸透鏡</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">凸透鏡會把光聚在一點</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"三道平行光從左邊射向凸透鏡，穿過後聚在右邊的焦點；焦點到透鏡中心的距離是焦距\" height=\"340\" viewbox=\"0 0 1500 340\" width=\"1500\">\n<line stroke=\"#9AAAA6\" stroke-dasharray=\"12 10\" stroke-width=\"3\" x1=\"40\" x2=\"1460\" y1=\"170\" y2=\"170\"></line>\n<line stroke=\"#E0A21A\" stroke-width=\"8\" x1=\"60\" x2=\"700\" y1=\"70\" y2=\"70\"></line>\n<line stroke=\"#E0A21A\" stroke-width=\"8\" x1=\"60\" x2=\"700\" y1=\"170\" y2=\"170\"></line>\n<line stroke=\"#E0A21A\" stroke-width=\"8\" x1=\"60\" x2=\"700\" y1=\"270\" y2=\"270\"></line>\n<line stroke=\"#E0A21A\" stroke-width=\"8\" x1=\"700\" x2=\"1100\" y1=\"70\" y2=\"170\"></line>\n<line stroke=\"#E0A21A\" stroke-width=\"8\" x1=\"700\" x2=\"1100\" y1=\"270\" y2=\"170\"></line>\n<line stroke=\"#E0A21A\" stroke-width=\"8\" x1=\"700\" x2=\"1100\" y1=\"170\" y2=\"170\"></line>\n<ellipse cx=\"700\" cy=\"170\" fill=\"#9CC0EA\" opacity=\"0.6\" rx=\"36\" ry=\"150\" stroke=\"#2463B8\" stroke-width=\"5\"></ellipse>\n<circle cx=\"1100\" cy=\"170\" fill=\"#B4521F\" r=\"16\"></circle>\n<line stroke=\"#B4521F\" stroke-width=\"6\" x1=\"700\" x2=\"1100\" y1=\"320\" y2=\"320\"></line>\n<line stroke=\"#B4521F\" stroke-width=\"6\" x1=\"700\" x2=\"700\" y1=\"304\" y2=\"336\"></line>\n<line stroke=\"#B4521F\" stroke-width=\"6\" x1=\"1100\" x2=\"1100\" y1=\"304\" y2=\"336\"></line>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">平行光穿過凸透鏡後聚在一點（橘色點），下方的橘色線是焦距。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b>凸透鏡</b>：中間厚、邊緣薄，像放大鏡。</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b style=\"color:#B4521F\">焦點 F</b>：平行光聚集的那一點。</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b style=\"color:#B4521F\">焦距 f</b>：透鏡中心到焦點的距離。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 12</p>\n\n</section>", "note": "可以在太陽下用放大鏡把光聚成一個小亮點，那就是焦點（注意不要對著眼睛或易燃物）。提醒學生：這裡的 f 是焦距，和前面波速公式裡的頻率 f 是不同的東西，只是剛好用同一個字母。"}, {"id": "images", "html": "<section data-transition=\"fade\" id=\"images\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">凸透鏡成像規律</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">物體放多遠，就成什麼樣的像</h2>\n</div>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">物距（物體到透鏡）</th><th style=\"width:38%;text-align:left\">像的樣子</th><th style=\"width:28%;text-align:left\">應用</th></tr>\n<tr><td>大於 2 倍焦距</td><td>倒立、縮小、實像</td><td>相機、眼睛</td></tr>\n<tr><td>等於 2 倍焦距</td><td>倒立、等大、實像</td><td>—</td></tr>\n<tr style=\"background:#F7E6DC\"><td>在焦距和 2 倍焦距之間</td><td>倒立、放大、實像</td><td>投影機</td></tr>\n<tr><td>等於焦距</td><td>不成像</td><td>—</td></tr>\n<tr style=\"background:#E1ECFA\"><td>小於焦距</td><td>正立、放大、虛像</td><td>放大鏡</td></tr>\n</table>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\"><b style=\"color:#18262B\">實像</b>：可以投影在屏幕上。<b style=\"color:#18262B\">虛像</b>：只能透過透鏡看到，投影不出來。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 13</p>\n\n</section>", "note": "記憶口訣：物體越靠近焦點，像越大；一進入焦距以內，就變成正立的放大虛像。可以拿放大鏡從遠到近看一個字，親眼看到像從倒立縮小、倒立放大，到正立放大的變化。"}, {"id": "rays", "html": "<section data-transition=\"fade\" id=\"rays\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">畫圖找出像</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">兩條光線，就能找到像在哪裡</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"成像作圖：物體在透鏡左邊，一條光線平行主軸射到透鏡後穿過右邊焦點，另一條穿過透鏡中心直線前進，兩線在右邊交會，形成倒立放大的像\" height=\"340\" viewbox=\"0 0 1500 340\" width=\"1500\">\n<line stroke=\"#9AAAA6\" stroke-dasharray=\"12 10\" stroke-width=\"3\" x1=\"40\" x2=\"1460\" y1=\"200\" y2=\"200\"></line>\n<ellipse cx=\"700\" cy=\"200\" fill=\"#9CC0EA\" opacity=\"0.6\" rx=\"30\" ry=\"150\" stroke=\"#2463B8\" stroke-width=\"5\"></ellipse>\n<circle cx=\"500\" cy=\"200\" fill=\"#B4521F\" r=\"12\"></circle>\n<circle cx=\"900\" cy=\"200\" fill=\"#B4521F\" r=\"12\"></circle>\n<line stroke=\"#18262B\" stroke-width=\"10\" x1=\"400\" x2=\"400\" y1=\"200\" y2=\"164\"></line>\n<polygon fill=\"#18262B\" points=\"384,168 400,140 416,168\"></polygon>\n<line stroke=\"#E0A21A\" stroke-width=\"7\" x1=\"400\" x2=\"700\" y1=\"140\" y2=\"140\"></line>\n<line stroke=\"#E0A21A\" stroke-width=\"7\" x1=\"700\" x2=\"1300\" y1=\"140\" y2=\"320\"></line>\n<line stroke=\"#2463B8\" stroke-width=\"7\" x1=\"400\" x2=\"1300\" y1=\"140\" y2=\"320\"></line>\n<line stroke=\"#B4521F\" stroke-width=\"10\" x1=\"1300\" x2=\"1300\" y1=\"200\" y2=\"296\"></line>\n<polygon fill=\"#B4521F\" points=\"1284,292 1300,322 1316,292\"></polygon>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">橘點是焦點。焦距 10 cm、物體放在 15 cm 處 → 像在另一側 30 cm，倒立、放大 2 倍的實像。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:32px;border:2px solid #D3DCD8;border-left:12px solid #E0A21A;border-radius:20px\">\n<h3 style=\"font-size:36px;font-weight:700\">黃色光線</h3>\n<p style=\"font-size:28px;line-height:1.5\">平行主軸射向透鏡 → 穿過後<b>經過另一側的焦點</b>。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:32px;border:2px solid #D3DCD8;border-left:12px solid #2463B8;border-radius:20px\">\n<h3 style=\"font-size:36px;font-weight:700\">藍色光線</h3>\n<p style=\"font-size:28px;line-height:1.5\">經過透鏡中心 → <b>直直前進，不會偏折</b>。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 14</p>\n\n</section>", "note": "兩條線的交點就是像的位置。作圖題只要記住這兩條光線就夠了。這一例的物體在焦距和 2 倍焦距之間，所以對照上一張表，是倒立放大的實像，就是投影機的原理。"}, {"id": "myth", "html": "<section data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" id=\"myth\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">凸透鏡一定會把東西放大嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.1\">不一定。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:36px;line-height:1.5\">物體在<b>焦距以內</b>，才會看到正立、放大的虛像，這就是放大鏡平常的用法。</p>\n<p style=\"font-size:36px;line-height:1.5\">拿放大鏡看<b>遠方的窗戶</b>，看到的是<b>倒立、縮小</b>的像，跟相機拍照的原理一樣。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">波動、聲音與光 · 15</p>\n\n</section>", "note": "現場示範最有說服力：請學生把放大鏡伸直手臂，看教室另一頭或窗外，會看到上下顛倒的小影像。"}, {"id": "quiz", "html": "<section data-transition=\"fade\" id=\"quiz\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:36px;line-height:1.5\">兩位太空人在太空艙外，不用無線電大聲喊，聽得到彼此嗎？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:36px;line-height:1.5\">空氣中聲速 340 m/s，680 Hz 的聲音波長是多少？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:36px;line-height:1.5\">焦距 10 cm 的凸透鏡，物體放在 30 cm 處，會成什麼樣的像？</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">波動、聲音與光 · 16</p>\n\n</section>", "note": "先讓學生自己作答。第 2 題 提醒他們用 λ = v ÷ f；第 3 題 先算 30 cm 是焦距的幾倍，再查成像規律表。"}, {"id": "answers", "html": "<section data-transition=\"fade\" id=\"answers\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:700\">聽不到</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">太空是真空，沒有介質，聲音傳不出去。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:700\">0.5 公尺</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:28px;line-height:1.5;color:#BFCDC9\">λ = v ÷ f = 340 ÷ 680 = 0.5 m</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:700\">倒立、縮小的實像</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">30 cm 大於 2 倍焦距（20 cm），就像相機。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.4\">波傳的是能量，不是東西。<br/><span style=\"color:#E58A55\">聲音需要介質，光不用；凸透鏡成像看物距。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">波動、聲音與光 · 17</p>\n\n</section>", "note": "回到開場的謎題：聲波波長和門縫、轉角差不多大，所以能繞過去；光的波長極短，幾乎只走直線，被牆擋住就看不到人。"}]}, "waves-en": {"title": "Waves, Sound & Light", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">PHYSICS</p>\n<h1 style=\"font-size:104px;font-weight:900;line-height:1.05;color:#F3F5F2\">Waves,<br>Sound &amp; Light</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">How do sound and light travel to you?</p>\n</div>\n<svg aria-label=\"Three waves: a long orange wave on top, a shorter blue wave in the middle, and yellow light rays passing through a lens to meet at a point\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<path d=\"M20 110 C 110 20, 200 20, 290 110 S 470 200, 560 110 S 650 20, 700 70\" fill=\"none\" stroke=\"#E58A55\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<path d=\"M20 250 C 60 200, 100 200, 140 250 S 220 300, 260 250 S 340 200, 380 250 S 460 300, 500 250 S 580 200, 620 250 S 680 290, 700 270\" fill=\"none\" stroke=\"#7FB0F2\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<line x1=\"20\" y1=\"350\" x2=\"330\" y2=\"350\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"20\" y1=\"400\" x2=\"330\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"20\" y1=\"450\" x2=\"330\" y2=\"450\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"350\" x2=\"560\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"450\" x2=\"560\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<line x1=\"330\" y1=\"400\" x2=\"560\" y2=\"400\" stroke=\"#FFC94D\" stroke-width=\"6\"/>\n<ellipse cx=\"330\" cy=\"400\" rx=\"22\" ry=\"70\" fill=\"#7FB0F2\" opacity=\"0.55\" stroke=\"#F3F5F2\" stroke-width=\"4\"/>\n<circle cx=\"560\" cy=\"400\" r=\"12\" fill=\"#E58A55\"/>\n</svg>\n\n</section>", "note": "This lesson starts with waves. Sound and light are both waves, just with different personalities. We meet waves first, then look at sound and light, and finish by predicting what image a convex lens makes."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why can you hear the next room, but not see into it?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Sound</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Slips under doors and bends around corners, so <b style=\"color:#18262B\">you hear it through a wall</b>.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M9 18h6M10 22h4M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Light</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Travels almost only in straight lines, so <b style=\"color:#18262B\">a wall blocks it</b> and you can’t see who’s there.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Sound and light are both <b style=\"color:#B4521F\">waves</b>, with different personalities. Let’s meet them.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 2</p>\n\n</section>", "note": "Let students guess. The answer has to do with wavelength: sound waves are tens of centimeters to a few meters long, about the size of doorways and corners, so they bend around them easily. Light’s wavelength is tiny, so it travels almost in straight lines. Come back to this after teaching wavelength."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Read a wave</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Name wavelength and frequency, and use v = fλ.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M21 12a8 8 0 0 1-11.6 7.1L3 21l1.9-6.4A8 8 0 1 1 21 12z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Explain sound</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Tell its three properties apart and why it needs a medium.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Predict images</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Say what image a convex lens makes at each distance.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 3</p>\n\n</section>", "note": "The three goals match the three parts: waves, sound, and light with lenses. We end with a myth and a three-question quiz."}, {"id": "wave", "html": "<section id=\"wave\" data-section=\"What a wave is: wavelength, frequency and wave speed\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WHAT IS A WAVE?</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A wave carries energy, not stuff</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A stadium wave: a row of people, a few in the middle standing with arms up, the rest seated; an arrow shows the wave moving right while everyone stays in their seat\" width=\"1600\" height=\"300\" viewBox=\"0 0 1600 300\">\n<line x1=\"40\" y1=\"270\" x2=\"1560\" y2=\"270\" stroke=\"#9AAAA6\" stroke-width=\"6\"/>\n<g fill=\"#4F5F64\">\n<circle cx=\"100\" cy=\"200\" r=\"22\"/><rect x=\"80\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"220\" cy=\"200\" r=\"22\"/><rect x=\"200\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"340\" cy=\"200\" r=\"22\"/><rect x=\"320\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"460\" cy=\"190\" r=\"22\"/><rect x=\"440\" y=\"212\" width=\"40\" height=\"58\" rx=\"10\"/>\n</g>\n<g fill=\"#B4521F\">\n<circle cx=\"580\" cy=\"150\" r=\"22\"/><rect x=\"560\" y=\"172\" width=\"40\" height=\"98\" rx=\"10\"/><line x1=\"580\" y1=\"128\" x2=\"580\" y2=\"70\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<circle cx=\"700\" cy=\"110\" r=\"22\"/><rect x=\"680\" y=\"132\" width=\"40\" height=\"138\" rx=\"10\"/><line x1=\"700\" y1=\"88\" x2=\"700\" y2=\"30\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n<circle cx=\"820\" cy=\"150\" r=\"22\"/><rect x=\"800\" y=\"172\" width=\"40\" height=\"98\" rx=\"10\"/><line x1=\"820\" y1=\"128\" x2=\"820\" y2=\"70\" stroke=\"#B4521F\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n</g>\n<g fill=\"#4F5F64\">\n<circle cx=\"940\" cy=\"190\" r=\"22\"/><rect x=\"920\" y=\"212\" width=\"40\" height=\"58\" rx=\"10\"/>\n<circle cx=\"1060\" cy=\"200\" r=\"22\"/><rect x=\"1040\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"1180\" cy=\"200\" r=\"22\"/><rect x=\"1160\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n<circle cx=\"1300\" cy=\"200\" r=\"22\"/><rect x=\"1280\" y=\"222\" width=\"40\" height=\"48\" rx=\"10\"/>\n</g>\n<line x1=\"1380\" y1=\"120\" x2=\"1520\" y2=\"120\" stroke=\"#2463B8\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"1520,96 1560,120 1520,144\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">A stadium wave: the “stand up” moves right, but everyone stays in their own seat.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:40px\">\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\">A wave is a <b>vibration</b> passed along, one neighbor to the next. What travels is <b style=\"color:#B4521F\">energy</b>; the material stays put.</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\">Drop a stone in a pond: ripples spread out, but a leaf on the water just <b>bobs up and down</b>.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 4</p>\n\n</section>", "note": "Have the class do a stadium wave. Each person just stands and sits, never leaving their seat, yet the “stand up” travels across the room. That is a wave: it carries energy, not stuff."}, {"id": "parts", "html": "<section id=\"parts\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Three things to know about a wave</h2>\n<svg aria-label=\"A wavy line: an orange bracket marks the distance between two crests as the wavelength, and a blue line marks the height from the middle line to a crest as the amplitude\" width=\"1664\" height=\"250\" viewBox=\"0 0 1664 250\">\n<line x1=\"0\" y1=\"170\" x2=\"1560\" y2=\"170\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<path d=\"M0 170 C 80 50, 170 50, 250 170 S 420 290, 500 170 S 670 50, 750 170 S 920 290, 1000 170 S 1170 50, 1250 170 S 1420 290, 1500 170\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<line x1=\"125\" y1=\"30\" x2=\"625\" y2=\"30\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"125\" y1=\"12\" x2=\"125\" y2=\"48\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"625\" y1=\"12\" x2=\"625\" y2=\"48\" stroke=\"#B4521F\" stroke-width=\"8\"/>\n<line x1=\"1125\" y1=\"82\" x2=\"1125\" y2=\"170\" stroke=\"#2463B8\" stroke-width=\"10\"/>\n<polygon points=\"1112,96 1125,74 1138,96\" fill=\"#2463B8\"/>\n</svg>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #B4521F;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Wavelength <span style=\"color:#B4521F\">λ</span></h3>\n<p style=\"font-size:24px;color:#4F5F64\">Unit: meters (m)</p>\n<p style=\"font-size:30px;line-height:1.5\">The distance from one <b>crest</b> to the next (orange bracket).</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #2463B8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Amplitude</h3>\n<p style=\"font-size:24px;color:#4F5F64\">How tall the wave is</p>\n<p style=\"font-size:30px;line-height:1.5\">The height of a crest above the middle (blue line). Bigger = more energy.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-top:12px solid #18262B;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Frequency <span style=\"color:#4F5F64\">f</span></h3>\n<p style=\"font-size:24px;color:#4F5F64\">Unit: hertz (Hz)</p>\n<p style=\"font-size:30px;line-height:1.5\"><b>Vibrations per second.</b> 100 Hz means 100 vibrations every second.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 5</p>\n\n</section>", "note": "Wavelength and amplitude show up in the picture; frequency is about time: how many waves pass each second. Use a jump rope: swing it faster for higher frequency, swing it harder (higher) for bigger amplitude."}, {"id": "speed", "html": "<section id=\"speed\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">WAVE SPEED</p>\n<div style=\"display:flex;align-items:flex-end;gap:56px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#F3F5F2\">v</p>\n<p style=\"font-size:32px;color:#BFCDC9\">speed (m/s)</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#7FB0F2\">f</p>\n<p style=\"font-size:32px;color:#BFCDC9\">frequency (Hz)</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;line-height:1.1;color:#BFCDC9\">×</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:200px;font-weight:700;line-height:1;color:#E58A55\">λ</p>\n<p style=\"font-size:32px;color:#BFCDC9\">wavelength (m)</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;line-height:1.4\">Example: sound in air travels about 340 m/s. A 170 Hz sound has<br>λ = v ÷ f = 340 ÷ 170 = <span style=\"color:#E58A55\">2 meters</span></p>\n<p style=\"font-size:24px;line-height:1.5;color:#BFCDC9\">For one kind of wave in one material, the speed stays the same: higher frequency means shorter wavelength.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Waves, Sound &amp; Light · 6</p>\n\n</section>", "note": "One way to see it: the wave vibrates f times per second and moves one wavelength each time, so it covers f × λ every second. Like Ohm’s law, know two and you can find the third. 340 m/s is roughly the speed of sound in air at about 15 °C."}, {"id": "kinds", "html": "<section id=\"kinds\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">TWO SHAPES OF WAVES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Transverse and longitudinal</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Transverse</h3>\n<svg aria-label=\"Transverse wave: a rope rises and falls; a blue arrow shows the wave moving right and an orange arrow shows the rope moving up and down\" width=\"700\" height=\"200\" viewBox=\"0 0 700 200\">\n<path d=\"M20 100 C 70 20, 120 20, 170 100 S 270 180, 320 100 S 420 20, 470 100 S 570 180, 620 100\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"7\" stroke-linecap=\"round\"/>\n<line x1=\"640\" y1=\"100\" x2=\"680\" y2=\"100\" stroke=\"#2463B8\" stroke-width=\"8\"/>\n<polygon points=\"672,86 698,100 672,114\" fill=\"#2463B8\"/>\n<line x1=\"95\" y1=\"70\" x2=\"95\" y2=\"150\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<polygon points=\"84,74 95,54 106,74\" fill=\"#B4521F\"/>\n<polygon points=\"84,146 95,166 106,146\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:32px;line-height:1.5\">Like shaking a rope: it moves <b style=\"color:#B4521F\">up and down</b> while the wave travels <b style=\"color:#2463B8\">sideways</b>.</p>\n<p style=\"font-size:28px;color:#4F5F64\">Examples: rope waves, <b style=\"color:#18262B\">light</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<h3 style=\"font-size:44px;font-weight:800\">Longitudinal</h3>\n<svg aria-label=\"Longitudinal wave: vertical lines bunched together in some places and spread apart in others, like a pushed spring; a blue arrow shows the wave moving right and an orange double arrow shows back-and-forth motion\" width=\"700\" height=\"200\" viewBox=\"0 0 700 200\">\n<g stroke=\"#18262B\" stroke-width=\"6\">\n<line x1=\"30\" y1=\"50\" x2=\"30\" y2=\"150\"/><line x1=\"48\" y1=\"50\" x2=\"48\" y2=\"150\"/><line x1=\"64\" y1=\"50\" x2=\"64\" y2=\"150\"/><line x1=\"78\" y1=\"50\" x2=\"78\" y2=\"150\"/>\n<line x1=\"120\" y1=\"50\" x2=\"120\" y2=\"150\"/><line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"150\"/><line x1=\"220\" y1=\"50\" x2=\"220\" y2=\"150\"/>\n<line x1=\"256\" y1=\"50\" x2=\"256\" y2=\"150\"/><line x1=\"274\" y1=\"50\" x2=\"274\" y2=\"150\"/><line x1=\"290\" y1=\"50\" x2=\"290\" y2=\"150\"/><line x1=\"304\" y1=\"50\" x2=\"304\" y2=\"150\"/>\n<line x1=\"346\" y1=\"50\" x2=\"346\" y2=\"150\"/><line x1=\"396\" y1=\"50\" x2=\"396\" y2=\"150\"/><line x1=\"446\" y1=\"50\" x2=\"446\" y2=\"150\"/>\n<line x1=\"482\" y1=\"50\" x2=\"482\" y2=\"150\"/><line x1=\"500\" y1=\"50\" x2=\"500\" y2=\"150\"/><line x1=\"516\" y1=\"50\" x2=\"516\" y2=\"150\"/><line x1=\"530\" y1=\"50\" x2=\"530\" y2=\"150\"/>\n<line x1=\"572\" y1=\"50\" x2=\"572\" y2=\"150\"/><line x1=\"620\" y1=\"50\" x2=\"620\" y2=\"150\"/>\n</g>\n<line x1=\"640\" y1=\"100\" x2=\"680\" y2=\"100\" stroke=\"#2463B8\" stroke-width=\"8\"/>\n<polygon points=\"672,86 698,100 672,114\" fill=\"#2463B8\"/>\n<line x1=\"150\" y1=\"180\" x2=\"250\" y2=\"180\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<polygon points=\"152,169 132,180 152,191\" fill=\"#B4521F\"/>\n<polygon points=\"248,169 268,180 248,191\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:32px;line-height:1.5\">Like pushing a spring: it squeezes <b style=\"color:#B4521F\">back and forth</b> in the <b style=\"color:#2463B8\">same direction</b> the wave travels.</p>\n<p style=\"font-size:28px;color:#4F5F64\">Examples: spring waves, <b style=\"color:#18262B\">sound</b></p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 7</p>\n\n</section>", "note": "A Slinky shows both: wiggle it side to side for a transverse wave, push and pull it for a longitudinal wave. Sound is air being squeezed and stretched (longitudinal); light is transverse."}, {"id": "sound3", "html": "<section id=\"sound3\" data-section=\"Sound: its three properties and why it needs a medium\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">SOUND</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Three properties of sound</h2>\n</div>\n<table style=\"font-size:34px;color:#18262B\">\n<tr><th style=\"width:22%;text-align:left\">Property</th><th style=\"width:36%;text-align:left\">Set by</th><th style=\"width:42%;text-align:left\">Everyday example</th></tr>\n<tr><td><b>Loudness</b></td><td><span style=\"color:#2463B8\">Amplitude</span>: bigger is louder</td><td>Whispering vs. shouting</td></tr>\n<tr><td><b>Pitch</b></td><td><span style=\"color:#B4521F\">Frequency</span>: higher is shriller</td><td>A bird’s chirp (high) vs. a bass drum (low)</td></tr>\n<tr><td><b>Timbre</b></td><td>Wave shape: different for every instrument</td><td>Piano and violin playing the same note still sound different</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Human ears hear about <b>20–20,000 Hz</b>. Higher than that is ultrasound, which dogs and bats can hear.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 8</p>\n\n</section>", "note": "Connect to the last section: amplitude sets loudness, frequency sets pitch. A free tone-generator app lets students hear the pitch rise as you slide the frequency up."}, {"id": "medium", "html": "<section id=\"medium\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">SOUND NEEDS A MEDIUM</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Can you hear an explosion in space?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:56px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<p style=\"font-size:96px;font-weight:900;line-height:1.05;color:#B4521F\">No.</p>\n<p style=\"font-size:32px;line-height:1.5\">Sound travels by particles in a medium <b>pushing their neighbors</b>. Space is a vacuum with no particles to push, so sound can’t travel.</p>\n<p style=\"font-size:32px;line-height:1.5\">Light doesn’t need a medium, which is how sunlight crosses space to reach Earth.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px\">\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:52%;text-align:left\">Traveling through</th><th style=\"width:48%;text-align:right\">Speed (about)</th></tr>\n<tr><td>Sound in air</td><td style=\"text-align:right\">340 m/s</td></tr>\n<tr><td>Sound in water</td><td style=\"text-align:right\">1,500 m/s</td></tr>\n<tr><td>Sound in steel</td><td style=\"text-align:right\">5,000 m/s</td></tr>\n<tr style=\"background:#E1ECFA\"><td><b>Light</b></td><td style=\"text-align:right\"><b>300,000,000 m/s</b></td></tr>\n</table>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Light is far faster, which is why you <b style=\"color:#18262B\">see lightning before you hear thunder</b>.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 9</p>\n\n</section>", "note": "The “boom” in space movies is a sound effect; real space is silent. Extension: count the seconds between a lightning flash and the thunder, multiply by 340, and you get roughly how many meters away it struck. All speeds are approximate and change with temperature and material."}, {"id": "reflect", "html": "<section id=\"reflect\" data-section=\"Light: reflection, refraction and convex lenses\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LIGHT</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Reflection: light bounces</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:760px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Reflection: a ray of light hits a mirror at an angle and bounces off; a dashed normal line stands between them, and the two angles are equal\" width=\"760\" height=\"420\" viewBox=\"0 0 760 420\">\n<rect x=\"60\" y=\"340\" width=\"640\" height=\"24\" fill=\"#9CC0EA\" stroke=\"#2463B8\" stroke-width=\"4\"/>\n<line x1=\"60\" y1=\"364\" x2=\"700\" y2=\"364\" stroke=\"#18262B\" stroke-width=\"6\"/>\n<line x1=\"380\" y1=\"40\" x2=\"380\" y2=\"340\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-dasharray=\"14 10\"/>\n<line x1=\"140\" y1=\"100\" x2=\"380\" y2=\"340\" stroke=\"#E0A21A\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"262,206 290,250 246,236\" fill=\"#E0A21A\"/>\n<line x1=\"380\" y1=\"340\" x2=\"620\" y2=\"100\" stroke=\"#E0A21A\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n<polygon points=\"514,206 530,162 486,178\" fill=\"#E0A21A\"/>\n<path d=\"M 380 250 A 90 90 0 0 0 316 276\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<path d=\"M 380 250 A 90 90 0 0 1 444 276\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">The dashed “normal” line is at right angles to the mirror. The two orange angles match.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:34px;line-height:1.5\">Light travels in <b>straight lines</b>, which is why blocked light makes a shadow.</p>\n<p style=\"font-size:34px;line-height:1.5\">When light hits a smooth surface it <b>bounces off</b>, like a ball off a wall.</p>\n<p style=\"font-size:44px;font-weight:800;line-height:1.35;color:#B4521F\">Angle in = angle out</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">Examples: mirrors, reflections on a calm lake, bike reflectors.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 10</p>\n\n</section>", "note": "Shine a flashlight at a mirror and change the angle: the reflected beam moves too, and the two angles always match. Angles are measured from the normal line, not from the mirror surface."}, {"id": "refract", "html": "<section id=\"refract\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LIGHT</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Refraction: light bends</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A chopstick standing in a glass of water looks bent at the water’s surface\" width=\"640\" height=\"440\" viewBox=\"0 0 640 440\">\n<path d=\"M150 60 L180 420 L460 420 L490 60\" fill=\"none\" stroke=\"#4F5F64\" stroke-width=\"8\" stroke-linejoin=\"round\"/>\n<path d=\"M163 200 L180 420 L460 420 L477 200 Z\" fill=\"#9CC0EA\" opacity=\"0.7\"/>\n<line x1=\"163\" y1=\"200\" x2=\"477\" y2=\"200\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<line x1=\"230\" y1=\"20\" x2=\"330\" y2=\"200\" stroke=\"#8A5A2B\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n<line x1=\"330\" y1=\"200\" x2=\"452\" y2=\"318\" stroke=\"#8A5A2B\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n<line x1=\"330\" y1=\"200\" x2=\"430\" y2=\"380\" stroke=\"#8A5A2B\" stroke-width=\"6\" stroke-dasharray=\"10 10\" opacity=\"0.5\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Solid: what you see. Faint dashes: where the chopstick really is.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:34px;line-height:1.5\">When light passes from water into air, it <b>changes speed</b>, so its direction <b style=\"color:#B4521F\">bends</b>. That’s refraction.</p>\n<p style=\"font-size:34px;line-height:1.5\">That’s why the chopstick <b>looks broken</b> at the surface, even though it’s perfectly straight.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\">More examples: a pool looks shallower than it is; glasses and magnifiers use refraction to bend light.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 11</p>\n\n</section>", "note": "Put a pencil or chopstick in a clear glass of water and look from the side. Remind students: reflection is light bouncing back; refraction is light going through but changing direction. Lenses work by refraction."}, {"id": "lens", "html": "<section id=\"lens\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">CONVEX LENS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A convex lens brings light to a point</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Three parallel light rays enter a convex lens from the left and meet at the focal point on the right; the distance from the lens center to that point is the focal length\" width=\"1500\" height=\"340\" viewBox=\"0 0 1500 340\">\n<line x1=\"40\" y1=\"170\" x2=\"1460\" y2=\"170\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<line x1=\"60\" y1=\"70\" x2=\"700\" y2=\"70\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"60\" y1=\"170\" x2=\"700\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"60\" y1=\"270\" x2=\"700\" y2=\"270\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"70\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"270\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<line x1=\"700\" y1=\"170\" x2=\"1100\" y2=\"170\" stroke=\"#E0A21A\" stroke-width=\"8\"/>\n<ellipse cx=\"700\" cy=\"170\" rx=\"36\" ry=\"150\" fill=\"#9CC0EA\" opacity=\"0.6\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<circle cx=\"1100\" cy=\"170\" r=\"16\" fill=\"#B4521F\"/>\n<line x1=\"700\" y1=\"320\" x2=\"1100\" y2=\"320\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<line x1=\"700\" y1=\"304\" x2=\"700\" y2=\"336\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n<line x1=\"1100\" y1=\"304\" x2=\"1100\" y2=\"336\" stroke=\"#B4521F\" stroke-width=\"6\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Parallel rays pass through and meet at one point (orange dot). The orange line below is the focal length.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b>Convex lens:</b> thick in the middle, thin at the edges, like a magnifier.</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b style=\"color:#B4521F\">Focal point F:</b> where parallel rays meet.</p>\n<p style=\"font-size:32px;line-height:1.5;background:#FBFCFA;padding:32px;border-radius:20px\"><b style=\"color:#B4521F\">Focal length f:</b> from the lens center to the focal point.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 12</p>\n\n</section>", "note": "Outdoors, a magnifier can focus sunlight into a small bright spot: that’s the focal point (never aim it at eyes or anything flammable). Remind students that this f means focal length; it is not the frequency f from the wave-speed formula, just the same letter."}, {"id": "images", "html": "<section id=\"images\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">CONVEX LENS IMAGES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Where the object is decides the image</h2>\n</div>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:36%;text-align:left\">Object distance</th><th style=\"width:38%;text-align:left\">Image</th><th style=\"width:26%;text-align:left\">Used in</th></tr>\n<tr><td>More than 2f</td><td>Upside down, smaller, real</td><td>Camera, eye</td></tr>\n<tr><td>Exactly 2f</td><td>Upside down, same size, real</td><td>—</td></tr>\n<tr style=\"background:#F7E6DC\"><td>Between f and 2f</td><td>Upside down, larger, real</td><td>Projector</td></tr>\n<tr><td>Exactly f</td><td>No image</td><td>—</td></tr>\n<tr style=\"background:#E1ECFA\"><td>Less than f</td><td>Upright, larger, virtual</td><td>Magnifier</td></tr>\n</table>\n<p style=\"font-size:28px;line-height:1.5;color:#4F5F64\"><b style=\"color:#18262B\">Real image:</b> can be projected on a screen. <b style=\"color:#18262B\">Virtual image:</b> seen only by looking through the lens.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 13</p>\n\n</section>", "note": "Memory trick: the closer the object gets to the focal point, the bigger the image; once it is inside the focal length, the image flips to upright and virtual. Look at a word through a magnifier from far to near to see the image go from small and upside down, to large and upside down, to large and upright."}, {"id": "rays", "html": "<section id=\"rays\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">DRAW IT</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Two rays find the image</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"Ray diagram: an object stands left of the lens; one ray runs parallel to the axis, bends through the far focal point; another passes straight through the lens center; they cross on the right, forming a larger upside-down image\" width=\"1500\" height=\"340\" viewBox=\"0 0 1500 340\">\n<line x1=\"40\" y1=\"200\" x2=\"1460\" y2=\"200\" stroke=\"#9AAAA6\" stroke-width=\"3\" stroke-dasharray=\"12 10\"/>\n<ellipse cx=\"700\" cy=\"200\" rx=\"30\" ry=\"150\" fill=\"#9CC0EA\" opacity=\"0.6\" stroke=\"#2463B8\" stroke-width=\"5\"/>\n<circle cx=\"500\" cy=\"200\" r=\"12\" fill=\"#B4521F\"/>\n<circle cx=\"900\" cy=\"200\" r=\"12\" fill=\"#B4521F\"/>\n<line x1=\"400\" y1=\"200\" x2=\"400\" y2=\"164\" stroke=\"#18262B\" stroke-width=\"10\"/>\n<polygon points=\"384,168 400,140 416,168\" fill=\"#18262B\"/>\n<line x1=\"400\" y1=\"140\" x2=\"700\" y2=\"140\" stroke=\"#E0A21A\" stroke-width=\"7\"/>\n<line x1=\"700\" y1=\"140\" x2=\"1300\" y2=\"320\" stroke=\"#E0A21A\" stroke-width=\"7\"/>\n<line x1=\"400\" y1=\"140\" x2=\"1300\" y2=\"320\" stroke=\"#2463B8\" stroke-width=\"7\"/>\n<line x1=\"1300\" y1=\"200\" x2=\"1300\" y2=\"296\" stroke=\"#B4521F\" stroke-width=\"10\"/>\n<polygon points=\"1284,292 1300,322 1316,292\" fill=\"#B4521F\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Orange dots are focal points. f = 10 cm, object at 15 cm → image at 30 cm on the other side, upside down and 2× larger.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:32px;border:2px solid #D3DCD8;border-left:12px solid #E0A21A;border-radius:20px\">\n<h3 style=\"font-size:36px;font-weight:800\">Yellow ray</h3>\n<p style=\"font-size:28px;line-height:1.5\">Comes in parallel to the axis → bends <b>through the far focal point</b>.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:32px;border:2px solid #D3DCD8;border-left:12px solid #2463B8;border-radius:20px\">\n<h3 style=\"font-size:36px;font-weight:800\">Blue ray</h3>\n<p style=\"font-size:28px;line-height:1.5\">Goes through the lens center → <b>keeps going straight</b>.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 14</p>\n\n</section>", "note": "Where the two rays cross is where the image forms. These two rays are all you need for any ray-diagram question. Here the object sits between f and 2f, so by the table on the previous slide the image is real, upside down and larger: how a projector works."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Does a convex lens always magnify?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">Not always.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">Only when the object is <b>inside the focal length</b> do you see an upright, larger, virtual image. That’s the usual magnifier view.</p>\n<p style=\"font-size:34px;line-height:1.5\">Look at a <b>faraway window</b> through a magnifier and you see a <b>small, upside-down</b> image, the same way a camera works.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Waves, Sound &amp; Light · 15</p>\n\n</section>", "note": "A live demo convinces best: have students hold a magnifier at arm’s length and look across the room or out a window. They’ll see a small, upside-down picture."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">Two astronauts on a spacewalk shout without radios. Can they hear each other?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">Sound travels at 340 m/s in air. What is the wavelength of a 680 Hz sound?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">A convex lens has f = 10 cm. An object sits 30 cm away. What image forms?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Waves, Sound &amp; Light · 16</p>\n\n</section>", "note": "Let students answer on their own first. For Q2, remind them λ = v ÷ f. For Q3, ask how many focal lengths 30 cm is, then check the table."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">No</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Space is a vacuum with no medium, so sound can’t travel.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">0.5 meters</p>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:28px;line-height:1.5;color:#BFCDC9\">λ = 340 ÷ 680 = 0.5 m</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">Smaller, upside down, real</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">30 cm is more than 2f (20 cm), like a camera.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Waves carry energy, not stuff.<br><span style=\"color:#E58A55\">Sound needs a medium, light doesn’t; lens images depend on distance.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Waves, Sound &amp; Light · 17</p>\n\n</section>", "note": "Back to the opening puzzle: sound waves are about as long as doorways and corners, so they bend around them; light’s wavelength is tiny, so it travels in nearly straight lines and a wall blocks it."}]}, "chem-reactions-zh": {"title": "化學反應與質量守恆", "lang": "zh", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">化學</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">化學反應與<br>質量守恆</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">物質反應之後，有東西不見嗎？<br>數一數原子就知道。</p>\n</div>\n<svg aria-label=\"天平一邊放著套了氣球的瓶子，另一邊放砝碼，兩邊剛好平衡\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<polygon points=\"360,420 320,470 400,470\" fill=\"#BFCDC9\"/><line x1=\"360\" y1=\"420\" x2=\"360\" y2=\"150\" stroke=\"#BFCDC9\" stroke-width=\"10\"/><line x1=\"120\" y1=\"150\" x2=\"600\" y2=\"150\" stroke=\"#F3F5F2\" stroke-width=\"10\" stroke-linecap=\"round\"/><line x1=\"150\" y1=\"150\" x2=\"150\" y2=\"300\" stroke=\"#BFCDC9\" stroke-width=\"4\"/><line x1=\"570\" y1=\"150\" x2=\"570\" y2=\"300\" stroke=\"#BFCDC9\" stroke-width=\"4\"/><path d=\"M70 300 H230 L210 330 H90 Z\" fill=\"#BFCDC9\"/><path d=\"M490 300 H650 L630 330 H510 Z\" fill=\"#BFCDC9\"/><path d=\"M125 300 V220 L140 200 V170 H160 V200 L175 220 V300 Z\" fill=\"#7FB0F2\"/><ellipse cx=\"150\" cy=\"150\" rx=\"30\" ry=\"38\" fill=\"#E58A55\"/><rect x=\"525\" y=\"250\" width=\"90\" height=\"50\" rx=\"8\" fill=\"#E58A55\"/><rect x=\"545\" y=\"215\" width=\"50\" height=\"35\" rx=\"6\" fill=\"#E58A55\"/>\n</svg>\n\n</section>", "note": "這一課給完全沒學過化學反應的同學。我們從一個冒泡實驗開始，再數原子看看質量為什麼不會消失，最後學平衡反應式和莫耳。"}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">化學反應會讓東西變輕嗎？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M9 3h6M10 3v6L4.6 18.6A1.6 1.6 0 0 0 6 21h12a1.6 1.6 0 0 0 1.4-2.4L14 9V3M7.5 15h9\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">在開口杯裡</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">小蘇打加白醋冒泡，秤上的數字<b style=\"color:#18262B\">變小了</b>。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M12 3v18M7 21h10M5 7h14M5 7l-3 7a3 3 0 0 0 6 0zM19 7l-3 7a3 3 0 0 0 6 0z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">在密封瓶裡</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">同樣的反應，瓶口套上氣球，數字<b style=\"color:#18262B\">完全沒變</b>。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">同樣的反應，結果卻不同。不見的質量到底跑去哪了？</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 2</p>\n\n</section>", "note": "可以的話現場示範：兩組一樣的器材放在兩台電子秤上。把小蘇打裝進氣球、套在裝白醋的瓶口再倒進去；另一組在開口杯裡做。開始前先讓學生預測。"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M12 3v18M7 21h10M5 7h14M5 7l-3 7a3 3 0 0 0 6 0zM19 7l-3 7a3 3 0 0 0 6 0z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">說明質量守恆</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">解釋為什麼總質量不變。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">平衡反應式</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">用係數讓兩邊原子數相等。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">會用莫耳</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">把公克換算成粒子數量。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 3</p>\n\n</section>", "note": "三個目標對應三段：為什麼質量守恆、怎麼平衡反應式、化學家怎麼用莫耳數粒子。"}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">開始之前</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先認識四個詞</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">反應物</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">反應開始時的物質。CH₄ + O₂ 裡兩者都是反應物。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">生成物</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">反應後產生的新物質，寫在箭頭右邊。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">係數</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">寫在前面的大數字：<b style=\"color:#18262B\">2</b>H₂O 代表兩個水分子。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">下標</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">寫在裡面的小數字：H<b style=\"color:#18262B\">₂</b>O 有兩個 H 原子。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 4</p>\n\n</section>", "note": "橘色卡片講反應前，藍色卡片講反應後或寫法。係數和下標的差別，後面的對照表會再整理一次。"}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"質量守恆\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">化學反應的真面目</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">原子只是換了搭檔</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"左邊是甲烷和兩個氧分子，重新排列成右邊的二氧化碳和兩個水分子；兩邊的原子完全相同\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<circle cx=\"90\" cy=\"110\" r=\"34\" fill=\"#2F3B40\"/><text x=\"90\" y=\"119\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">C</text><circle cx=\"46\" cy=\"80\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"46\" y=\"86\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"134\" cy=\"80\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"134\" y=\"86\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"46\" cy=\"140\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"46\" y=\"146\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"134\" cy=\"140\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"134\" y=\"146\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"68\" cy=\"240\" r=\"26\" fill=\"#B4521F\"/><text x=\"68\" y=\"249\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"112\" cy=\"240\" r=\"26\" fill=\"#B4521F\"/><text x=\"112\" y=\"249\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"68\" cy=\"320\" r=\"26\" fill=\"#B4521F\"/><text x=\"68\" y=\"329\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"112\" cy=\"320\" r=\"26\" fill=\"#B4521F\"/><text x=\"112\" y=\"329\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><line x1=\"190\" y1=\"210\" x2=\"304\" y2=\"210\" stroke=\"#4F5F64\" stroke-width=\"8\" stroke-linecap=\"round\"/><polygon points=\"330,210 304,196 304,224\" fill=\"#4F5F64\"/><circle cx=\"430\" cy=\"110\" r=\"26\" fill=\"#B4521F\"/><text x=\"430\" y=\"119\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"480\" cy=\"110\" r=\"32\" fill=\"#2F3B40\"/><text x=\"480\" y=\"119\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">C</text><circle cx=\"530\" cy=\"110\" r=\"26\" fill=\"#B4521F\"/><text x=\"530\" y=\"119\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"440\" cy=\"240\" r=\"28\" fill=\"#B4521F\"/><text x=\"440\" y=\"249\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"406\" cy=\"266\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"406\" y=\"272\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"474\" cy=\"266\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"474\" y=\"272\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"540\" cy=\"300\" r=\"28\" fill=\"#B4521F\"/><text x=\"540\" y=\"309\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"506\" cy=\"326\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"506\" y=\"332\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"574\" cy=\"326\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"574\" y=\"332\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><text x=\"90\" y=\"30\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">CH₄ + 2O₂</text><text x=\"480\" y=\"30\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">CO₂ + 2H₂O</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">數數看：兩邊都是 1 個 C、4 個 H、4 個 O。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">化學反應中，原子<b>不會被創造，也不會消失</b>。</p>\n<p style=\"font-size:34px;line-height:1.5\">它們拆開、再用新的方式組合，變成新的物質。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">反應前後原子一樣 → 總質量也一樣。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 5</p>\n\n</section>", "note": "有樂高的話可以示範：先拼出 CH₄ 和兩個 O₂，再拆開重組成 CO₂ 和兩個 H₂O，過程中一塊都不多、不少。"}, {"id": "figure", "html": "<section id=\"figure\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">回到謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">質量沒有消失，是跑掉了</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"兩台秤：開口杯的氣體冒出去，從 250.0 克變成 248.6 克；密封瓶的氣體被氣球留住，維持 250.0 克\" width=\"1400\" height=\"320\" viewBox=\"0 0 1400 320\">\n<rect x=\"180\" y=\"170\" width=\"300\" height=\"24\" rx=\"6\" fill=\"#4F5F64\"/><rect x=\"210\" y=\"194\" width=\"240\" height=\"40\" rx=\"8\" fill=\"#18262B\"/><text x=\"330\" y=\"223\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#E58A55\">248.6 g</text><path d=\"M275 80 V170 H385 V80\" fill=\"#E1ECFA\" stroke=\"#18262B\" stroke-width=\"5\"/><line x1=\"295\" y1=\"70\" x2=\"303\" y2=\"32\" stroke=\"#2463B8\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"305,20 296,30 309,33\" fill=\"#2463B8\"/><line x1=\"330\" y1=\"70\" x2=\"338\" y2=\"32\" stroke=\"#2463B8\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"340,20 331,30 344,33\" fill=\"#2463B8\"/><line x1=\"365\" y1=\"70\" x2=\"373\" y2=\"32\" stroke=\"#2463B8\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"375,20 366,30 379,33\" fill=\"#2463B8\"/><text x=\"330\" y=\"270\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">開口杯</text><text x=\"330\" y=\"306\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">250.0 g → 248.6 g</text><rect x=\"900\" y=\"170\" width=\"300\" height=\"24\" rx=\"6\" fill=\"#4F5F64\"/><rect x=\"930\" y=\"194\" width=\"240\" height=\"40\" rx=\"8\" fill=\"#18262B\"/><text x=\"1050\" y=\"223\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#7FE0A0\">250.0 g</text><path d=\"M1010 170 V100 L1025 80 V60 H1075 V80 L1090 100 V170 Z\" fill=\"#E1ECFA\" stroke=\"#18262B\" stroke-width=\"5\"/><ellipse cx=\"1050\" cy=\"30\" rx=\"36\" ry=\"30\" fill=\"#E58A55\"/><text x=\"1050\" y=\"270\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">密封瓶 + 氣球</text><text x=\"1050\" y=\"306\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">250.0 g → 250.0 g</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">課堂示範的典型讀數。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>開口杯</b>：反應產生 CO₂ 氣體，飄到空氣中了。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>密封瓶</b>：氣球把 CO₂ 留住，什麼都沒跑掉。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">把<b>所有東西</b>都秤進去，包括氣體，總質量就不會變。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 6</p>\n\n</section>", "note": "數字僅供參考，減少多少取決於小蘇打的用量。氣球鼓起來，就是有氣體產生的證據。"}, {"id": "formula", "html": "<section id=\"formula\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">質量守恆定律</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">質量</p>\n<p style=\"font-size:32px;color:#BFCDC9\">反應前</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#7FB0F2\">質量</p>\n<p style=\"font-size:32px;color:#BFCDC9\">反應後</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:700;line-height:1.4\">反應物總質量 = 生成物總質量</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">法國化學家拉瓦節在 1780 年代，把反應放在密封容器裡秤重，證明了這件事。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">化學反應與質量守恆 · 7</p>\n\n</section>", "note": "這就是化學反應式一定要平衡的原因：反應式兩邊必須有相同的原子。"}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一步一步平衡</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">CH₄ + O₂ → CO₂ + H₂O</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">數 C</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">1 = 1 ✓</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">平衡 H</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">左邊 4 個 H<br>→ 2H₂O</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">平衡 O</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">右邊 4 個 O<br>→ 2O₂</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">檢查</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">C 1=1<br>H 4=4<br>O 4=4</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">CH₄ + <span style=\"color:#2463B8\">2</span>O₂ → CO₂ + <span style=\"color:#2463B8\">2</span>H₂O</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 8</p>\n\n</section>", "note": "平衡時只改係數（前面的大數字）。H 和 O 如果出現在好幾個地方，就留到最後再平衡。"}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一張表看懂</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">係數和下標，差在哪裡？</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">比較</th><th style=\"width:33%;text-align:left\">係數</th><th style=\"width:33%;text-align:left\">下標</th></tr>\n<tr><td>寫在哪裡</td><td>前面：<b>2</b>H₂O</td><td>裡面：H<b>₂</b>O</td></tr>\n<tr><td>代表什麼</td><td>有幾個分子</td><td>一個分子裡有幾個原子</td></tr>\n<tr><td>平衡時可以改嗎？</td><td><span style=\"color:#2463B8\">可以</span></td><td><span style=\"color:#B4521F\">絕對不行</span></td></tr>\n<tr><td>改了會怎樣</td><td>同一種物質變多或變少</td><td>變成另一種物質：H₂O → H₂O₂</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">一句話記住：</b> 只改前面的大數字，不要動裡面的小數字。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 9</p>\n\n</section>", "note": "H₂O₂ 是過氧化氫，也就是消毒用的雙氧水。改一個下標，喝的水就變成消毒水，學生會記得很清楚。"}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">用莫耳來數</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">莫耳是化學家的「一打」</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"一盒 12 顆雞蛋標示 1 打，旁邊一盒很多小粒子標示 1 莫耳 = 6 × 10²³ 個\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<rect x=\"30\" y=\"60\" width=\"320\" height=\"140\" rx=\"16\" fill=\"none\" stroke=\"#D3DCD8\" stroke-width=\"4\"/><ellipse cx=\"70\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"120\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"170\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"220\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"270\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"320\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"70\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"120\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"170\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"220\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"270\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"320\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><rect x=\"400\" y=\"60\" width=\"300\" height=\"140\" rx=\"16\" fill=\"none\" stroke=\"#D3DCD8\" stroke-width=\"4\"/><circle cx=\"430\" cy=\"80\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"467\" cy=\"133\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"504\" cy=\"186\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"541\" cy=\"109\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"578\" cy=\"162\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"615\" cy=\"85\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"652\" cy=\"138\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"449\" cy=\"191\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"486\" cy=\"114\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"523\" cy=\"167\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"560\" cy=\"90\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"597\" cy=\"143\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"634\" cy=\"196\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"431\" cy=\"119\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"468\" cy=\"172\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"505\" cy=\"95\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"542\" cy=\"148\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"579\" cy=\"201\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"616\" cy=\"124\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"653\" cy=\"177\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"450\" cy=\"100\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"487\" cy=\"153\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"524\" cy=\"206\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"561\" cy=\"129\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"598\" cy=\"182\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"635\" cy=\"105\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"432\" cy=\"158\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"469\" cy=\"81\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"506\" cy=\"134\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"543\" cy=\"187\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"580\" cy=\"110\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"617\" cy=\"163\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"654\" cy=\"86\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"451\" cy=\"139\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"488\" cy=\"192\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"525\" cy=\"115\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"562\" cy=\"168\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"599\" cy=\"91\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"636\" cy=\"144\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"433\" cy=\"197\" r=\"7\" fill=\"#2463B8\"/><text x=\"190\" y=\"250\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">1 打 = 12 個</text><text x=\"550\" y=\"250\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">1 莫耳 = 6 × 10²³ 個</text><text x=\"190\" y=\"290\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#4F5F64\">雞蛋</text><text x=\"550\" y=\"290\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#4F5F64\">粒子</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">物質</th><th style=\"width:60%;text-align:left\">1 莫耳重</th></tr>\n<tr><td>CH₄</td><td><b>16 g</b></td></tr>\n<tr><td>H₂O</td><td><b>18 g</b></td></tr>\n<tr><td>O₂</td><td><b>32 g</b></td></tr>\n<tr><td>CO₂</td><td><b>44 g</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\"><b>質量（g）= 莫耳數 × 分子量</b>。原子量：C = 12、H = 1、O = 16。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 10</p>\n\n</section>", "note": "示範每一列怎麼算：H₂O = 2 × 1 + 16 = 18。莫耳只是一個計數單位，就像「一打」，只是大得多。"}, {"id": "example2", "html": "<section id=\"example2\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">例題</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">要讓 16 g 的 CH₄ 完全燃燒，需要多少克 O₂？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">CH₄ 的莫耳數</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">16 ÷ 16<br>= 1 莫耳</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">看係數比</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">CH₄ : O₂<br>= 1 : 2</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">O₂ 的莫耳數</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">1 × 2<br>= 2 莫耳</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">O₂ 的質量</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">2 × 32<br>= 64 g</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">答案：需要 <span style=\"color:#2463B8\">64 g</span> 的 O₂</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 11</p>\n\n</section>", "note": "用前面平衡好的反應式。係數代表莫耳數的比，不是質量的比。"}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">蠟燭越燒越輕，質量消失了嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">沒有。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">蠟和氧氣反應，變成 <b>CO₂ 和水蒸氣</b>。兩者都是氣體，飄走了，秤就秤不到。</p>\n<p style=\"font-size:34px;line-height:1.5\">把蠟燭放在<b>密封罐</b>裡、放在秤上燒，讀數就不會變。所有原子都還在。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">化學反應與質量守恆 · 12</p>\n\n</section>", "note": "相反的驚喜：鋼絲絨燃燒後會變重，因為它從空氣中得到了氧。兩種情況遵守的是同一條規則。"}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:34px;line-height:1.5\">鋼絲絨燃燒後變重了。這違反質量守恆嗎？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:34px;line-height:1.5\">平衡這個反應式：H₂ + O₂ → H₂O</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:34px;line-height:1.5\">2 莫耳的 H₂O 是多少克？</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">化學反應與質量守恆 · 13</p>\n\n</section>", "note": "先讓學生自己作答。第 2 題提醒他們只能改係數。"}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:700\">沒有</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">它從空氣中得到了氧原子。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:700\">2H₂ + O₂ → 2H₂O</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">H 4 = 4，O 2 = 2。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:700\">36 g</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">2 × 18 = 36</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">原子只會重新排列，不會消失。<br><span style=\"color:#E58A55\">用係數平衡，用莫耳計數。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">化學反應與質量守恆 · 14</p>\n\n</section>", "note": "可選出場單：「用一句話說明，為什麼密封瓶的質量沒有改變？」請學生用到「原子」和「質量守恆」兩個詞。"}]}, "chem-reactions-en": {"title": "Chemical Reactions & Conservation of Mass", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">CHEMISTRY</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Chemical<br>Reactions</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">When substances react, does anything get lost?<br>Count the atoms and find out.</p>\n</div>\n<svg aria-label=\"A balance holding a bottle with a balloon on one side and weights on the other, perfectly level\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<polygon points=\"360,420 320,470 400,470\" fill=\"#BFCDC9\"/><line x1=\"360\" y1=\"420\" x2=\"360\" y2=\"150\" stroke=\"#BFCDC9\" stroke-width=\"10\"/><line x1=\"120\" y1=\"150\" x2=\"600\" y2=\"150\" stroke=\"#F3F5F2\" stroke-width=\"10\" stroke-linecap=\"round\"/><line x1=\"150\" y1=\"150\" x2=\"150\" y2=\"300\" stroke=\"#BFCDC9\" stroke-width=\"4\"/><line x1=\"570\" y1=\"150\" x2=\"570\" y2=\"300\" stroke=\"#BFCDC9\" stroke-width=\"4\"/><path d=\"M70 300 H230 L210 330 H90 Z\" fill=\"#BFCDC9\"/><path d=\"M490 300 H650 L630 330 H510 Z\" fill=\"#BFCDC9\"/><path d=\"M125 300 V220 L140 200 V170 H160 V200 L175 220 V300 Z\" fill=\"#7FB0F2\"/><ellipse cx=\"150\" cy=\"150\" rx=\"30\" ry=\"38\" fill=\"#E58A55\"/><rect x=\"525\" y=\"250\" width=\"90\" height=\"50\" rx=\"8\" fill=\"#E58A55\"/><rect x=\"545\" y=\"215\" width=\"50\" height=\"35\" rx=\"6\" fill=\"#E58A55\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied chemical reactions. We start with a fizzing experiment, then count atoms to see why mass never disappears, and finish with balancing equations and the mole."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Does a reaction make things lighter?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M9 3h6M10 3v6L4.6 18.6A1.6 1.6 0 0 0 6 21h12a1.6 1.6 0 0 0 1.4-2.4L14 9V3M7.5 15h9\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">In an open cup</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Baking soda + vinegar fizz, and the scale reading <b style=\"color:#18262B\">drops</b>.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M12 3v18M7 21h10M5 7h14M5 7l-3 7a3 3 0 0 0 6 0zM19 7l-3 7a3 3 0 0 0 6 0z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">In a sealed bottle</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">The same reaction under a balloon, and the reading <b style=\"color:#18262B\">stays the same</b>.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Same reaction, different result. So where did the missing mass go?</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 2</p>\n\n</section>", "note": "Demo if you can: two identical setups on two digital scales. Put baking soda in a balloon and stretch it over a bottle of vinegar; tip it in. Do the open version in a cup. Let students predict before you start."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M12 3v18M7 21h10M5 7h14M5 7l-3 7a3 3 0 0 0 6 0zM19 7l-3 7a3 3 0 0 0 6 0z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Explain conservation</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Say why total mass stays the same.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Balance equations</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Use coefficients so atoms add up.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Use the mole</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Turn grams into particle counts.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 3</p>\n\n</section>", "note": "The three goals match the three parts: why mass is conserved, how to balance an equation, and how chemists count with moles."}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BEFORE YOU START</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Four words you need first</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Reactant</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">What you start with. In CH₄ + O₂, both are reactants.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Product</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">The new substances that form, written after the arrow.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Coefficient</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">The big number in front: <b style=\"color:#18262B\">2</b>H₂O means two water molecules.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Subscript</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">The small number inside: H<b style=\"color:#18262B\">₂</b>O has two H atoms.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 4</p>\n\n</section>", "note": "Orange cards are about what goes in; blue cards are about what comes out or how it is written. Coefficient vs. subscript comes back in the comparison table."}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"Conservation of mass\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WHAT A REACTION REALLY IS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Atoms only change partners</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Methane and two oxygen molecules on the left rearrange into carbon dioxide and two water molecules on the right; the same atoms appear on both sides\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<circle cx=\"90\" cy=\"110\" r=\"34\" fill=\"#2F3B40\"/><text x=\"90\" y=\"119\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">C</text><circle cx=\"46\" cy=\"80\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"46\" y=\"86\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"134\" cy=\"80\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"134\" y=\"86\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"46\" cy=\"140\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"46\" y=\"146\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"134\" cy=\"140\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"134\" y=\"146\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"68\" cy=\"240\" r=\"26\" fill=\"#B4521F\"/><text x=\"68\" y=\"249\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"112\" cy=\"240\" r=\"26\" fill=\"#B4521F\"/><text x=\"112\" y=\"249\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"68\" cy=\"320\" r=\"26\" fill=\"#B4521F\"/><text x=\"68\" y=\"329\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"112\" cy=\"320\" r=\"26\" fill=\"#B4521F\"/><text x=\"112\" y=\"329\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><line x1=\"190\" y1=\"210\" x2=\"304\" y2=\"210\" stroke=\"#4F5F64\" stroke-width=\"8\" stroke-linecap=\"round\"/><polygon points=\"330,210 304,196 304,224\" fill=\"#4F5F64\"/><circle cx=\"430\" cy=\"110\" r=\"26\" fill=\"#B4521F\"/><text x=\"430\" y=\"119\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"480\" cy=\"110\" r=\"32\" fill=\"#2F3B40\"/><text x=\"480\" y=\"119\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">C</text><circle cx=\"530\" cy=\"110\" r=\"26\" fill=\"#B4521F\"/><text x=\"530\" y=\"119\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"440\" cy=\"240\" r=\"28\" fill=\"#B4521F\"/><text x=\"440\" y=\"249\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"406\" cy=\"266\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"406\" y=\"272\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"474\" cy=\"266\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"474\" y=\"272\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"540\" cy=\"300\" r=\"28\" fill=\"#B4521F\"/><text x=\"540\" y=\"309\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"506\" cy=\"326\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"506\" y=\"332\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><circle cx=\"574\" cy=\"326\" r=\"18\" fill=\"#9AAAA6\"/><text x=\"574\" y=\"332\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"800\" fill=\"#18262B\">H</text><text x=\"90\" y=\"30\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">CH₄ + 2O₂</text><text x=\"480\" y=\"30\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">CO₂ + 2H₂O</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Count them: 1 C, 4 H, 4 O on each side.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">In a reaction, atoms are <b>not created or destroyed</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">They break apart and join up in new ways, making new substances.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Same atoms before and after → same total mass.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 5</p>\n\n</section>", "note": "Use LEGO bricks if you have them: build CH₄ and two O₂, then rebuild into CO₂ and two H₂O without adding or removing a brick."}, {"id": "figure", "html": "<section id=\"figure\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BACK TO THE PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">The mass didn’t vanish. It escaped.</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"Two scales: the open cup lets gas bubble out and drops from 250.0 to 248.6 grams; the sealed bottle traps the gas in a balloon and stays at 250.0 grams\" width=\"1400\" height=\"320\" viewBox=\"0 0 1400 320\">\n<rect x=\"180\" y=\"170\" width=\"300\" height=\"24\" rx=\"6\" fill=\"#4F5F64\"/><rect x=\"210\" y=\"194\" width=\"240\" height=\"40\" rx=\"8\" fill=\"#18262B\"/><text x=\"330\" y=\"223\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#E58A55\">248.6 g</text><path d=\"M275 80 V170 H385 V80\" fill=\"#E1ECFA\" stroke=\"#18262B\" stroke-width=\"5\"/><line x1=\"295\" y1=\"70\" x2=\"303\" y2=\"32\" stroke=\"#2463B8\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"305,20 296,30 309,33\" fill=\"#2463B8\"/><line x1=\"330\" y1=\"70\" x2=\"338\" y2=\"32\" stroke=\"#2463B8\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"340,20 331,30 344,33\" fill=\"#2463B8\"/><line x1=\"365\" y1=\"70\" x2=\"373\" y2=\"32\" stroke=\"#2463B8\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"375,20 366,30 379,33\" fill=\"#2463B8\"/><text x=\"330\" y=\"270\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">Open cup</text><text x=\"330\" y=\"306\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">250.0 g → 248.6 g</text><rect x=\"900\" y=\"170\" width=\"300\" height=\"24\" rx=\"6\" fill=\"#4F5F64\"/><rect x=\"930\" y=\"194\" width=\"240\" height=\"40\" rx=\"8\" fill=\"#18262B\"/><text x=\"1050\" y=\"223\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#7FE0A0\">250.0 g</text><path d=\"M1010 170 V100 L1025 80 V60 H1075 V80 L1090 100 V170 Z\" fill=\"#E1ECFA\" stroke=\"#18262B\" stroke-width=\"5\"/><ellipse cx=\"1050\" cy=\"30\" rx=\"36\" ry=\"30\" fill=\"#E58A55\"/><text x=\"1050\" y=\"270\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">Sealed bottle + balloon</text><text x=\"1050\" y=\"306\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">250.0 g → 250.0 g</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Typical readings from a classroom demo.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Open cup</b>: the reaction makes CO₂ gas, which floats away into the air.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Sealed bottle</b>: the balloon traps the CO₂, so nothing leaves.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">Weigh <b>everything</b>, including gases, and the total never changes.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 6</p>\n\n</section>", "note": "The numbers are illustrative; the drop depends on how much baking soda you use. The balloon inflating is the visible clue that gas was made."}, {"id": "formula", "html": "<section id=\"formula\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">CONSERVATION OF MASS</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">mass</p>\n<p style=\"font-size:32px;color:#BFCDC9\">before</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">=</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#7FB0F2\">mass</p>\n<p style=\"font-size:32px;color:#BFCDC9\">after</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:800;line-height:1.4\">Total mass of reactants = total mass of products</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Antoine Lavoisier showed this in the 1780s by weighing reactions inside sealed containers.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Chemical Reactions &amp; Conservation of Mass · 7</p>\n\n</section>", "note": "This is why chemical equations must be balanced: the equation has to show the same atoms on both sides."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BALANCE IT STEP BY STEP</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.1\">CH₄ + O₂ → CO₂ + H₂O</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Count C</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">1 = 1 ✓</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Fix H</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">4 H left<br>→ 2H₂O</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Fix O</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">4 O right<br>→ 2O₂</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">Check</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">C 1=1<br>H 4=4<br>O 4=4</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">CH₄ + <span style=\"color:#2463B8\">2</span>O₂ → CO₂ + <span style=\"color:#2463B8\">2</span>H₂O</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 8</p>\n\n</section>", "note": "Always balance by changing coefficients (the big numbers in front). Balance H and O last if they appear in more than one place."}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ONE TABLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Coefficient vs. subscript</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">Compare</th><th style=\"width:33%;text-align:left\">Coefficient</th><th style=\"width:33%;text-align:left\">Subscript</th></tr>\n<tr><td>Where it goes</td><td>In front: <b>2</b>H₂O</td><td>Inside: H<b>₂</b>O</td></tr>\n<tr><td>What it counts</td><td>How many molecules</td><td>Atoms in one molecule</td></tr>\n<tr><td>Change it to balance?</td><td><span style=\"color:#2463B8\">Yes</span></td><td><span style=\"color:#B4521F\">Never</span></td></tr>\n<tr><td>If you change it</td><td>More or fewer of the same thing</td><td>A different substance: H₂O → H₂O₂</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">Remember:</b> change the big number in front, never the small number inside.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 9</p>\n\n</section>", "note": "H₂O₂ is hydrogen peroxide, a bleach. Changing a subscript turns drinking water into a disinfectant, which makes the point memorable."}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">COUNTING WITH MOLES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A mole is a chemist’s “dozen”</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"A box of 12 eggs labeled one dozen next to a box of many tiny particles labeled one mole, 6 times 10 to the 23rd\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<rect x=\"30\" y=\"60\" width=\"320\" height=\"140\" rx=\"16\" fill=\"none\" stroke=\"#D3DCD8\" stroke-width=\"4\"/><ellipse cx=\"70\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"120\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"170\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"220\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"270\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"320\" cy=\"110\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"70\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"120\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"170\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"220\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"270\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><ellipse cx=\"320\" cy=\"170\" rx=\"20\" ry=\"26\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><rect x=\"400\" y=\"60\" width=\"300\" height=\"140\" rx=\"16\" fill=\"none\" stroke=\"#D3DCD8\" stroke-width=\"4\"/><circle cx=\"430\" cy=\"80\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"467\" cy=\"133\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"504\" cy=\"186\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"541\" cy=\"109\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"578\" cy=\"162\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"615\" cy=\"85\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"652\" cy=\"138\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"449\" cy=\"191\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"486\" cy=\"114\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"523\" cy=\"167\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"560\" cy=\"90\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"597\" cy=\"143\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"634\" cy=\"196\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"431\" cy=\"119\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"468\" cy=\"172\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"505\" cy=\"95\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"542\" cy=\"148\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"579\" cy=\"201\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"616\" cy=\"124\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"653\" cy=\"177\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"450\" cy=\"100\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"487\" cy=\"153\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"524\" cy=\"206\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"561\" cy=\"129\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"598\" cy=\"182\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"635\" cy=\"105\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"432\" cy=\"158\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"469\" cy=\"81\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"506\" cy=\"134\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"543\" cy=\"187\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"580\" cy=\"110\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"617\" cy=\"163\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"654\" cy=\"86\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"451\" cy=\"139\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"488\" cy=\"192\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"525\" cy=\"115\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"562\" cy=\"168\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"599\" cy=\"91\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"636\" cy=\"144\" r=\"7\" fill=\"#2463B8\"/><circle cx=\"433\" cy=\"197\" r=\"7\" fill=\"#2463B8\"/><text x=\"190\" y=\"250\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">1 dozen = 12</text><text x=\"550\" y=\"250\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">1 mole = 6 × 10²³</text><text x=\"190\" y=\"290\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#4F5F64\">eggs</text><text x=\"550\" y=\"290\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#4F5F64\">particles</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">Substance</th><th style=\"width:60%;text-align:left\">1 mole weighs</th></tr>\n<tr><td>CH₄</td><td><b>16 g</b></td></tr>\n<tr><td>H₂O</td><td><b>18 g</b></td></tr>\n<tr><td>O₂</td><td><b>32 g</b></td></tr>\n<tr><td>CO₂</td><td><b>44 g</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\"><b>mass (g) = moles × molecular mass</b>. Atomic masses: C = 12, H = 1, O = 16.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 10</p>\n\n</section>", "note": "Show how each row is built: H₂O = 2 × 1 + 16 = 18. A mole is just a counting number, like a dozen, but enormous."}, {"id": "example2", "html": "<section id=\"example2\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.1\">How many grams of O₂ are needed to burn 16 g of CH₄?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Moles of CH₄</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">16 ÷ 16<br>= 1 mol</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Read the ratio</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">CH₄ : O₂<br>= 1 : 2</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Moles of O₂</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">1 × 2<br>= 2 mol</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">Grams of O₂</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">2 × 32<br>= 64 g</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Answer: <span style=\"color:#2463B8\">64 g</span> of O₂</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 11</p>\n\n</section>", "note": "Use the balanced equation from earlier. The coefficients give the ratio of moles, never the ratio of grams."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A candle gets lighter as it burns. Is mass lost?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">The wax reacts with oxygen and turns into <b>CO₂ and water vapor</b>. Both are gases, so they float away and the scale can’t see them.</p>\n<p style=\"font-size:34px;line-height:1.5\">Burn a candle inside a <b>sealed jar</b> on a scale and the reading stays the same. The atoms are all still there.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Chemical Reactions &amp; Conservation of Mass · 12</p>\n\n</section>", "note": "The opposite surprise: steel wool gets heavier when it burns, because it gains oxygen from the air. Both cases follow the same rule."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">Steel wool burns and gets heavier. Does this break conservation of mass?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">Balance this equation: H₂ + O₂ → H₂O</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">How many grams is 2 moles of H₂O?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Chemical Reactions &amp; Conservation of Mass · 13</p>\n\n</section>", "note": "Let students answer on their own first. For Q2, remind them to change coefficients only."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">No</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">It gains oxygen atoms from the air.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">2H₂ + O₂ → 2H₂O</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">H 4 = 4, O 2 = 2.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">36 g</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">2 × 18 = 36</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Atoms rearrange; they never vanish.<br><span style=\"color:#E58A55\">Balance with coefficients, count with moles.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Chemical Reactions &amp; Conservation of Mass · 14</p>\n\n</section>", "note": "Optional exit ticket: “In one sentence, explain why the sealed bottle’s mass did not change.” Ask students to use the words atoms and conservation of mass."}]}, "chem-acids-zh": {"title": "酸、鹼、鹽", "lang": "zh", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">化學</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">酸、鹼、鹽</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">檸檬為什麼酸？肥皂為什麼滑？<br>答案在兩種很小的粒子。</p>\n</div>\n<svg aria-label=\"三個燒杯：橘色酸性、灰色中性、藍色鹼性，下方是一條 pH 色帶\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<defs><linearGradient id=\"phbar\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#B4521F\"/><stop offset=\".35\" stop-color=\"#E58A55\"/><stop offset=\".5\" stop-color=\"#9AAAA6\"/><stop offset=\".65\" stop-color=\"#7FB0F2\"/><stop offset=\"1\" stop-color=\"#2463B8\"/></linearGradient></defs>\n<path d=\"M38 220 H202 V354 Q202 382 174 382 H66 Q38 382 38 354 Z\" fill=\"#E58A55\"/>\n<path d=\"M30 90 V354 Q30 390 66 390 H174 Q210 390 210 354 V90\" fill=\"none\" stroke=\"#F3F5F2\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<path d=\"M278 220 H442 V354 Q442 382 414 382 H306 Q278 382 278 354 Z\" fill=\"#9AAAA6\"/>\n<path d=\"M270 90 V354 Q270 390 306 390 H414 Q450 390 450 354 V90\" fill=\"none\" stroke=\"#F3F5F2\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<path d=\"M518 220 H682 V354 Q682 382 654 382 H546 Q518 382 518 354 Z\" fill=\"#7FB0F2\"/>\n<path d=\"M510 90 V354 Q510 390 546 390 H654 Q690 390 690 354 V90\" fill=\"none\" stroke=\"#F3F5F2\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<circle cx=\"90\" cy=\"300\" r=\"10\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"140\" cy=\"270\" r=\"7\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"110\" cy=\"340\" r=\"6\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"580\" cy=\"290\" r=\"9\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"630\" cy=\"330\" r=\"7\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"600\" cy=\"260\" r=\"6\" fill=\"#F3F5F2\" opacity=\"0.55\"/>\n<rect x=\"30\" y=\"430\" width=\"660\" height=\"26\" rx=\"13\" fill=\"url(#phbar)\"/>\n</svg>\n\n</section>", "note": "這一課給完全沒學過酸鹼的同學。我們從大家熟悉的味道和顏色出發，用 H⁺ 和 OH⁻ 兩種粒子來解釋，最後看看酸遇到鹼會發生什麼事。"}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">紫甘藍汁為什麼會變色？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 2.7s6.5 7 6.5 11.8a6.5 6.5 0 0 1-13 0C5.5 9.7 12 2.7 12 2.7z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">加入白醋</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">紫色的汁變成<b style=\"color:#18262B\">鮮豔的粉紅色</b>。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M9 3h6M10 3v6L4.6 18.6A1.6 1.6 0 0 0 6 21h12a1.6 1.6 0 0 0 1.4-2.4L14 9V3M7.5 15h9\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">加入肥皂水</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">同樣的紫色汁變成<b style=\"color:#18262B\">綠色</b>。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">同一杯汁，變成相反的顏色。因為白醋和肥皂屬於兩個相反的家族：<b style=\"color:#B4521F\">酸和鹼</b>。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 2</p>\n\n</section>", "note": "可以的話現場示範：把紫甘藍切碎煮水，濾出湯汁倒進透明杯。一杯加白醋，一杯加肥皂水或小蘇打水，倒之前先讓學生猜。延伸活動：再測汽水、檸檬汁和玻璃清潔劑，把杯子從粉紅排到綠色。"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">分辨酸和鹼</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">用 H⁺ 和 OH⁻ 來解釋。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">看懂 pH 值</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">知道每差 1 就差 10 倍。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M9 3h6M10 3v6L4.6 18.6A1.6 1.6 0 0 0 6 21h12a1.6 1.6 0 0 0 1.4-2.4L14 9V3M7.5 15h9\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">預測中和反應</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">寫出酸 + 鹼 → 鹽 + 水。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 3</p>\n\n</section>", "note": "三個目標對應簡報的三段：什麼是酸和鹼、pH 值、中和反應。最後有一個迷思和三題小測驗。"}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">開始之前</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先認識四個詞</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">酸</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">嚐起來酸。檸檬汁、白醋、汽水都是酸性。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">鹼</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">摸起來滑。肥皂、小蘇打、漂白水都是鹼性。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">pH</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">從 <b style=\"color:#18262B\">0 到 14</b> 的數字，表示東西有多酸或多鹼。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">指示劑</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">顏色會隨 pH 改變的染料，例如紫甘藍汁。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 4</p>\n\n</section>", "note": "橘色卡片是酸那一邊，藍色卡片是鹼那一邊，整份簡報都用這個顏色規則。安全提醒：實驗室裡不明的化學藥品絕對不能嚐或摸，這裡說的味道都來自日常食物。"}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"什麼是酸和鹼\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">酸和鹼的真面目</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">酸放出 H⁺，鹼放出 OH⁻</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"兩杯水：左邊滿是酸放出的橘色 H⁺，右邊滿是鹼放出的藍色 OH⁻\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<path d=\"M48 160 H292 V334 Q292 362 264 362 H76 Q48 362 48 334 Z\" fill=\"#E1ECFA\"/>\n<path d=\"M40 120 V334 Q40 370 76 370 H264 Q300 370 300 334 V120\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n<path d=\"M368 160 H612 V334 Q612 362 584 362 H396 Q368 362 368 334 Z\" fill=\"#E1ECFA\"/>\n<path d=\"M360 120 V334 Q360 370 396 370 H584 Q620 370 620 334 V120\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n<rect x=\"71.0\" y=\"176\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"110\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text><rect x=\"171.0\" y=\"206\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"210\" y=\"240\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text><rect x=\"91.0\" y=\"266\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"130\" y=\"300\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text><rect x=\"191.0\" y=\"286\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"230\" y=\"320\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text><rect x=\"131.0\" y=\"316\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"170\" y=\"350\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text>\n<rect x=\"392.0\" y=\"176\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"440\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text><rect x=\"502.0\" y=\"216\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"550\" y=\"250\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text><rect x=\"412.0\" y=\"266\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"460\" y=\"300\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text><rect x=\"512.0\" y=\"296\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"560\" y=\"330\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text><rect x=\"452.0\" y=\"326\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"500\" y=\"360\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text>\n<text x=\"170\" y=\"80\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#B4521F\">H⁺</text>\n<text x=\"490\" y=\"80\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#2463B8\">OH⁻</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">左：酸溶在水中。右：鹼溶在水中。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">酸溶在水裡，會放出 <b style=\"color:#B4521F\">H⁺</b>（氫離子）。</p>\n<p style=\"font-size:34px;line-height:1.5\">鹼溶在水裡，會放出 <b style=\"color:#2463B8\">OH⁻</b>（氫氧根離子）。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">H⁺ 越多越酸，OH⁻ 越多越鹼。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 5</p>\n\n</section>", "note": "「+」和「−」代表這些粒子帶電，叫做離子。學生現在還不需要完整的離子理論，只要記住：酸放出 H⁺，鹼放出 OH⁻。"}, {"id": "figure", "html": "<section id=\"figure\" data-section=\"pH 值\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">pH 值</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">0 到 14：酸性、中性、鹼性</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"pH 色帶從 0 到 14，酸性那端是橘色，7 是灰色，鹼性那端是藍色，上面標出生活中的東西\" width=\"1600\" height=\"210\" viewBox=\"0 0 1600 210\">\n<defs><linearGradient id=\"phscale\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#B4521F\"/><stop offset=\".35\" stop-color=\"#E58A55\"/><stop offset=\".5\" stop-color=\"#D3DCD8\"/><stop offset=\".65\" stop-color=\"#7FB0F2\"/><stop offset=\"1\" stop-color=\"#2463B8\"/></linearGradient></defs>\n<rect x=\"40\" y=\"100\" width=\"1520\" height=\"50\" rx=\"25\" fill=\"url(#phscale)\"/>\n<line x1=\"257.1428571428571\" y1=\"38\" x2=\"257.1428571428571\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"257.1428571428571\" y=\"30\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">檸檬汁</text><line x1=\"365.7142857142857\" y1=\"70\" x2=\"365.7142857142857\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"365.7142857142857\" y=\"62\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">白醋</text><line x1=\"800.0\" y1=\"38\" x2=\"800.0\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"800.0\" y=\"30\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">純水</text><line x1=\"1017.1428571428571\" y1=\"70\" x2=\"1017.1428571428571\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"1017.1428571428571\" y=\"62\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">小蘇打水</text><line x1=\"1125.7142857142858\" y1=\"38\" x2=\"1125.7142857142858\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"1125.7142857142858\" y=\"30\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">肥皂水</text><line x1=\"1451.4285714285713\" y1=\"70\" x2=\"1451.4285714285713\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"1451.4285714285713\" y=\"62\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">漂白水</text>\n<text x=\"40.0\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">0</text><text x=\"148.57142857142856\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">1</text><text x=\"257.1428571428571\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">2</text><text x=\"365.7142857142857\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">3</text><text x=\"474.2857142857143\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">4</text><text x=\"582.8571428571429\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">5</text><text x=\"691.4285714285714\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">6</text><text x=\"800.0\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">7</text><text x=\"908.5714285714286\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">8</text><text x=\"1017.1428571428571\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">9</text><text x=\"1125.7142857142858\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">10</text><text x=\"1234.2857142857142\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">11</text><text x=\"1342.857142857143\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">12</text><text x=\"1451.4285714285713\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">13</text><text x=\"1560.0\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">14</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">小於 7 是酸性，等於 7 是中性，大於 7 是鹼性。離 7 越遠，越強。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b style=\"color:#B4521F\">小於 7</b>：酸性。檸檬汁大約是 2。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>等於 7</b>：中性。純水。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b style=\"color:#2463B8\">大於 7</b>：鹼性。漂白水大約是 13。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 6</p>\n\n</section>", "note": "數值是大約值，實際產品會有差異。可以點出汽水是酸性的，雖然喝起來甜，那是糖蓋過了酸味。"}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">算算看</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">pH 每差 1，就差 10 倍</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"五根柱子從 pH 7 到 pH 3 一階一階變高，每一階標示乘以 10\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<line x1=\"40\" y1=\"340\" x2=\"700\" y2=\"340\" stroke=\"#4F5F64\" stroke-width=\"4\"/>\n<rect x=\"60\" y=\"280\" width=\"96\" height=\"60\" rx=\"10\" fill=\"#D3DCD8\"/><text x=\"108\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">7</text><rect x=\"190\" y=\"220\" width=\"96\" height=\"120\" rx=\"10\" fill=\"#F7E6DC\"/><text x=\"238\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">6</text><text x=\"173\" y=\"200\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">×10</text><rect x=\"320\" y=\"160\" width=\"96\" height=\"180\" rx=\"10\" fill=\"#E58A55\"/><text x=\"368\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">5</text><text x=\"303\" y=\"140\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">×10</text><rect x=\"450\" y=\"100\" width=\"96\" height=\"240\" rx=\"10\" fill=\"#C8693A\"/><text x=\"498\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">4</text><text x=\"433\" y=\"80\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">×10</text><rect x=\"580\" y=\"40\" width=\"96\" height=\"300\" rx=\"10\" fill=\"#B4521F\"/><text x=\"628\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">3</text><text x=\"563\" y=\"20\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">×10</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">pH 值</th><th style=\"width:60%;text-align:left\">和純水比的 H⁺</th></tr>\n<tr><td>7</td><td><b>1 倍</b></td></tr>\n<tr><td>6</td><td><b>10 倍</b></td></tr>\n<tr><td>5</td><td><b>100 倍</b></td></tr>\n<tr><td>4</td><td><b>1,000 倍</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td>3</td><td><b>10,000 倍</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">pH 往下 1，H⁺ 就乘以 10。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 7</p>\n\n</section>", "note": "先遮住右欄讓學生自己填。柱子是用對數比例畫的；如果照真實比例畫，pH 3 的柱子會是 pH 7 的 10,000 倍高。"}, {"id": "formula", "html": "<section id=\"formula\" data-section=\"中和反應\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">中和反應</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">H⁺</p>\n<p style=\"font-size:32px;color:#BFCDC9\">來自酸</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">+</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#7FB0F2\">OH⁻</p>\n<p style=\"font-size:32px;color:#BFCDC9\">來自鹼</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">→</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#F3F5F2\">H₂O</p>\n<p style=\"font-size:32px;color:#BFCDC9\">水</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:700;line-height:1.4\">酸 + 鹼 → 鹽 + 水</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">例：HCl + NaOH → NaCl + H₂O（鹽酸 + 氫氧化鈉 → 食鹽 + 水）</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">酸、鹼、鹽 · 8</p>\n\n</section>", "note": "酸的 H⁺ 和鹼的 OH⁻ 結合成水，兩者就互相抵消了，剩下的部分組成鹽。這就是胃藥（鹼性）能中和胃酸的原因。"}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">電解質</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">酸、鹼、鹽的水溶液會導電</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"電池接上兩根插在鹽水裡的金屬棒，水中的帶電粒子在移動，燈泡亮了\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<path d=\"M220 140 V50 H292 M308 50 H370 M426 50 H470 V140\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/>\n<line x1=\"292\" y1=\"24\" x2=\"292\" y2=\"76\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"308\" y1=\"34\" x2=\"308\" y2=\"66\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<circle cx=\"398\" cy=\"50\" r=\"28\" fill=\"#FFC94D\" stroke=\"#18262B\" stroke-width=\"5\"/>\n<g stroke=\"#E0A21A\" stroke-width=\"6\" stroke-linecap=\"round\"><line x1=\"398\" y1=\"14\" x2=\"398\" y2=\"2\"/><line x1=\"432\" y1=\"24\" x2=\"444\" y2=\"14\"/><line x1=\"364\" y1=\"24\" x2=\"352\" y2=\"14\"/></g>\n<path d=\"M168 210 H512 V324 Q512 352 484 352 H196 Q168 352 168 324 Z\" fill=\"#E1ECFA\"/>\n<path d=\"M160 160 V324 Q160 360 196 360 H484 Q520 360 520 324 V160\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n<rect x=\"212\" y=\"120\" width=\"16\" height=\"200\" rx=\"6\" fill=\"#4F5F64\"/>\n<rect x=\"462\" y=\"120\" width=\"16\" height=\"200\" rx=\"6\" fill=\"#4F5F64\"/>\n<circle cx=\"260\" cy=\"240\" r=\"18\" fill=\"#B4521F\"/><text x=\"260\" y=\"249\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">+</text><circle cx=\"330\" cy=\"300\" r=\"18\" fill=\"#2463B8\"/><text x=\"330\" y=\"309\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">−</text><circle cx=\"380\" cy=\"225\" r=\"18\" fill=\"#B4521F\"/><text x=\"380\" y=\"234\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">+</text><circle cx=\"300\" cy=\"330\" r=\"18\" fill=\"#2463B8\"/><text x=\"300\" y=\"339\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">−</text><circle cx=\"420\" cy=\"280\" r=\"18\" fill=\"#B4521F\"/><text x=\"420\" y=\"289\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">+</text><circle cx=\"360\" cy=\"260\" r=\"18\" fill=\"#2463B8\"/><text x=\"360\" y=\"269\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">−</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">鹽水：燈泡亮了。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">酸、鹼、鹽在水中會分成<b>帶電的粒子</b>（離子）。</p>\n<p style=\"font-size:34px;line-height:1.5\">帶電粒子移動就能傳電，所以燈泡會亮。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">糖會溶解，但不會分成離子，所以糖水不導電。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 9</p>\n\n</section>", "note": "在水中會導電的物質叫做電解質。可選示範：用 9 V 電池和 LED 做簡單的導電測試器，分別測自來水、鹽水、白醋和糖水。"}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一張表看懂</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">酸和鹼，差在哪裡？</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">比較</th><th style=\"width:33%;text-align:left\">酸</th><th style=\"width:33%;text-align:left\">鹼</th></tr>\n<tr><td>在水中放出</td><td><span style=\"color:#B4521F\">H⁺</span></td><td><span style=\"color:#2463B8\">OH⁻</span></td></tr>\n<tr><td>pH 值</td><td>小於 7</td><td>大於 7</td></tr>\n<tr><td>味道或觸感</td><td>酸</td><td>苦、滑</td></tr>\n<tr><td>紫甘藍汁</td><td>粉紅到紅</td><td>藍到綠</td></tr>\n<tr><td>生活例子</td><td>檸檬、白醋、汽水</td><td>肥皂、小蘇打、漂白水</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">一句話記住：</b> 酸放出 H⁺，pH 小於 7；鹼放出 OH⁻，pH 大於 7。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 10</p>\n\n</section>", "note": "先遮住最後一列，請學生用這張表把五樣家裡的東西分成酸或鹼。"}, {"id": "figure2", "html": "<section id=\"figure2\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">看顏色判斷</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">指示劑用顏色告訴你 pH</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"六杯紫甘藍汁從 pH 2 到 pH 12：紅、粉紅、紫、藍、綠、黃\" width=\"1500\" height=\"240\" viewBox=\"0 0 1500 240\">\n<path d=\"M78 70 L94 180 H196 L212 70 Z\" fill=\"#C62828\"/><path d=\"M60 20 L90 184 H200 L230 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"145\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 2</text><path d=\"M323 70 L339 180 H441 L457 70 Z\" fill=\"#E0457B\"/><path d=\"M305 20 L335 184 H445 L475 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"390\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 4</text><path d=\"M568 70 L584 180 H686 L702 70 Z\" fill=\"#8E44AD\"/><path d=\"M550 20 L580 184 H690 L720 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"635\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 6</text><path d=\"M813 70 L829 180 H931 L947 70 Z\" fill=\"#3F51B5\"/><path d=\"M795 20 L825 184 H935 L965 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"880\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 8</text><path d=\"M1058 70 L1074 180 H1176 L1192 70 Z\" fill=\"#2E9E5B\"/><path d=\"M1040 20 L1070 184 H1180 L1210 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"1125\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 10</text><path d=\"M1303 70 L1319 180 H1421 L1437 70 Z\" fill=\"#E0B020\"/><path d=\"M1285 20 L1315 184 H1425 L1455 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"1370\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 12</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">紫甘藍汁在不同 pH 下的顏色。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>紫甘藍汁</b>：一整道彩虹，從紅色（酸）到綠色、黃色（鹼）。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>石蕊試紙</b>：遇酸變紅，遇鹼變藍。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>酚酞</b>：在酸中無色，在鹼中變粉紅。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 11</p>\n\n</section>", "note": "酚酞會出現在小測驗。學生常把石蕊和酚酞搞混：石蕊有兩種顏色，酚酞不是無色就是粉紅。"}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">例題</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">pH 2 的溶液，H⁺ 是 pH 5 溶液的幾倍？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">算出差距</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">5 − 2 = 3</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">每差 1 乘 10</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">差 3 步</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">連乘</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">10 × 10 × 10</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">答案</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">= 1,000</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">pH 2 的 H⁺ 是 <span style=\"color:#2463B8\">1,000 倍</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 12</p>\n\n</section>", "note": "最常見的錯誤答案是 3 倍：學生相減後就停了。提醒他們每差 1 都要乘以 10。"}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">「鹽」就是食鹽嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">不是。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">在化學裡，<b>鹽</b>是酸和鹼中和後產生的化合物的總稱。食鹽（NaCl）只是其中一種。</p>\n<p style=\"font-size:34px;line-height:1.5\">小蘇打、粉筆（碳酸鈣）和許多肥料也都是<b>鹽</b>，而且大部分吃起來一點也不鹹。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">酸、鹼、鹽 · 13</p>\n\n</section>", "note": "回扣中和反應：換一種酸或鹼，就會產生不同的鹽。HCl + KOH 會產生 KCl，就是低鈉鹽的成分。"}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:34px;line-height:1.5\">是非題：pH 3 只比 pH 4 酸一點點。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:34px;line-height:1.5\">寫出生成物：HCl + NaOH → ？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:34px;line-height:1.5\">在肥皂水裡加入酚酞，會看到什麼顏色？為什麼？</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">酸、鹼、鹽 · 14</p>\n\n</section>", "note": "先讓學生自己作答。第 1 題提醒他們每差 1 就差 10 倍。"}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:700\">錯</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">pH 3 的 H⁺ 是 pH 4 的 10 倍。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:700\">NaCl + H₂O</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">酸 + 鹼 → 鹽 + 水。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:700\">粉紅色</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">肥皂水是鹼性，酚酞遇鹼變粉紅。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">酸放出 H⁺，鹼放出 OH⁻。<br><span style=\"color:#E58A55\">pH 每差 1 就差 10 倍；酸鹼相遇變成鹽和水。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">酸、鹼、鹽 · 15</p>\n\n</section>", "note": "可選出場單：「pH 2 的 H⁺ 是 pH 4 的幾倍？」（答案：100 倍。）"}]}, "chem-acids-en": {"title": "Acids, Bases & Salts", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">CHEMISTRY</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Acids, Bases &amp;<br>Salts</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">Why is lemon juice sour and soap slippery?<br>It comes down to two tiny particles.</p>\n</div>\n<svg aria-label=\"Three beakers: an orange acid, a gray neutral and a blue base, above a pH color bar\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<defs><linearGradient id=\"phbar\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#B4521F\"/><stop offset=\".35\" stop-color=\"#E58A55\"/><stop offset=\".5\" stop-color=\"#9AAAA6\"/><stop offset=\".65\" stop-color=\"#7FB0F2\"/><stop offset=\"1\" stop-color=\"#2463B8\"/></linearGradient></defs>\n<path d=\"M38 220 H202 V354 Q202 382 174 382 H66 Q38 382 38 354 Z\" fill=\"#E58A55\"/>\n<path d=\"M30 90 V354 Q30 390 66 390 H174 Q210 390 210 354 V90\" fill=\"none\" stroke=\"#F3F5F2\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<path d=\"M278 220 H442 V354 Q442 382 414 382 H306 Q278 382 278 354 Z\" fill=\"#9AAAA6\"/>\n<path d=\"M270 90 V354 Q270 390 306 390 H414 Q450 390 450 354 V90\" fill=\"none\" stroke=\"#F3F5F2\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<path d=\"M518 220 H682 V354 Q682 382 654 382 H546 Q518 382 518 354 Z\" fill=\"#7FB0F2\"/>\n<path d=\"M510 90 V354 Q510 390 546 390 H654 Q690 390 690 354 V90\" fill=\"none\" stroke=\"#F3F5F2\" stroke-width=\"8\" stroke-linecap=\"round\"/>\n<circle cx=\"90\" cy=\"300\" r=\"10\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"140\" cy=\"270\" r=\"7\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"110\" cy=\"340\" r=\"6\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"580\" cy=\"290\" r=\"9\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"630\" cy=\"330\" r=\"7\" fill=\"#F3F5F2\" opacity=\"0.55\"/><circle cx=\"600\" cy=\"260\" r=\"6\" fill=\"#F3F5F2\" opacity=\"0.55\"/>\n<rect x=\"30\" y=\"430\" width=\"660\" height=\"26\" rx=\"13\" fill=\"url(#phbar)\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied acids and bases. We start from tastes and colors everyone knows, then explain them with two particles, H⁺ and OH⁻, and finish with what happens when an acid meets a base."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why does purple cabbage juice change color?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 2.7s6.5 7 6.5 11.8a6.5 6.5 0 0 1-13 0C5.5 9.7 12 2.7 12 2.7z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Add vinegar</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">The purple juice turns <b style=\"color:#18262B\">bright pink</b>.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M9 3h6M10 3v6L4.6 18.6A1.6 1.6 0 0 0 6 21h12a1.6 1.6 0 0 0 1.4-2.4L14 9V3M7.5 15h9\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Add soapy water</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">The same purple juice turns <b style=\"color:#18262B\">green</b>.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Same juice, opposite colors. Vinegar and soap belong to two opposite families: <b style=\"color:#B4521F\">acids and bases</b>.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 2</p>\n\n</section>", "note": "If you can, do it live: boil chopped purple cabbage, strain the juice, and pour it into clear cups. Add vinegar to one and soapy water or baking soda water to another. Ask students to guess before you pour. Optional extension: test soda, lemon juice and window cleaner too, and line the cups up from pink to green."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Tell acids from bases</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Explain them with H⁺ and OH⁻.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Read the pH scale</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Know that each step is 10 times stronger.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M9 3h6M10 3v6L4.6 18.6A1.6 1.6 0 0 0 6 21h12a1.6 1.6 0 0 0 1.4-2.4L14 9V3M7.5 15h9\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Predict neutralization</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Write acid + base → salt + water.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 3</p>\n\n</section>", "note": "The three goals match the three parts of the deck: what acids and bases are, the pH scale, and neutralization. We finish with a myth and a three-question quiz."}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BEFORE YOU START</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Four words you need first</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Acid</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Tastes sour. Lemon juice, vinegar and soda are acidic.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Base</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Feels slippery. Soap, baking soda and bleach are basic.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">pH</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">A number from <b style=\"color:#18262B\">0 to 14</b> that says how acidic or basic something is.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Indicator</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">A dye that changes color with pH, like purple cabbage juice.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 4</p>\n\n</section>", "note": "Orange cards are the acid side; blue cards are the base side. We keep this color code for the rest of the deck. Safety: never taste or touch unknown chemicals in the lab; the tastes here are only from everyday foods."}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"What acids and bases are\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WHAT MAKES AN ACID OR A BASE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Acids give off H⁺. Bases give off OH⁻.</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Two beakers of water: the left one is full of orange H⁺ particles from an acid, the right one is full of blue OH⁻ particles from a base\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<path d=\"M48 160 H292 V334 Q292 362 264 362 H76 Q48 362 48 334 Z\" fill=\"#E1ECFA\"/>\n<path d=\"M40 120 V334 Q40 370 76 370 H264 Q300 370 300 334 V120\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n<path d=\"M368 160 H612 V334 Q612 362 584 362 H396 Q368 362 368 334 Z\" fill=\"#E1ECFA\"/>\n<path d=\"M360 120 V334 Q360 370 396 370 H584 Q620 370 620 334 V120\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n<rect x=\"71.0\" y=\"176\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"110\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text><rect x=\"171.0\" y=\"206\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"210\" y=\"240\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text><rect x=\"91.0\" y=\"266\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"130\" y=\"300\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text><rect x=\"191.0\" y=\"286\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"230\" y=\"320\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text><rect x=\"131.0\" y=\"316\" width=\"78\" height=\"48\" rx=\"24\" fill=\"#B4521F\"/><text x=\"170\" y=\"350\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">H⁺</text>\n<rect x=\"392.0\" y=\"176\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"440\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text><rect x=\"502.0\" y=\"216\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"550\" y=\"250\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text><rect x=\"412.0\" y=\"266\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"460\" y=\"300\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text><rect x=\"512.0\" y=\"296\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"560\" y=\"330\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text><rect x=\"452.0\" y=\"326\" width=\"96\" height=\"48\" rx=\"24\" fill=\"#2463B8\"/><text x=\"500\" y=\"360\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#FFFFFF\">OH⁻</text>\n<text x=\"170\" y=\"80\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#B4521F\">H⁺</text>\n<text x=\"490\" y=\"80\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#2463B8\">OH⁻</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Left: acid in water. Right: base in water.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">When an acid dissolves in water, it releases <b style=\"color:#B4521F\">H⁺</b> (hydrogen ions).</p>\n<p style=\"font-size:34px;line-height:1.5\">When a base dissolves in water, it releases <b style=\"color:#2463B8\">OH⁻</b> (hydroxide ions).</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">More H⁺ → more acidic. More OH⁻ → more basic.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 5</p>\n\n</section>", "note": "The “+” and “−” mean these particles carry an electric charge; they are called ions. Students do not need the full ion theory yet, only the rule: acids give H⁺, bases give OH⁻."}, {"id": "figure", "html": "<section id=\"figure\" data-section=\"The pH scale\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">THE pH SCALE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">From 0 to 14: acidic, neutral, basic</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"A pH bar from 0 to 14, orange on the acid side, gray at 7 and blue on the base side, with everyday items marked\" width=\"1600\" height=\"210\" viewBox=\"0 0 1600 210\">\n<defs><linearGradient id=\"phscale\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#B4521F\"/><stop offset=\".35\" stop-color=\"#E58A55\"/><stop offset=\".5\" stop-color=\"#D3DCD8\"/><stop offset=\".65\" stop-color=\"#7FB0F2\"/><stop offset=\"1\" stop-color=\"#2463B8\"/></linearGradient></defs>\n<rect x=\"40\" y=\"100\" width=\"1520\" height=\"50\" rx=\"25\" fill=\"url(#phscale)\"/>\n<line x1=\"257.1428571428571\" y1=\"38\" x2=\"257.1428571428571\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"257.1428571428571\" y=\"30\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">Lemon juice</text><line x1=\"365.7142857142857\" y1=\"70\" x2=\"365.7142857142857\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"365.7142857142857\" y=\"62\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">Vinegar</text><line x1=\"800.0\" y1=\"38\" x2=\"800.0\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"800.0\" y=\"30\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">Pure water</text><line x1=\"1017.1428571428571\" y1=\"70\" x2=\"1017.1428571428571\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"1017.1428571428571\" y=\"62\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">Baking soda</text><line x1=\"1125.7142857142858\" y1=\"38\" x2=\"1125.7142857142858\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"1125.7142857142858\" y=\"30\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">Soapy water</text><line x1=\"1451.4285714285713\" y1=\"70\" x2=\"1451.4285714285713\" y2=\"96\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"1451.4285714285713\" y=\"62\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">Bleach</text>\n<text x=\"40.0\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">0</text><text x=\"148.57142857142856\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">1</text><text x=\"257.1428571428571\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">2</text><text x=\"365.7142857142857\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">3</text><text x=\"474.2857142857143\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">4</text><text x=\"582.8571428571429\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">5</text><text x=\"691.4285714285714\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">6</text><text x=\"800.0\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">7</text><text x=\"908.5714285714286\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">8</text><text x=\"1017.1428571428571\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">9</text><text x=\"1125.7142857142858\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">10</text><text x=\"1234.2857142857142\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">11</text><text x=\"1342.857142857143\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">12</text><text x=\"1451.4285714285713\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">13</text><text x=\"1560.0\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"700\" fill=\"#4F5F64\">14</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Below 7 is acidic, 7 is neutral, above 7 is basic. The further from 7, the stronger.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b style=\"color:#B4521F\">Below 7</b>: acidic. Lemon juice is about 2.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Exactly 7</b>: neutral. Pure water.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b style=\"color:#2463B8\">Above 7</b>: basic. Bleach is about 13.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 6</p>\n\n</section>", "note": "Values are typical; real products vary. Point out that soda is acidic even though it tastes sweet: the sugar hides the sourness."}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">TRY THE NUMBERS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Each step on the pH scale is 10 times</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"Five bars that get taller step by step from pH 7 to pH 3; each step is labeled times ten\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<line x1=\"40\" y1=\"340\" x2=\"700\" y2=\"340\" stroke=\"#4F5F64\" stroke-width=\"4\"/>\n<rect x=\"60\" y=\"280\" width=\"96\" height=\"60\" rx=\"10\" fill=\"#D3DCD8\"/><text x=\"108\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">7</text><rect x=\"190\" y=\"220\" width=\"96\" height=\"120\" rx=\"10\" fill=\"#F7E6DC\"/><text x=\"238\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">6</text><text x=\"173\" y=\"200\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">×10</text><rect x=\"320\" y=\"160\" width=\"96\" height=\"180\" rx=\"10\" fill=\"#E58A55\"/><text x=\"368\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">5</text><text x=\"303\" y=\"140\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">×10</text><rect x=\"450\" y=\"100\" width=\"96\" height=\"240\" rx=\"10\" fill=\"#C8693A\"/><text x=\"498\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">4</text><text x=\"433\" y=\"80\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">×10</text><rect x=\"580\" y=\"40\" width=\"96\" height=\"300\" rx=\"10\" fill=\"#B4521F\"/><text x=\"628\" y=\"384\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">3</text><text x=\"563\" y=\"20\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">×10</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">pH</th><th style=\"width:60%;text-align:left\">H⁺ compared with water</th></tr>\n<tr><td>7</td><td><b>1 ×</b></td></tr>\n<tr><td>6</td><td><b>10 ×</b></td></tr>\n<tr><td>5</td><td><b>100 ×</b></td></tr>\n<tr><td>4</td><td><b>1,000 ×</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td>3</td><td><b>10,000 ×</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Going down 1 on the pH scale multiplies the H⁺ by 10.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 7</p>\n\n</section>", "note": "Cover the right column and let students fill it in. The bars are drawn on a log scale; if they were drawn to real size, the pH 3 bar would be 10,000 times taller than the pH 7 bar."}, {"id": "formula", "html": "<section id=\"formula\" data-section=\"Neutralization\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">NEUTRALIZATION</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">H⁺</p>\n<p style=\"font-size:32px;color:#BFCDC9\">from the acid</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">+</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#7FB0F2\">OH⁻</p>\n<p style=\"font-size:32px;color:#BFCDC9\">from the base</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">→</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#F3F5F2\">H₂O</p>\n<p style=\"font-size:32px;color:#BFCDC9\">water</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:800;line-height:1.4\">acid + base → salt + water</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Example: HCl + NaOH → NaCl + H₂O (hydrochloric acid + sodium hydroxide → table salt + water)</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Acids, Bases &amp; Salts · 8</p>\n\n</section>", "note": "The H⁺ from the acid and the OH⁻ from the base join to make water, so the two cancel each other out. The leftover pieces form a salt. This is why antacid tablets (a base) settle an acidic stomach."}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ELECTROLYTES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Acids, bases and salts conduct electricity</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A battery wired to two metal rods in a beaker of salt water; charged particles move in the water and the bulb lights up\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<path d=\"M220 140 V50 H292 M308 50 H370 M426 50 H470 V140\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/>\n<line x1=\"292\" y1=\"24\" x2=\"292\" y2=\"76\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<line x1=\"308\" y1=\"34\" x2=\"308\" y2=\"66\" stroke=\"#18262B\" stroke-width=\"8\"/>\n<circle cx=\"398\" cy=\"50\" r=\"28\" fill=\"#FFC94D\" stroke=\"#18262B\" stroke-width=\"5\"/>\n<g stroke=\"#E0A21A\" stroke-width=\"6\" stroke-linecap=\"round\"><line x1=\"398\" y1=\"14\" x2=\"398\" y2=\"2\"/><line x1=\"432\" y1=\"24\" x2=\"444\" y2=\"14\"/><line x1=\"364\" y1=\"24\" x2=\"352\" y2=\"14\"/></g>\n<path d=\"M168 210 H512 V324 Q512 352 484 352 H196 Q168 352 168 324 Z\" fill=\"#E1ECFA\"/>\n<path d=\"M160 160 V324 Q160 360 196 360 H484 Q520 360 520 324 V160\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n<rect x=\"212\" y=\"120\" width=\"16\" height=\"200\" rx=\"6\" fill=\"#4F5F64\"/>\n<rect x=\"462\" y=\"120\" width=\"16\" height=\"200\" rx=\"6\" fill=\"#4F5F64\"/>\n<circle cx=\"260\" cy=\"240\" r=\"18\" fill=\"#B4521F\"/><text x=\"260\" y=\"249\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">+</text><circle cx=\"330\" cy=\"300\" r=\"18\" fill=\"#2463B8\"/><text x=\"330\" y=\"309\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">−</text><circle cx=\"380\" cy=\"225\" r=\"18\" fill=\"#B4521F\"/><text x=\"380\" y=\"234\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">+</text><circle cx=\"300\" cy=\"330\" r=\"18\" fill=\"#2463B8\"/><text x=\"300\" y=\"339\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">−</text><circle cx=\"420\" cy=\"280\" r=\"18\" fill=\"#B4521F\"/><text x=\"420\" y=\"289\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">+</text><circle cx=\"360\" cy=\"260\" r=\"18\" fill=\"#2463B8\"/><text x=\"360\" y=\"269\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">−</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Salt water: the bulb lights up.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">In water, acids, bases and salts split into <b>charged particles</b> (ions).</p>\n<p style=\"font-size:34px;line-height:1.5\">Moving charges carry electricity, so the bulb lights up.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Sugar dissolves but does not split into ions, so sugar water does not conduct.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 9</p>\n\n</section>", "note": "Substances that conduct in water are called electrolytes. Optional demo: a simple conductivity tester with a 9 V battery and an LED, tried in tap water, salt water, vinegar and sugar water."}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ONE TABLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Acids vs. bases</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">Compare</th><th style=\"width:33%;text-align:left\">Acid</th><th style=\"width:33%;text-align:left\">Base</th></tr>\n<tr><td>Releases in water</td><td><span style=\"color:#B4521F\">H⁺</span></td><td><span style=\"color:#2463B8\">OH⁻</span></td></tr>\n<tr><td>pH</td><td>Below 7</td><td>Above 7</td></tr>\n<tr><td>Taste or feel</td><td>Sour</td><td>Bitter, slippery</td></tr>\n<tr><td>Purple cabbage juice</td><td>Pink to red</td><td>Blue to green</td></tr>\n<tr><td>Everyday examples</td><td>Lemon, vinegar, soda</td><td>Soap, baking soda, bleach</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">Remember:</b> acids give H⁺ and sit below 7; bases give OH⁻ and sit above 7.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 10</p>\n\n</section>", "note": "Ask students to sort five household items into acid or base using the table before you show the last row."}, {"id": "figure2", "html": "<section id=\"figure2\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">READ THE COLOR</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Indicators show pH as a color</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"Six cups of purple cabbage juice from pH 2 to pH 12: red, pink, purple, blue, green, yellow\" width=\"1500\" height=\"240\" viewBox=\"0 0 1500 240\">\n<path d=\"M78 70 L94 180 H196 L212 70 Z\" fill=\"#C62828\"/><path d=\"M60 20 L90 184 H200 L230 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"145\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 2</text><path d=\"M323 70 L339 180 H441 L457 70 Z\" fill=\"#E0457B\"/><path d=\"M305 20 L335 184 H445 L475 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"390\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 4</text><path d=\"M568 70 L584 180 H686 L702 70 Z\" fill=\"#8E44AD\"/><path d=\"M550 20 L580 184 H690 L720 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"635\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 6</text><path d=\"M813 70 L829 180 H931 L947 70 Z\" fill=\"#3F51B5\"/><path d=\"M795 20 L825 184 H935 L965 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"880\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 8</text><path d=\"M1058 70 L1074 180 H1176 L1192 70 Z\" fill=\"#2E9E5B\"/><path d=\"M1040 20 L1070 184 H1180 L1210 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"1125\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 10</text><path d=\"M1303 70 L1319 180 H1421 L1437 70 Z\" fill=\"#E0B020\"/><path d=\"M1285 20 L1315 184 H1425 L1455 20\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"6\" stroke-linejoin=\"round\"/><text x=\"1370\" y=\"228\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">pH 12</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Purple cabbage juice at different pH values.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Purple cabbage juice</b>: a whole rainbow, from red (acid) to green and yellow (base).</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Litmus paper</b>: turns red in acid, blue in base.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Phenolphthalein</b>: colorless in acid, pink in base.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 11</p>\n\n</section>", "note": "Phenolphthalein is used in the quiz. Students often mix up litmus and phenolphthalein: litmus has two colors, phenolphthalein is either clear or pink."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.1\">How many times more H⁺ does a pH 2 solution have than a pH 5 solution?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Find the gap</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">5 − 2 = 3</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Each step ×10</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">3 steps</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Multiply</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">10 × 10 × 10</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">Answer</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">= 1,000</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">pH 2 has <span style=\"color:#2463B8\">1,000 times</span> more H⁺</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 12</p>\n\n</section>", "note": "The most common wrong answer is 3 times: students subtract and stop. Remind them that every step multiplies by 10."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Does “salt” just mean table salt?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">In chemistry, a <b>salt</b> is any compound made when an acid and a base neutralize each other. Table salt (NaCl) is only one of them.</p>\n<p style=\"font-size:34px;line-height:1.5\">Baking soda, chalk (calcium carbonate) and many fertilizers are <b>salts</b> too, and most of them don’t taste salty at all.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Acids, Bases &amp; Salts · 13</p>\n\n</section>", "note": "Link back to neutralization: change the acid or the base and you get a different salt. HCl + KOH makes KCl, a salt substitute."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">True or false: pH 3 is only a little more acidic than pH 4.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">Write the products: HCl + NaOH → ?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">Phenolphthalein is added to soapy water. What color do you see, and why?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Acids, Bases &amp; Salts · 14</p>\n\n</section>", "note": "Let students answer on their own first. For Q1, remind them that each step is 10 times."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">False</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">pH 3 has 10 times more H⁺ than pH 4.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">NaCl + H₂O</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Acid + base → salt + water.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">Pink</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Soapy water is basic, and phenolphthalein turns pink in a base.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Acids give H⁺, bases give OH⁻.<br><span style=\"color:#E58A55\">Each pH step is 10×; together they make salt + water.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Acids, Bases &amp; Salts · 15</p>\n\n</section>", "note": "Optional exit ticket: “How many times more H⁺ does pH 2 have than pH 4?” (Answer: 100 times.)"}]}, "chem-redox-zh": {"title": "氧化與還原", "lang": "zh", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">化學</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">氧化<br>與還原</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">鐵為什麼會生鏽？鐵又是怎麼從石頭裡來的？<br>跟著氧走就知道。</p>\n</div>\n<svg aria-label=\"一根生鏽的鐵釘，旁邊的氧原子正朝它靠近\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<g transform=\"rotate(-28 360 240)\"><rect x=\"110\" y=\"215\" width=\"470\" height=\"50\" rx=\"8\" fill=\"#8C989C\"/><rect x=\"80\" y=\"190\" width=\"40\" height=\"100\" rx=\"8\" fill=\"#8C989C\"/><polygon points=\"580,215 680,240 580,265\" fill=\"#8C989C\"/><ellipse cx=\"220\" cy=\"232\" rx=\"40\" ry=\"18\" fill=\"#A0522D\"/><ellipse cx=\"330\" cy=\"250\" rx=\"54\" ry=\"16\" fill=\"#E58A55\"/><ellipse cx=\"450\" cy=\"228\" rx=\"34\" ry=\"14\" fill=\"#A0522D\"/><ellipse cx=\"520\" cy=\"252\" rx=\"30\" ry=\"12\" fill=\"#E58A55\"/></g><circle cx=\"560\" cy=\"90\" r=\"26\" fill=\"#E58A55\"/><text x=\"560\" y=\"99\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"630\" cy=\"150\" r=\"26\" fill=\"#E58A55\"/><text x=\"630\" y=\"159\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"150\" cy=\"380\" r=\"26\" fill=\"#E58A55\"/><text x=\"150\" y=\"389\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><line x1=\"540\" y1=\"110\" x2=\"482\" y2=\"160\" stroke=\"#BFCDC9\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"470,170 488,166 476,153\" fill=\"#BFCDC9\"/><line x1=\"605\" y1=\"165\" x2=\"534\" y2=\"198\" stroke=\"#BFCDC9\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"520,205 538,206 531,190\" fill=\"#BFCDC9\"/><line x1=\"175\" y1=\"360\" x2=\"226\" y2=\"328\" stroke=\"#BFCDC9\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"240,320 222,321 231,336\" fill=\"#BFCDC9\"/>\n</svg>\n\n</section>", "note": "這一課給完全沒學過氧化還原的同學。在這個階段，我們只用「得到或失去氧」來定義，電子轉移到高中再學。"}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">鐵釘放進藍色溶液，為什麼會變紅？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M9 3h6M10 3v6L4.6 18.6A1.6 1.6 0 0 0 6 21h12a1.6 1.6 0 0 0 1.4-2.4L14 9V3M7.5 15h9\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">鐵釘泡硫酸銅</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">幾分鐘後，鐵釘表面附著<b style=\"color:#18262B\">紅色的銅</b>，藍色也變淡了。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M12 3 2 21h20L12 3zM12 10v5M12 18h.01\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">腳踏車淋雨</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">鏈條慢慢變成<b style=\"color:#18262B\">橘褐色</b>，還會剝落。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">這兩種變化是同一類反應：有東西<b style=\"color:#B4521F\">得到或失去了氧</b>。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 2</p>\n\n</section>", "note": "示範：把鐵釘用砂紙磨乾淨，放進硫酸銅溶液，或播一段短片。先請學生寫下預測。"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">判斷氧化還原</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">分辨誰得到氧、誰失去氧。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">找出氧化劑和還原劑</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">找出誰給氧、誰搶氧。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">會用活性大小</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">預測金屬會不會反應。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 3</p>\n\n</section>", "note": "三個目標對應三段：得氧與失氧、活性大小、生活應用（煉鐵和防鏽）。"}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">開始之前</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先認識四個詞</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">氧化</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">物質<b style=\"color:#18262B\">得到氧</b>。鐵生鏽就是氧化。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">還原</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">物質<b style=\"color:#18262B\">失去氧</b>。從鐵礦取出鐵就是還原。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">氧化劑</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">把自己的氧給出去（自己被還原）。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">還原劑</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">把別人的氧搶過來（自己被氧化）。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 4</p>\n\n</section>", "note": "橘色卡片是得到氧的一方，藍色卡片是失去氧的一方。名稱看起來是反的：還原劑自己是被氧化的那個。"}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"得氧與失氧\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一定成對</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">一個失去氧，另一個就得到氧</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"氧化銅把氧原子交給碳；銅被留下來，碳變成二氧化碳\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<circle cx=\"80\" cy=\"190\" r=\"40\" fill=\"#C8693A\"/><text x=\"80\" y=\"199\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">Cu</text><circle cx=\"150\" cy=\"190\" r=\"30\" fill=\"#B4521F\"/><text x=\"150\" y=\"199\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><text x=\"115\" y=\"120\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">CuO</text><text x=\"260\" y=\"202\" text-anchor=\"middle\" font-size=\"48\" font-weight=\"700\" fill=\"#4F5F64\">+</text><circle cx=\"350\" cy=\"190\" r=\"38\" fill=\"#2F3B40\"/><text x=\"350\" y=\"199\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">C</text><text x=\"350\" y=\"120\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">C</text><line x1=\"150\" y1=\"240\" x2=\"314\" y2=\"249\" stroke=\"#B4521F\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"330,250 315,240 314,258\" fill=\"#B4521F\"/><path d=\"M150 230 Q240 330 340 236\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"5\" stroke-dasharray=\"10 8\"/><line x1=\"410\" y1=\"190\" x2=\"448\" y2=\"190\" stroke=\"#4F5F64\" stroke-width=\"7\" stroke-linecap=\"round\"/><polygon points=\"470,190 448,178 448,202\" fill=\"#4F5F64\"/><circle cx=\"530\" cy=\"120\" r=\"36\" fill=\"#C8693A\"/><text x=\"530\" y=\"129\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">Cu</text><text x=\"530\" y=\"70\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">Cu</text><circle cx=\"530\" cy=\"270\" r=\"34\" fill=\"#2F3B40\"/><text x=\"530\" y=\"279\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">C</text><circle cx=\"588\" cy=\"270\" r=\"26\" fill=\"#B4521F\"/><text x=\"588\" y=\"279\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><text x=\"560\" y=\"340\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">CO₂</text><text x=\"115\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#2463B8\">失去 O</text><text x=\"350\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#B4521F\">得到 O</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">2CuO + C → 2Cu + CO₂</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">CuO <b style=\"color:#2463B8\">失去</b>氧 → 被<b>還原</b>成銅。</p>\n<p style=\"font-size:34px;line-height:1.5\">C <b style=\"color:#B4521F\">得到</b>氧 → 被<b>氧化</b>成 CO₂。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">氧化和還原一定同時發生。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 5</p>\n\n</section>", "note": "用手指追著氧原子走：它從銅身上出發，最後到了碳身上。氧離開的那個被還原，氧加入的那個被氧化。"}, {"id": "figure", "html": "<section id=\"figure\" data-section=\"活性大小\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">活性大小</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">有些元素搶氧的力氣比較大</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"十六種元素排成一列，從活性最大的鉀到活性最小的金，碳、鐵、氫、銅特別標示\" width=\"1600\" height=\"250\" viewBox=\"0 0 1600 250\">\n<rect x=\"40\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"82\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">K</text><rect x=\"136\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"178\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Na</text><rect x=\"232\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"274\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Ca</text><rect x=\"328\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"370\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Mg</text><rect x=\"424\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"466\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Al</text><rect x=\"520\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"562\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#FFFFFF\">C</text><rect x=\"616\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"658\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Zn</text><rect x=\"712\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"754\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#FFFFFF\">Fe</text><rect x=\"808\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"850\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Sn</text><rect x=\"904\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"946\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Pb</text><rect x=\"1000\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"1042\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#FFFFFF\">H</text><rect x=\"1096\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"1138\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#FFFFFF\">Cu</text><rect x=\"1192\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"1234\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Hg</text><rect x=\"1288\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"1330\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Ag</text><rect x=\"1384\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"1426\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Pt</text><rect x=\"1480\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"1522\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Au</text><line x1=\"60\" y1=\"190\" x2=\"1518\" y2=\"190\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1540,190 1518,178 1518,202\" fill=\"#4F5F64\"/><text x=\"60\" y=\"236\" text-anchor=\"start\" font-size=\"28\" font-weight=\"800\" fill=\"#B4521F\">活性大</text><text x=\"1540\" y=\"236\" text-anchor=\"end\" font-size=\"28\" font-weight=\"800\" fill=\"#2463B8\">活性小</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">K &gt; Na &gt; Ca &gt; Mg &gt; Al &gt; C &gt; Zn &gt; Fe &gt; Sn &gt; Pb &gt; H &gt; Cu &gt; Hg &gt; Ag &gt; Pt &gt; Au</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>活性大</b>的元素可以把活性小的元素的氧搶走。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>碳排在鐵前面</b>，所以碳能把鐵礦裡的氧拉出來。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>金和白金</b>幾乎不反應，所以在自然界以純金屬的樣子出現。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 6</p>\n\n</section>", "note": "學生不必背整串，只要會使用。特別標示的 C、Fe、H、Cu 是這一課最常用到的四個。"}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">會不會反應？</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">活性大的金屬會把活性小的擠出來</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"鐵釘放進藍色硫酸銅溶液；兩分鐘後鐵釘表面附著銅，溶液顏色變淡\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<path d=\"M140 40 V300 Q140 340 190 340 Q240 340 240 300 V40\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><path d=\"M145 140 H235 V298 Q235 334 190 334 Q145 334 145 298 Z\" fill=\"#5B8DEF\"/><rect x=\"180\" y=\"20\" width=\"20\" height=\"270\" rx=\"6\" fill=\"#8C989C\"/><text x=\"190\" y=\"380\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">開始</text><line x1=\"290\" y1=\"200\" x2=\"380\" y2=\"200\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"400,200 380,189 380,211\" fill=\"#4F5F64\"/><path d=\"M450 40 V300 Q450 340 500 340 Q550 340 550 300 V40\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><path d=\"M455 140 H545 V298 Q545 334 500 334 Q455 334 455 298 Z\" fill=\"#A9C4F5\"/><rect x=\"490\" y=\"20\" width=\"20\" height=\"270\" rx=\"6\" fill=\"#8C989C\"/><rect x=\"488\" y=\"140\" width=\"24\" height=\"150\" rx=\"6\" fill=\"#C8693A\"/><text x=\"500\" y=\"380\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">2 分鐘後</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">金屬 + 溶液</th><th style=\"width:60%;text-align:left\">會反應嗎？</th></tr>\n<tr><td>Fe + CuSO₄</td><td><b>會：Fe &gt; Cu</b></td></tr>\n<tr><td>Zn + CuSO₄</td><td><b>會：Zn &gt; Cu</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td>Cu + FeSO₄</td><td><b>不會：Cu &lt; Fe</b></td></tr>\n<tr><td>Cu + AgNO₃</td><td><b>會：Cu &gt; Ag</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">查活性大小：放進去的金屬必須比溶液裡的金屬<b>活性大</b>。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 7</p>\n\n</section>", "note": "這就是開場謎題的答案：鐵的活性比銅大，所以鐵取代了銅，紅色的銅就附著在鐵釘上。標示的那一列是不會反應的情況。"}, {"id": "formula", "html": "<section id=\"formula\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">煉鐵</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">Fe₂O₃</p>\n<p style=\"font-size:32px;color:#BFCDC9\">鐵礦</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">+</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#7FB0F2\">C</p>\n<p style=\"font-size:32px;color:#BFCDC9\">碳</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">→</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#F3F5F2\">Fe</p>\n<p style=\"font-size:32px;color:#BFCDC9\">鐵</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:700;line-height:1.4\">碳把氧搶走，鐵就留下來了。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">在高爐中：Fe₂O₃ + 3CO → 2Fe + 3CO₂。鐵礦被還原，碳（以 CO 的形式）被氧化。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">氧化與還原 · 8</p>\n\n</section>", "note": "大字公式表達的是概念，不是平衡的反應式；平衡的版本寫在下面。煉鐵之所以可行，就是因為碳的活性比鐵大。"}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">生鏽</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">鐵要同時碰到空氣和水才會生鏽</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"三支試管裡各有一根鐵釘：有空氣又有水的那支生鏽了；只有乾燥空氣、或水面蓋了一層油的都沒有生鏽\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<path d=\"M40 50 V280 Q40 320 85 320 Q130 320 130 280 V50\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><path d=\"M45 200 H125 V278 Q125 314 85 314 Q45 314 45 278 Z\" fill=\"#E1ECFA\"/><rect x=\"76\" y=\"70\" width=\"18\" height=\"230\" rx=\"5\" fill=\"#8C989C\"/><ellipse cx=\"85\" cy=\"170\" rx=\"12\" ry=\"8\" fill=\"#A0522D\"/><ellipse cx=\"85\" cy=\"205\" rx=\"12\" ry=\"8\" fill=\"#A0522D\"/><ellipse cx=\"85\" cy=\"240\" rx=\"12\" ry=\"8\" fill=\"#A0522D\"/><text x=\"85\" y=\"350\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"800\" fill=\"#18262B\">空氣 + 水</text><path d=\"M270 50 V280 Q270 320 315 320 Q360 320 360 280 V50\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><rect x=\"306\" y=\"70\" width=\"18\" height=\"230\" rx=\"5\" fill=\"#8C989C\"/><text x=\"315\" y=\"350\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"800\" fill=\"#18262B\">乾燥空氣</text><path d=\"M500 50 V280 Q500 320 545 320 Q590 320 590 280 V50\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><path d=\"M505 200 H585 V278 Q585 314 545 314 Q505 314 505 278 Z\" fill=\"#E1ECFA\"/><rect x=\"505\" y=\"186\" width=\"80\" height=\"16\" fill=\"#E0B020\"/><rect x=\"536\" y=\"70\" width=\"18\" height=\"230\" rx=\"5\" fill=\"#8C989C\"/><text x=\"545\" y=\"350\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"800\" fill=\"#18262B\">隔絕空氣</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">只有最左邊的鐵釘生鏽。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">生鏽是<b>緩慢的氧化</b>：鐵 + 氧 + 水 → 鐵鏽（氧化鐵）。</p>\n<p style=\"font-size:34px;line-height:1.5\">拿掉空氣或水，生鏽就停止。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">油漆、上油、鍍鋅，都是把氧和水隔開。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 9</p>\n\n</section>", "note": "可選活動：週一架好三支試管，幾天後再觀察。煮過的水上面加一層油，可以防止空氣再溶進水裡。"}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一張表看懂</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">氧化劑和還原劑，差在哪裡？</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">比較</th><th style=\"width:33%;text-align:left\">氧化劑</th><th style=\"width:33%;text-align:left\">還原劑</th></tr>\n<tr><td>氧</td><td><span style=\"color:#2463B8\">給出去</span></td><td><span style=\"color:#B4521F\">搶過來</span></td></tr>\n<tr><td>自己變成</td><td>被還原</td><td>被氧化</td></tr>\n<tr><td>2CuO + C</td><td>CuO</td><td>C</td></tr>\n<tr><td>煉鐵</td><td>鐵礦（Fe₂O₃）</td><td>碳（CO）</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">一句話記住：</b> 還原劑搶氧，自己被氧化；氧化劑給氧，自己被還原。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 10</p>\n\n</section>", "note": "最後兩列先遮住，讓學生自己填。"}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">例題</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">2Mg + O₂ → 2MgO：誰被氧化？誰是氧化劑？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">追著氧走</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">O₂ → MgO</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">誰得到氧？</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">Mg</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">所以 Mg</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">被氧化</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">O₂ 給出氧</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">是氧化劑</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Mg <span style=\"color:#2463B8\">被氧化</span>；O₂ 是<span style=\"color:#2463B8\">氧化劑</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 11</p>\n\n</section>", "note": "燃燒鎂帶會發出很亮的白光；如果示範，提醒學生不要直視。"}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">生鏽只是顏色改變嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">不是。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">鐵鏽（氧化鐵）是<b>新的物質</b>：易碎、脆弱、橘褐色。所以生鏽是化學變化，也是一種氧化。</p>\n<p style=\"font-size:34px;line-height:1.5\">生鏽的鐵釘其實會變<b>重</b>，因為它從空氣中得到了氧原子。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">氧化與還原 · 12</p>\n\n</section>", "note": "可以對比物理變化，例如把鐵釘折彎或冰融化：沒有產生新物質。"}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:34px;line-height:1.5\">是非題：氧化可以單獨發生，不需要還原。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:34px;line-height:1.5\">銅片放進硫酸亞鐵溶液會反應嗎？為什麼？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:34px;line-height:1.5\">在 2CuO + C → 2Cu + CO₂ 中，哪一個是還原劑？</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">氧化與還原 · 13</p>\n\n</section>", "note": "先讓學生自己作答。第 2 題提醒他們查活性大小。"}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:700\">錯</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">兩者一定同時發生。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:700\">不會</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">銅的活性比鐵小。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:700\">C</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">它把 CuO 的氧搶走。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">得到氧是氧化，失去氧是還原。<br><span style=\"color:#E58A55\">活性大的元素會把氧搶走。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">氧化與還原 · 14</p>\n\n</section>", "note": "可選出場單：「用活性大小解釋，為什麼鐵釘上出現了紅色的銅？」"}]}, "chem-redox-en": {"title": "Oxidation & Reduction", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">CHEMISTRY</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Oxidation &amp;<br>Reduction</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">Why does iron rust, and how do we get iron from rock?<br>Follow the oxygen.</p>\n</div>\n<svg aria-label=\"A rusty iron nail with oxygen atoms arrowing toward it\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<g transform=\"rotate(-28 360 240)\"><rect x=\"110\" y=\"215\" width=\"470\" height=\"50\" rx=\"8\" fill=\"#8C989C\"/><rect x=\"80\" y=\"190\" width=\"40\" height=\"100\" rx=\"8\" fill=\"#8C989C\"/><polygon points=\"580,215 680,240 580,265\" fill=\"#8C989C\"/><ellipse cx=\"220\" cy=\"232\" rx=\"40\" ry=\"18\" fill=\"#A0522D\"/><ellipse cx=\"330\" cy=\"250\" rx=\"54\" ry=\"16\" fill=\"#E58A55\"/><ellipse cx=\"450\" cy=\"228\" rx=\"34\" ry=\"14\" fill=\"#A0522D\"/><ellipse cx=\"520\" cy=\"252\" rx=\"30\" ry=\"12\" fill=\"#E58A55\"/></g><circle cx=\"560\" cy=\"90\" r=\"26\" fill=\"#E58A55\"/><text x=\"560\" y=\"99\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"630\" cy=\"150\" r=\"26\" fill=\"#E58A55\"/><text x=\"630\" y=\"159\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><circle cx=\"150\" cy=\"380\" r=\"26\" fill=\"#E58A55\"/><text x=\"150\" y=\"389\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><line x1=\"540\" y1=\"110\" x2=\"482\" y2=\"160\" stroke=\"#BFCDC9\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"470,170 488,166 476,153\" fill=\"#BFCDC9\"/><line x1=\"605\" y1=\"165\" x2=\"534\" y2=\"198\" stroke=\"#BFCDC9\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"520,205 538,206 531,190\" fill=\"#BFCDC9\"/><line x1=\"175\" y1=\"360\" x2=\"226\" y2=\"328\" stroke=\"#BFCDC9\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"240,320 222,321 231,336\" fill=\"#BFCDC9\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied oxidation and reduction. At this level we define both by gaining or losing oxygen; electron transfer comes later in high school."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why does a nail turn red in a blue liquid?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M9 3h6M10 3v6L4.6 18.6A1.6 1.6 0 0 0 6 21h12a1.6 1.6 0 0 0 1.4-2.4L14 9V3M7.5 15h9\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Nail in copper sulfate</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">After a few minutes the nail is coated in <b style=\"color:#18262B\">red copper</b> and the blue fades.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M12 3 2 21h20L12 3zM12 10v5M12 18h.01\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Bike left in the rain</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">The chain slowly turns <b style=\"color:#18262B\">orange-brown</b> and flaky.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Both changes are the same kind of reaction: something <b style=\"color:#B4521F\">gains or loses oxygen</b>.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 2</p>\n\n</section>", "note": "Demo: sand an iron nail clean and drop it into copper(II) sulfate solution, or show a short video. Let students write a prediction first."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Spot oxidation</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Tell who gains and who loses oxygen.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Name the agents</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Find who gives and who takes oxygen.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Use the series</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Predict whether a metal reacts.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 3</p>\n\n</section>", "note": "The goals match the three parts: gain and loss of oxygen, the reactivity series, and real-world uses such as smelting and rust prevention."}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BEFORE YOU START</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Four words you need first</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Oxidation</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">A substance <b style=\"color:#18262B\">gains oxygen</b>. Iron rusting is oxidation.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Reduction</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">A substance <b style=\"color:#18262B\">loses oxygen</b>. Getting iron from ore is reduction.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Oxidizing agent</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Gives its oxygen away (and is reduced).</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Reducing agent</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Takes oxygen from something else (and is oxidized).</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 4</p>\n\n</section>", "note": "Orange cards are the oxygen-gaining side; blue cards are the oxygen-losing side. The agent names are backward on purpose: the reducing agent is the one that gets oxidized."}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"Gaining and losing oxygen\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ALWAYS A PAIR</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">One loses oxygen, another gains it</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Copper oxide gives its oxygen atom to carbon; copper is left alone and carbon becomes carbon dioxide\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<circle cx=\"80\" cy=\"190\" r=\"40\" fill=\"#C8693A\"/><text x=\"80\" y=\"199\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">Cu</text><circle cx=\"150\" cy=\"190\" r=\"30\" fill=\"#B4521F\"/><text x=\"150\" y=\"199\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><text x=\"115\" y=\"120\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">CuO</text><text x=\"260\" y=\"202\" text-anchor=\"middle\" font-size=\"48\" font-weight=\"700\" fill=\"#4F5F64\">+</text><circle cx=\"350\" cy=\"190\" r=\"38\" fill=\"#2F3B40\"/><text x=\"350\" y=\"199\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">C</text><text x=\"350\" y=\"120\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">C</text><line x1=\"150\" y1=\"240\" x2=\"314\" y2=\"249\" stroke=\"#B4521F\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"330,250 315,240 314,258\" fill=\"#B4521F\"/><path d=\"M150 230 Q240 330 340 236\" fill=\"none\" stroke=\"#B4521F\" stroke-width=\"5\" stroke-dasharray=\"10 8\"/><line x1=\"410\" y1=\"190\" x2=\"448\" y2=\"190\" stroke=\"#4F5F64\" stroke-width=\"7\" stroke-linecap=\"round\"/><polygon points=\"470,190 448,178 448,202\" fill=\"#4F5F64\"/><circle cx=\"530\" cy=\"120\" r=\"36\" fill=\"#C8693A\"/><text x=\"530\" y=\"129\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">Cu</text><text x=\"530\" y=\"70\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">Cu</text><circle cx=\"530\" cy=\"270\" r=\"34\" fill=\"#2F3B40\"/><text x=\"530\" y=\"279\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">C</text><circle cx=\"588\" cy=\"270\" r=\"26\" fill=\"#B4521F\"/><text x=\"588\" y=\"279\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#FFFFFF\">O</text><text x=\"560\" y=\"340\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">CO₂</text><text x=\"115\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#2463B8\">loses O</text><text x=\"350\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#B4521F\">gains O</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">2CuO + C → 2Cu + CO₂</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">CuO <b style=\"color:#2463B8\">loses</b> oxygen → it is <b>reduced</b> to copper.</p>\n<p style=\"font-size:34px;line-height:1.5\">C <b style=\"color:#B4521F\">gains</b> oxygen → it is <b>oxidized</b> to CO₂.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Oxidation and reduction always happen at the same time.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 5</p>\n\n</section>", "note": "Trace the oxygen atom with your finger: it starts on copper and ends on carbon. Whatever the oxygen leaves is reduced; whatever it joins is oxidized."}, {"id": "figure", "html": "<section id=\"figure\" data-section=\"The reactivity series\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">REACTIVITY SERIES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Some elements grab oxygen harder than others</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"Sixteen elements in a row from most reactive potassium to least reactive gold, with carbon, iron, hydrogen and copper highlighted\" width=\"1600\" height=\"250\" viewBox=\"0 0 1600 250\">\n<rect x=\"40\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"82\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">K</text><rect x=\"136\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"178\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Na</text><rect x=\"232\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"274\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Ca</text><rect x=\"328\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"370\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Mg</text><rect x=\"424\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"466\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Al</text><rect x=\"520\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"562\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#FFFFFF\">C</text><rect x=\"616\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"658\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Zn</text><rect x=\"712\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"754\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#FFFFFF\">Fe</text><rect x=\"808\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"850\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Sn</text><rect x=\"904\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"946\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Pb</text><rect x=\"1000\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"1042\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#FFFFFF\">H</text><rect x=\"1096\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"1138\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#FFFFFF\">Cu</text><rect x=\"1192\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"1234\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Hg</text><rect x=\"1288\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"1330\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Ag</text><rect x=\"1384\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"1426\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Pt</text><rect x=\"1480\" y=\"60\" width=\"84\" height=\"84\" rx=\"14\" fill=\"#E1ECFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"1522\" y=\"114\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">Au</text><line x1=\"60\" y1=\"190\" x2=\"1518\" y2=\"190\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1540,190 1518,178 1518,202\" fill=\"#4F5F64\"/><text x=\"60\" y=\"236\" text-anchor=\"start\" font-size=\"28\" font-weight=\"800\" fill=\"#B4521F\">more reactive</text><text x=\"1540\" y=\"236\" text-anchor=\"end\" font-size=\"28\" font-weight=\"800\" fill=\"#2463B8\">less reactive</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">K &gt; Na &gt; Ca &gt; Mg &gt; Al &gt; C &gt; Zn &gt; Fe &gt; Sn &gt; Pb &gt; H &gt; Cu &gt; Hg &gt; Ag &gt; Pt &gt; Au</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">A <b>more reactive</b> element can take oxygen away from a less reactive one.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Carbon sits above iron</b>, so carbon can pull oxygen out of iron ore.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Gold and platinum</b> hardly react, which is why they are found as pure metal.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 6</p>\n\n</section>", "note": "Students don’t need to memorize the whole list; they should be able to use it. Highlighted: C, Fe, H and Cu, the four used most in this lesson."}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WILL IT REACT?</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A more reactive metal pushes a weaker one out</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"An iron nail in blue copper sulfate solution; two minutes later the nail is coated in copper and the solution is paler\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<path d=\"M140 40 V300 Q140 340 190 340 Q240 340 240 300 V40\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><path d=\"M145 140 H235 V298 Q235 334 190 334 Q145 334 145 298 Z\" fill=\"#5B8DEF\"/><rect x=\"180\" y=\"20\" width=\"20\" height=\"270\" rx=\"6\" fill=\"#8C989C\"/><text x=\"190\" y=\"380\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Start</text><line x1=\"290\" y1=\"200\" x2=\"380\" y2=\"200\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"400,200 380,189 380,211\" fill=\"#4F5F64\"/><path d=\"M450 40 V300 Q450 340 500 340 Q550 340 550 300 V40\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><path d=\"M455 140 H545 V298 Q545 334 500 334 Q455 334 455 298 Z\" fill=\"#A9C4F5\"/><rect x=\"490\" y=\"20\" width=\"20\" height=\"270\" rx=\"6\" fill=\"#8C989C\"/><rect x=\"488\" y=\"140\" width=\"24\" height=\"150\" rx=\"6\" fill=\"#C8693A\"/><text x=\"500\" y=\"380\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">After 2 min</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">Metal + solution</th><th style=\"width:60%;text-align:left\">Reacts?</th></tr>\n<tr><td>Fe + CuSO₄</td><td><b>Yes: Fe &gt; Cu</b></td></tr>\n<tr><td>Zn + CuSO₄</td><td><b>Yes: Zn &gt; Cu</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td>Cu + FeSO₄</td><td><b>No: Cu &lt; Fe</b></td></tr>\n<tr><td>Cu + AgNO₃</td><td><b>Yes: Cu &gt; Ag</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Check the series: the metal going in must be <b>more reactive</b> than the metal in the solution.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 7</p>\n\n</section>", "note": "This is the opening puzzle explained: iron is more reactive than copper, so iron takes copper’s place and red copper metal forms on the nail. The highlighted row is the case that does not react."}, {"id": "formula", "html": "<section id=\"formula\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">SMELTING IRON</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">Fe₂O₃</p>\n<p style=\"font-size:32px;color:#BFCDC9\">iron ore</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">+</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#7FB0F2\">C</p>\n<p style=\"font-size:32px;color:#BFCDC9\">carbon</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">→</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#F3F5F2\">Fe</p>\n<p style=\"font-size:32px;color:#BFCDC9\">iron</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:800;line-height:1.4\">Carbon takes the oxygen; iron is left behind.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">In a blast furnace: Fe₂O₃ + 3CO → 2Fe + 3CO₂. Iron ore is reduced; carbon (as CO) is oxidized.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Oxidation &amp; Reduction · 8</p>\n\n</section>", "note": "The big formula is the idea, not a balanced equation; the balanced version is underneath. Smelting works only because carbon is above iron in the series."}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">RUSTING</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Iron needs both air and water to rust</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Three test tubes with nails: the one with air and water rusts; the ones with only dry air or with water under an oil layer do not\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<path d=\"M40 50 V280 Q40 320 85 320 Q130 320 130 280 V50\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><path d=\"M45 200 H125 V278 Q125 314 85 314 Q45 314 45 278 Z\" fill=\"#E1ECFA\"/><rect x=\"76\" y=\"70\" width=\"18\" height=\"230\" rx=\"5\" fill=\"#8C989C\"/><ellipse cx=\"85\" cy=\"170\" rx=\"12\" ry=\"8\" fill=\"#A0522D\"/><ellipse cx=\"85\" cy=\"205\" rx=\"12\" ry=\"8\" fill=\"#A0522D\"/><ellipse cx=\"85\" cy=\"240\" rx=\"12\" ry=\"8\" fill=\"#A0522D\"/><text x=\"85\" y=\"350\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"800\" fill=\"#18262B\">Air + water</text><path d=\"M270 50 V280 Q270 320 315 320 Q360 320 360 280 V50\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><rect x=\"306\" y=\"70\" width=\"18\" height=\"230\" rx=\"5\" fill=\"#8C989C\"/><text x=\"315\" y=\"350\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"800\" fill=\"#18262B\">Dry air</text><path d=\"M500 50 V280 Q500 320 545 320 Q590 320 590 280 V50\" fill=\"none\" stroke=\"#18262B\" stroke-width=\"5\"/><path d=\"M505 200 H585 V278 Q585 314 545 314 Q505 314 505 278 Z\" fill=\"#E1ECFA\"/><rect x=\"505\" y=\"186\" width=\"80\" height=\"16\" fill=\"#E0B020\"/><rect x=\"536\" y=\"70\" width=\"18\" height=\"230\" rx=\"5\" fill=\"#8C989C\"/><text x=\"545\" y=\"350\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"800\" fill=\"#18262B\">No air</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Only the left nail rusts.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">Rusting is <b>slow oxidation</b>: iron + oxygen + water → rust (iron oxide).</p>\n<p style=\"font-size:34px;line-height:1.5\">Take away air or water and rusting stops.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Paint, oil and zinc coatings keep oxygen and water away.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 9</p>\n\n</section>", "note": "Optional activity: set up the three tubes at the start of the week and check them a few days later. The oil layer stops air from dissolving into the boiled water."}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ONE TABLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Oxidizing agent vs. reducing agent</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">Compare</th><th style=\"width:33%;text-align:left\">Oxidizing agent</th><th style=\"width:33%;text-align:left\">Reducing agent</th></tr>\n<tr><td>Oxygen</td><td><span style=\"color:#2463B8\">Gives it away</span></td><td><span style=\"color:#B4521F\">Takes it</span></td></tr>\n<tr><td>It becomes</td><td>Reduced</td><td>Oxidized</td></tr>\n<tr><td>2CuO + C</td><td>CuO</td><td>C</td></tr>\n<tr><td>Smelting iron</td><td>Iron ore (Fe₂O₃)</td><td>Carbon (CO)</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">Remember:</b> the reducing agent takes oxygen and gets oxidized; the oxidizing agent gives oxygen and gets reduced.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 10</p>\n\n</section>", "note": "Ask students to fill in the last two rows before revealing them."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.1\">2Mg + O₂ → 2MgO: who is oxidized, and what is the oxidizing agent?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Follow the O</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">O₂ → MgO</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Who gains O?</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">Mg</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">So Mg is</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">oxidized</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">O₂ gives O</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">oxidizing<br>agent</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Mg is <span style=\"color:#2463B8\">oxidized</span>; O₂ is the <span style=\"color:#2463B8\">oxidizing agent</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 11</p>\n\n</section>", "note": "Burning magnesium ribbon gives a bright white flash; if you show it, remind students not to look straight at it."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Is rusting just a color change?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">Rust (iron oxide) is a <b>new substance</b>: flaky, weak and orange-brown. That makes rusting a chemical change, and an oxidation.</p>\n<p style=\"font-size:34px;line-height:1.5\">A rusty nail actually gets <b>heavier</b>, because it has gained oxygen atoms from the air.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Oxidation &amp; Reduction · 12</p>\n\n</section>", "note": "Contrast with a physical change such as bending a nail or melting ice: no new substance forms."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">True or false: oxidation can happen without reduction.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">Will a copper strip react with iron(II) sulfate solution? Why?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">In 2CuO + C → 2Cu + CO₂, which substance is the reducing agent?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Oxidation &amp; Reduction · 13</p>\n\n</section>", "note": "Let students answer on their own first. For Q2, point them to the reactivity series."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">False</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">They always happen together.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">No</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Copper is less reactive than iron.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">C</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">It takes oxygen from CuO.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Gain oxygen = oxidation; lose oxygen = reduction.<br><span style=\"color:#E58A55\">The more reactive element wins the oxygen.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Oxidation &amp; Reduction · 14</p>\n\n</section>", "note": "Optional exit ticket: “Use the reactivity series to explain why red copper appeared on the nail.”"}]}, "bio-osmosis-zh": {"title": "細胞：滲透作用", "lang": "zh", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">生物</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">細胞：<br>滲透作用</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">水是怎麼進出細胞的？<br>它總是往比較鹹的那邊跑。</p>\n</div>\n<svg aria-label=\"一個細胞，四周的水滴正朝它移動\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<circle cx=\"360\" cy=\"240\" r=\"170\" fill=\"#22343A\" stroke=\"#E58A55\" stroke-width=\"10\"/><circle cx=\"400\" cy=\"210\" r=\"46\" fill=\"#E58A55\" opacity=\".85\"/><path d=\"M80 120 q14 -26 0 -40 q-14 14 0 40z\" fill=\"#7FB0F2\"/><path d=\"M110 400 q14 -26 0 -40 q-14 14 0 40z\" fill=\"#7FB0F2\"/><path d=\"M640 150 q14 -26 0 -40 q-14 14 0 40z\" fill=\"#7FB0F2\"/><path d=\"M620 380 q14 -26 0 -40 q-14 14 0 40z\" fill=\"#7FB0F2\"/><line x1=\"110\" y1=\"150\" x2=\"184\" y2=\"183\" stroke=\"#7FB0F2\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"200,190 188,174 180,192\" fill=\"#7FB0F2\"/><line x1=\"140\" y1=\"380\" x2=\"200\" y2=\"340\" stroke=\"#7FB0F2\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"215,330 195,332 206,348\" fill=\"#7FB0F2\"/><line x1=\"610\" y1=\"170\" x2=\"537\" y2=\"194\" stroke=\"#7FB0F2\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"520,200 540,204 534,185\" fill=\"#7FB0F2\"/><line x1=\"590\" y1=\"370\" x2=\"521\" y2=\"329\" stroke=\"#7FB0F2\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"505,320 515,338 526,321\" fill=\"#7FB0F2\"/>\n</svg>\n\n</section>", "note": "這一課給沒有深入學過細胞的同學。我們從撒鹽的小黃瓜開始，建立擴散的概念，最後解釋蔬菜為什麼能保持爽脆、醫院為什麼用生理食鹽水。"}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">小黃瓜撒鹽後，為什麼會出水？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 2.7s6.5 7 6.5 11.8a6.5 6.5 0 0 1-13 0C5.5 9.7 12 2.7 12 2.7z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">小黃瓜撒鹽</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">十分鐘後，<b style=\"color:#18262B\">盤子上積了一灘水</b>，小黃瓜也變軟了。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M11 20A7 7 0 0 1 4 13c0-6 6-9 16-10-1 10-4 16-10 16zM4 21c3-5 7-8 11-10\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">生菜噴水</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">超市在蔬菜上噴水，讓它們保持<b style=\"color:#18262B\">爽脆硬挺</b>。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">兩種情況裡，水都在<b style=\"color:#B4521F\">進出蔬菜的細胞</b>。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 2</p>\n\n</section>", "note": "示範：上課一開始就在小黃瓜片上撒鹽，放在盤子上。講完這張讓學生看盤子裡的水，問他們：水是來自鹽、空氣，還是小黃瓜裡面？"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">說明擴散</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">解釋粒子為什麼會散開。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M12 2.7s6.5 7 6.5 11.8a6.5 6.5 0 0 1-13 0C5.5 9.7 12 2.7 12 2.7z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">預測滲透方向</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">判斷水會往哪邊移動。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 20A7 7 0 0 1 4 13c0-6 6-9 16-10-1 10-4 16-10 16zM4 21c3-5 7-8 11-10\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">解釋生活現象</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">爽脆的蔬菜、生理食鹽水點滴。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 3</p>\n\n</section>", "note": "三個目標對應三段：擴散、滲透規則、滲透對植物和動物細胞的影響。"}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">開始之前</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先認識四個詞</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">細胞膜</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">包住細胞的薄膜。水可以通過，鹽很難通過。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">濃度</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">一定量的水裡含有多少東西（例如鹽）。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">擴散</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">粒子從<b style=\"color:#18262B\">擁擠的地方往空曠的地方</b>散開。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">滲透</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\"><b style=\"color:#18262B\">水</b>穿過細胞膜的擴散。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 4</p>\n\n</section>", "note": "點出滲透是擴散的一種特例：道理相同，只是移動的是水。"}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"擴散\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">擴散</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">粒子會一直散開，直到平均</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"左：橘色粒子擠在水槽一邊。右：一段時間後，粒子平均分散在整個水槽\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"20\" y=\"50\" width=\"260\" height=\"270\" rx=\"18\" fill=\"#E1ECFA\" stroke=\"#18262B\" stroke-width=\"5\"/><circle cx=\"40\" cy=\"80\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"63\" cy=\"121\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"86\" cy=\"162\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"109\" cy=\"203\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"42\" cy=\"244\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"65\" cy=\"285\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"88\" cy=\"106\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"111\" cy=\"147\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"44\" cy=\"188\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"67\" cy=\"229\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"90\" cy=\"270\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"113\" cy=\"91\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"46\" cy=\"132\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"69\" cy=\"173\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"92\" cy=\"214\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"115\" cy=\"255\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"48\" cy=\"296\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"71\" cy=\"117\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"94\" cy=\"158\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"117\" cy=\"199\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"50\" cy=\"240\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"73\" cy=\"281\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"96\" cy=\"102\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"119\" cy=\"143\" r=\"9\" fill=\"#B4521F\"/><rect x=\"340\" y=\"50\" width=\"280\" height=\"270\" rx=\"18\" fill=\"#E1ECFA\" stroke=\"#18262B\" stroke-width=\"5\"/><circle cx=\"350\" cy=\"70\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"411\" cy=\"117\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"472\" cy=\"164\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"533\" cy=\"211\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"594\" cy=\"258\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"405\" cy=\"75\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"466\" cy=\"122\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"527\" cy=\"169\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"588\" cy=\"216\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"399\" cy=\"263\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"460\" cy=\"80\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"521\" cy=\"127\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"582\" cy=\"174\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"393\" cy=\"221\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"454\" cy=\"268\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"515\" cy=\"85\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"576\" cy=\"132\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"387\" cy=\"179\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"448\" cy=\"226\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"509\" cy=\"273\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"570\" cy=\"90\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"381\" cy=\"137\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"442\" cy=\"184\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"503\" cy=\"231\" r=\"9\" fill=\"#B4521F\"/><line x1=\"150\" y1=\"185\" x2=\"244\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"260,185 244,176 244,194\" fill=\"#4F5F64\"/><text x=\"150\" y=\"30\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">開始</text><text x=\"480\" y=\"30\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">一段時間後</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">一滴食用色素滴進靜止的水裡。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">粒子一直在晃動、互相碰撞。</p>\n<p style=\"font-size:34px;line-height:1.5\">時間久了，它們會從<b>擁擠</b>的地方（濃度高）移到<b>空曠</b>的地方（濃度低）。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">不需要推它：擴散會自己發生。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 5</p>\n\n</section>", "note": "快速示範：在一杯靜止的清水裡滴一滴食用色素；或在教室前面噴芳香劑，請學生聞到時舉手。"}, {"id": "figure", "html": "<section id=\"figure\" data-section=\"滲透規則\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">滲透</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">水會往哪邊走？</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"三個細胞：在清水裡，箭頭朝內、細胞脹大；在和細胞一樣鹹的水裡，沒有變化；在鹽水裡，箭頭朝外、細胞縮小\" width=\"1500\" height=\"360\" viewBox=\"0 0 1500 360\">\n<rect x=\"20\" y=\"10\" width=\"420\" height=\"250\" rx=\"20\" fill=\"#E1ECFA\"/><circle cx=\"230\" cy=\"135\" r=\"80\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"6\"/><circle cx=\"202\" cy=\"111\" r=\"7\" fill=\"#18262B\"/><circle cx=\"254\" cy=\"115\" r=\"7\" fill=\"#18262B\"/><circle cx=\"230\" cy=\"139\" r=\"7\" fill=\"#18262B\"/><line x1=\"90\" y1=\"135\" x2=\"120\" y2=\"135\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"138,135 120,125 120,145\" fill=\"#2463B8\"/><line x1=\"370\" y1=\"135\" x2=\"340\" y2=\"135\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"322,135 340,145 340,125\" fill=\"#2463B8\"/><line x1=\"230\" y1=\"15\" x2=\"230\" y2=\"27\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"230,45 240,27 220,27\" fill=\"#2463B8\"/><line x1=\"230\" y1=\"255\" x2=\"230\" y2=\"243\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"230,225 220,243 240,243\" fill=\"#2463B8\"/><text x=\"230\" y=\"300\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">清水</text><text x=\"230\" y=\"340\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">水往內 → 脹大</text><rect x=\"540\" y=\"10\" width=\"420\" height=\"250\" rx=\"20\" fill=\"#E1ECFA\"/><circle cx=\"580\" cy=\"40\" r=\"7\" fill=\"#18262B\"/><circle cx=\"677\" cy=\"99\" r=\"7\" fill=\"#18262B\"/><circle cx=\"774\" cy=\"158\" r=\"7\" fill=\"#18262B\"/><circle cx=\"750\" cy=\"135\" r=\"62\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"6\"/><circle cx=\"728\" cy=\"116\" r=\"7\" fill=\"#18262B\"/><circle cx=\"769\" cy=\"120\" r=\"7\" fill=\"#18262B\"/><circle cx=\"750\" cy=\"138\" r=\"7\" fill=\"#18262B\"/><text x=\"750\" y=\"300\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">濃度相同</text><text x=\"750\" y=\"340\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">大小不變</text><rect x=\"1060\" y=\"10\" width=\"420\" height=\"250\" rx=\"20\" fill=\"#E1ECFA\"/><circle cx=\"1100\" cy=\"40\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1197\" cy=\"99\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1294\" cy=\"158\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1391\" cy=\"217\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1148\" cy=\"86\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1245\" cy=\"145\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1342\" cy=\"204\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1439\" cy=\"73\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1196\" cy=\"132\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1293\" cy=\"191\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1390\" cy=\"60\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1147\" cy=\"119\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1270\" cy=\"135\" r=\"46\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"6\"/><circle cx=\"1254\" cy=\"121\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1284\" cy=\"124\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1270\" cy=\"137\" r=\"7\" fill=\"#18262B\"/><line x1=\"1214\" y1=\"135\" x2=\"1184\" y2=\"135\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1166,135 1184,145 1184,125\" fill=\"#2463B8\"/><line x1=\"1326\" y1=\"135\" x2=\"1356\" y2=\"135\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1374,135 1356,125 1356,145\" fill=\"#2463B8\"/><line x1=\"1270\" y1=\"81\" x2=\"1270\" y2=\"69\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1270,51 1260,69 1280,69\" fill=\"#2463B8\"/><line x1=\"1270\" y1=\"189\" x2=\"1270\" y2=\"201\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1270,219 1280,201 1260,201\" fill=\"#2463B8\"/><text x=\"1270\" y=\"300\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">鹽水</text><text x=\"1270\" y=\"340\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">水往外 → 縮小</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">黑點 = 鹽。藍色箭頭 = 水移動的方向。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">外面是<b>清水</b>：細胞比較鹹，水往<b>內</b>走。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>濃度相同</b>：水進出一樣多，所以沒有變化。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">外面是<b>鹽水</b>：外面比較鹹，水往<b>外</b>走。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 6</p>\n\n</section>", "note": "在黑板畫一個細胞，裡外各點幾個鹽點，先請學生預測箭頭方向再揭曉。"}, {"id": "rule", "html": "<section id=\"rule\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">規則</p>\n<p style=\"font-size:96px;font-weight:900;line-height:1.2\">水會往<br>比較鹹的一邊移動。</p>\n<p style=\"font-size:36px;line-height:1.5;color:#BFCDC9\">細胞膜讓水通過，但鹽不容易穿過。所以移動的是水。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">細胞：滲透作用 · 7</p>\n\n</section>", "note": "回到開場：鹽在小黃瓜外面，所以水離開了小黃瓜的細胞，積在盤子上。"}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">看看數據</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">馬鈴薯條泡 40 分鐘後</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"三條馬鈴薯條：一開始 5.0 公分，泡清水後 5.3 公分，泡濃鹽水後 4.6 公分\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<rect x=\"200\" y=\"70\" width=\"350\" height=\"44\" rx=\"10\" fill=\"#E8D9A8\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"180\" y=\"102\" text-anchor=\"end\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">開始</text><text x=\"562.0\" y=\"102\" text-anchor=\"start\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">5.0 cm</text><rect x=\"200\" y=\"170\" width=\"371\" height=\"44\" rx=\"10\" fill=\"#F2E3B0\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"180\" y=\"202\" text-anchor=\"end\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">清水</text><text x=\"583.0\" y=\"202\" text-anchor=\"start\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">5.3 cm</text><rect x=\"200\" y=\"270\" width=\"322\" height=\"44\" rx=\"10\" fill=\"#D4C08A\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"180\" y=\"302\" text-anchor=\"end\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">濃鹽水</text><text x=\"534.0\" y=\"302\" text-anchor=\"start\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">4.6 cm</text><line x1=\"550\" y1=\"50\" x2=\"550\" y2=\"330\" stroke=\"#B4521F\" stroke-width=\"3\" stroke-dasharray=\"8 8\"/>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">泡在</th><th style=\"width:60%;text-align:left\">結果</th></tr>\n<tr><td>清水</td><td><b>5.3 cm，變硬：吸水</b></td></tr>\n<tr><td>淡鹽水</td><td><b>5.0 cm，沒變</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td>濃鹽水</td><td><b>4.6 cm，變軟：失水</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">變長變硬 = 吸了水。變短變軟 = 失去水。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 8</p>\n\n</section>", "note": "數據是典型結果，實際會有差異。可選實驗：上課前至少 40 分鐘，把一樣大的馬鈴薯條分別泡清水和 10% 鹽水各 3 條，課堂上讓兩人一組量長度、彎一彎。課堂上只泡 15 分鐘看不出差別。"}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">動物細胞和植物細胞</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">水太多，紅血球會脹破</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"三個紅血球：在清水中脹大破裂，在生理食鹽水中正常，在濃鹽水中皺縮\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<ellipse cx=\"110\" cy=\"170\" rx=\"82\" ry=\"82\" fill=\"#D84B4B\"/><line x1=\"180\" y1=\"120\" x2=\"215\" y2=\"95\" stroke=\"#D84B4B\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"40\" y1=\"120\" x2=\"5\" y2=\"95\" stroke=\"#D84B4B\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"190\" y1=\"210\" x2=\"230\" y2=\"230\" stroke=\"#D84B4B\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"30\" y1=\"210\" x2=\"-10\" y2=\"230\" stroke=\"#D84B4B\" stroke-width=\"5\" stroke-linecap=\"round\"/><ellipse cx=\"320\" cy=\"170\" rx=\"75\" ry=\"52\" fill=\"#D84B4B\"/><ellipse cx=\"320\" cy=\"170\" rx=\"34\" ry=\"21\" fill=\"#B83232\"/><path d=\"M500 140 q20 -20 40 0 q20 20 40 0 q-10 40 -40 50 q-30 -10 -40 -50z\" fill=\"#D84B4B\"/><text x=\"110\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">清水</text><text x=\"110\" y=\"334\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"#4F5F64\">脹大，可能破裂</text><text x=\"320\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">生理食鹽水</text><text x=\"320\" y=\"334\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"#4F5F64\">維持正常</text><text x=\"540\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">濃鹽水</text><text x=\"540\" y=\"334\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"#4F5F64\">皺縮</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">紅血球放在三種液體裡。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\"><b>動物細胞</b>只有一層薄膜，水進太多就可能脹破。</p>\n<p style=\"font-size:34px;line-height:1.5\"><b>植物細胞</b>有堅硬的細胞壁，水進來只會變硬，不會破。所以噴過水的生菜很爽脆。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">所以醫院的點滴用生理食鹽水，絕不用純水。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 9</p>\n\n</section>", "note": "生理食鹽水大約含 0.9% 的鹽，跟血液一樣鹹，所以水進出一樣多。"}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一張表看懂</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">擴散和滲透，差在哪裡？</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">比較</th><th style=\"width:33%;text-align:left\">擴散</th><th style=\"width:33%;text-align:left\">滲透</th></tr>\n<tr><td>誰在移動</td><td>任何粒子</td><td>只有水</td></tr>\n<tr><td>需要細胞膜嗎？</td><td>不需要</td><td>需要</td></tr>\n<tr><td>方向</td><td>擁擠 → 空曠</td><td>往比較鹹的一邊</td></tr>\n<tr><td>例子</td><td>香水味散滿房間</td><td>撒鹽的小黃瓜變軟</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">一句話記住：</b> 滲透就是水穿過細胞膜的擴散。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 10</p>\n\n</section>", "note": "請學生在每一欄各補一個例子。"}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">例題</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">含鹽 1% 的細胞放進 5% 的鹽水，會發生什麼事？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">比較</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">內 1%<br>外 5%</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">比較鹹的一邊</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">外面</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">水往哪走</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">往外</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">結果</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">細胞縮小</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">水跑出去，細胞<span style=\"color:#2463B8\">縮小</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 11</p>\n\n</section>", "note": "學生常常只說到「外面比較鹹」就停了。引導他們說完整：所以水往外走，所以細胞縮小。"}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">是鹽跑進細胞裡嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">不是。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">細胞膜讓<b>水</b>輕鬆通過，但鹽幾乎過不去。鹽留在原地，移動的是<b>水</b>。</p>\n<p style=\"font-size:34px;line-height:1.5\">所以撒鹽的小黃瓜是出水，而不是裡面變鹹：是水<b>跑出來</b>找鹽。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">細胞：滲透作用 · 12</p>\n\n</section>", "note": "學生常把「鹽比較多」理解成「鹽在移動」。用一句話收尾：鹽不動，水在跑。"}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:34px;line-height:1.5\">把紅血球放進清水，水往哪個方向移動？會發生什麼事？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:34px;line-height:1.5\">為什麼超市要在新鮮蔬菜上噴水？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:34px;line-height:1.5\">是非題：滲透作用中，鹽會穿過細胞膜。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">細胞：滲透作用 · 13</p>\n\n</section>", "note": "先讓學生自己作答。第 1 題提醒他們先找出比較鹹的一邊。"}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:700\">往內；脹大</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">細胞比較鹹，甚至可能脹破。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:700\">保持爽脆</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">水進入細胞，讓它們變硬挺。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:700\">錯</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">移動的是水，鹽留在原地。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">水往比較鹹的一邊移動。<br><span style=\"color:#E58A55\">鹽不動，水在跑。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">細胞：滲透作用 · 14</p>\n\n</section>", "note": "可選句型練習：「水會往細胞___移動，因為外面的濃度比較___。」「泡在___裡的薯條變___了，因為它___了水。」"}]}, "bio-osmosis-en": {"title": "Cells: Osmosis", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">BIOLOGY</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Cells:<br>Osmosis</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">How does water get in and out of a cell?<br>It always heads for the saltier side.</p>\n</div>\n<svg aria-label=\"A cell with water drops moving toward it from every side\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<circle cx=\"360\" cy=\"240\" r=\"170\" fill=\"#22343A\" stroke=\"#E58A55\" stroke-width=\"10\"/><circle cx=\"400\" cy=\"210\" r=\"46\" fill=\"#E58A55\" opacity=\".85\"/><path d=\"M80 120 q14 -26 0 -40 q-14 14 0 40z\" fill=\"#7FB0F2\"/><path d=\"M110 400 q14 -26 0 -40 q-14 14 0 40z\" fill=\"#7FB0F2\"/><path d=\"M640 150 q14 -26 0 -40 q-14 14 0 40z\" fill=\"#7FB0F2\"/><path d=\"M620 380 q14 -26 0 -40 q-14 14 0 40z\" fill=\"#7FB0F2\"/><line x1=\"110\" y1=\"150\" x2=\"184\" y2=\"183\" stroke=\"#7FB0F2\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"200,190 188,174 180,192\" fill=\"#7FB0F2\"/><line x1=\"140\" y1=\"380\" x2=\"200\" y2=\"340\" stroke=\"#7FB0F2\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"215,330 195,332 206,348\" fill=\"#7FB0F2\"/><line x1=\"610\" y1=\"170\" x2=\"537\" y2=\"194\" stroke=\"#7FB0F2\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"520,200 540,204 534,185\" fill=\"#7FB0F2\"/><line x1=\"590\" y1=\"370\" x2=\"521\" y2=\"329\" stroke=\"#7FB0F2\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"505,320 515,338 526,321\" fill=\"#7FB0F2\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied cells in detail. We start with salted cucumbers, build up the idea of diffusion, and finish with why vegetables stay crisp and why hospitals use saline."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Why does salted cucumber get watery?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 2.7s6.5 7 6.5 11.8a6.5 6.5 0 0 1-13 0C5.5 9.7 12 2.7 12 2.7z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Salt on cucumber</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Ten minutes later, <b style=\"color:#18262B\">water pools on the plate</b> and the slices go limp.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M11 20A7 7 0 0 1 4 13c0-6 6-9 16-10-1 10-4 16-10 16zM4 21c3-5 7-8 11-10\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Water on lettuce</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Stores spray vegetables so they stay <b style=\"color:#18262B\">crisp and firm</b>.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">In both cases, water is moving <b style=\"color:#B4521F\">in or out of the vegetable’s cells</b>.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 2</p>\n\n</section>", "note": "Demo: at the start of class, sprinkle salt on cucumber slices and leave them on a plate. Show the water at the end of this slide. Ask: did the water come from the salt, the air, or inside the cucumber?"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Explain diffusion</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Say why particles spread out.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M12 2.7s6.5 7 6.5 11.8a6.5 6.5 0 0 1-13 0C5.5 9.7 12 2.7 12 2.7z\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Predict osmosis</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Tell which way water will move.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 20A7 7 0 0 1 4 13c0-6 6-9 16-10-1 10-4 16-10 16zM4 21c3-5 7-8 11-10\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Explain everyday cases</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Crisp vegetables, saline drips.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 3</p>\n\n</section>", "note": "The goals match the three parts: diffusion, the osmosis rule, and what osmosis does to plant and animal cells."}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BEFORE YOU START</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Four words you need first</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Cell membrane</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">The thin skin around a cell. Water passes through; salt hardly does.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Concentration</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">How much stuff (like salt) is in a set amount of water.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Diffusion</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Particles spreading from <b style=\"color:#18262B\">crowded to less crowded</b>.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Osmosis</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Diffusion of <b style=\"color:#18262B\">water</b> across a membrane.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 4</p>\n\n</section>", "note": "Point out that osmosis is a special case of diffusion: same idea, but only water is moving."}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"Diffusion\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">DIFFUSION</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Particles spread out until they’re even</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Left: orange particles crowded at one side of a tank of water. Right: later, the particles are spread evenly through the tank\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"20\" y=\"50\" width=\"260\" height=\"270\" rx=\"18\" fill=\"#E1ECFA\" stroke=\"#18262B\" stroke-width=\"5\"/><circle cx=\"40\" cy=\"80\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"63\" cy=\"121\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"86\" cy=\"162\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"109\" cy=\"203\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"42\" cy=\"244\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"65\" cy=\"285\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"88\" cy=\"106\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"111\" cy=\"147\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"44\" cy=\"188\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"67\" cy=\"229\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"90\" cy=\"270\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"113\" cy=\"91\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"46\" cy=\"132\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"69\" cy=\"173\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"92\" cy=\"214\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"115\" cy=\"255\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"48\" cy=\"296\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"71\" cy=\"117\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"94\" cy=\"158\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"117\" cy=\"199\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"50\" cy=\"240\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"73\" cy=\"281\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"96\" cy=\"102\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"119\" cy=\"143\" r=\"9\" fill=\"#B4521F\"/><rect x=\"340\" y=\"50\" width=\"280\" height=\"270\" rx=\"18\" fill=\"#E1ECFA\" stroke=\"#18262B\" stroke-width=\"5\"/><circle cx=\"350\" cy=\"70\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"411\" cy=\"117\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"472\" cy=\"164\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"533\" cy=\"211\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"594\" cy=\"258\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"405\" cy=\"75\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"466\" cy=\"122\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"527\" cy=\"169\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"588\" cy=\"216\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"399\" cy=\"263\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"460\" cy=\"80\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"521\" cy=\"127\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"582\" cy=\"174\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"393\" cy=\"221\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"454\" cy=\"268\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"515\" cy=\"85\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"576\" cy=\"132\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"387\" cy=\"179\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"448\" cy=\"226\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"509\" cy=\"273\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"570\" cy=\"90\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"381\" cy=\"137\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"442\" cy=\"184\" r=\"9\" fill=\"#B4521F\"/><circle cx=\"503\" cy=\"231\" r=\"9\" fill=\"#B4521F\"/><line x1=\"150\" y1=\"185\" x2=\"244\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"260,185 244,176 244,194\" fill=\"#4F5F64\"/><text x=\"150\" y=\"30\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Start</text><text x=\"480\" y=\"30\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Later</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">A drop of food coloring in still water.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">Particles are always jiggling and bumping.</p>\n<p style=\"font-size:34px;line-height:1.5\">Over time they move from where they’re <b>crowded</b> (high concentration) to where they’re <b>spread out</b> (low concentration).</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">No push needed: diffusion just happens.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 5</p>\n\n</section>", "note": "Quick demo: one drop of food coloring in a clear cup of still water, or spray air freshener at the front of the room and ask students to raise a hand when they smell it."}, {"id": "figure", "html": "<section id=\"figure\" data-section=\"The osmosis rule\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">OSMOSIS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Which way does the water go?</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"Three cells: in pure water, arrows point in and the cell swells; in water as salty as the cell, no change; in salt water, arrows point out and the cell shrinks\" width=\"1500\" height=\"360\" viewBox=\"0 0 1500 360\">\n<rect x=\"20\" y=\"10\" width=\"420\" height=\"250\" rx=\"20\" fill=\"#E1ECFA\"/><circle cx=\"230\" cy=\"135\" r=\"80\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"6\"/><circle cx=\"202\" cy=\"111\" r=\"7\" fill=\"#18262B\"/><circle cx=\"254\" cy=\"115\" r=\"7\" fill=\"#18262B\"/><circle cx=\"230\" cy=\"139\" r=\"7\" fill=\"#18262B\"/><line x1=\"90\" y1=\"135\" x2=\"120\" y2=\"135\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"138,135 120,125 120,145\" fill=\"#2463B8\"/><line x1=\"370\" y1=\"135\" x2=\"340\" y2=\"135\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"322,135 340,145 340,125\" fill=\"#2463B8\"/><line x1=\"230\" y1=\"15\" x2=\"230\" y2=\"27\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"230,45 240,27 220,27\" fill=\"#2463B8\"/><line x1=\"230\" y1=\"255\" x2=\"230\" y2=\"243\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"230,225 220,243 240,243\" fill=\"#2463B8\"/><text x=\"230\" y=\"300\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">Pure water</text><text x=\"230\" y=\"340\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">water moves in → swells</text><rect x=\"540\" y=\"10\" width=\"420\" height=\"250\" rx=\"20\" fill=\"#E1ECFA\"/><circle cx=\"580\" cy=\"40\" r=\"7\" fill=\"#18262B\"/><circle cx=\"677\" cy=\"99\" r=\"7\" fill=\"#18262B\"/><circle cx=\"774\" cy=\"158\" r=\"7\" fill=\"#18262B\"/><circle cx=\"750\" cy=\"135\" r=\"62\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"6\"/><circle cx=\"728\" cy=\"116\" r=\"7\" fill=\"#18262B\"/><circle cx=\"769\" cy=\"120\" r=\"7\" fill=\"#18262B\"/><circle cx=\"750\" cy=\"138\" r=\"7\" fill=\"#18262B\"/><text x=\"750\" y=\"300\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">Same saltiness</text><text x=\"750\" y=\"340\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">no net change</text><rect x=\"1060\" y=\"10\" width=\"420\" height=\"250\" rx=\"20\" fill=\"#E1ECFA\"/><circle cx=\"1100\" cy=\"40\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1197\" cy=\"99\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1294\" cy=\"158\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1391\" cy=\"217\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1148\" cy=\"86\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1245\" cy=\"145\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1342\" cy=\"204\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1439\" cy=\"73\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1196\" cy=\"132\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1293\" cy=\"191\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1390\" cy=\"60\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1147\" cy=\"119\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1270\" cy=\"135\" r=\"46\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"6\"/><circle cx=\"1254\" cy=\"121\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1284\" cy=\"124\" r=\"7\" fill=\"#18262B\"/><circle cx=\"1270\" cy=\"137\" r=\"7\" fill=\"#18262B\"/><line x1=\"1214\" y1=\"135\" x2=\"1184\" y2=\"135\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1166,135 1184,145 1184,125\" fill=\"#2463B8\"/><line x1=\"1326\" y1=\"135\" x2=\"1356\" y2=\"135\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1374,135 1356,125 1356,145\" fill=\"#2463B8\"/><line x1=\"1270\" y1=\"81\" x2=\"1270\" y2=\"69\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1270,51 1260,69 1280,69\" fill=\"#2463B8\"/><line x1=\"1270\" y1=\"189\" x2=\"1270\" y2=\"201\" stroke=\"#2463B8\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"1270,219 1280,201 1260,201\" fill=\"#2463B8\"/><text x=\"1270\" y=\"300\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#18262B\">Salt water</text><text x=\"1270\" y=\"340\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">water moves out → shrinks</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Black dots = salt. Blue arrows = which way water moves.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Pure water</b> outside: the cell is saltier, so water moves <b>in</b>.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Same saltiness</b>: water moves both ways equally, so nothing changes.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>Salt water</b> outside: the outside is saltier, so water moves <b>out</b>.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 6</p>\n\n</section>", "note": "Draw one cell on the board and add salt dots inside and outside; ask students to predict the arrows before revealing."}, {"id": "rule", "html": "<section id=\"rule\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">THE RULE</p>\n<p style=\"font-size:96px;font-weight:900;line-height:1.2\">Water moves toward<br>the saltier side.</p>\n<p style=\"font-size:36px;line-height:1.5;color:#BFCDC9\">The membrane lets water through, but salt can’t easily cross. So the water does the moving.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Cells: Osmosis · 7</p>\n\n</section>", "note": "Back to the hook: the salt was on the outside of the cucumber, so water left the cucumber’s cells and pooled on the plate."}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">TRY THE NUMBERS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Potato strips after 40 minutes</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"Three potato strips: the starting strip is 5.0 cm, the one from plain water is 5.3 cm, the one from strong salt water is 4.6 cm\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<rect x=\"200\" y=\"70\" width=\"350\" height=\"44\" rx=\"10\" fill=\"#E8D9A8\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"180\" y=\"102\" text-anchor=\"end\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Start</text><text x=\"562.0\" y=\"102\" text-anchor=\"start\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">5.0 cm</text><rect x=\"200\" y=\"170\" width=\"371\" height=\"44\" rx=\"10\" fill=\"#F2E3B0\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"180\" y=\"202\" text-anchor=\"end\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Plain water</text><text x=\"583.0\" y=\"202\" text-anchor=\"start\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">5.3 cm</text><rect x=\"200\" y=\"270\" width=\"322\" height=\"44\" rx=\"10\" fill=\"#D4C08A\" stroke=\"#18262B\" stroke-width=\"3\"/><text x=\"180\" y=\"302\" text-anchor=\"end\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Strong salt</text><text x=\"534.0\" y=\"302\" text-anchor=\"start\" font-size=\"26\" font-weight=\"700\" fill=\"#4F5F64\">4.6 cm</text><line x1=\"550\" y1=\"50\" x2=\"550\" y2=\"330\" stroke=\"#B4521F\" stroke-width=\"3\" stroke-dasharray=\"8 8\"/>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">Soaked in</th><th style=\"width:60%;text-align:left\">Result</th></tr>\n<tr><td>Plain water</td><td><b>5.3 cm, firm: gained water</b></td></tr>\n<tr><td>Weak salt water</td><td><b>5.0 cm, no change</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td>Strong salt water</td><td><b>4.6 cm, soft: lost water</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Longer and firmer = gained water. Shorter and floppy = lost water.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 8</p>\n\n</section>", "note": "Typical results; yours will vary. Optional lab: soak equal potato strips for at least 40 minutes before class (3 in plain water, 3 in 10% salt water), then have pairs measure and bend them. A 15-minute soak in class will not show a difference."}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ANIMAL VS. PLANT CELLS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Too much water can burst a red blood cell</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Three red blood cells: swollen and bursting in pure water, normal in saline, shriveled in salty water\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<ellipse cx=\"110\" cy=\"170\" rx=\"82\" ry=\"82\" fill=\"#D84B4B\"/><line x1=\"180\" y1=\"120\" x2=\"215\" y2=\"95\" stroke=\"#D84B4B\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"40\" y1=\"120\" x2=\"5\" y2=\"95\" stroke=\"#D84B4B\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"190\" y1=\"210\" x2=\"230\" y2=\"230\" stroke=\"#D84B4B\" stroke-width=\"5\" stroke-linecap=\"round\"/><line x1=\"30\" y1=\"210\" x2=\"-10\" y2=\"230\" stroke=\"#D84B4B\" stroke-width=\"5\" stroke-linecap=\"round\"/><ellipse cx=\"320\" cy=\"170\" rx=\"75\" ry=\"52\" fill=\"#D84B4B\"/><ellipse cx=\"320\" cy=\"170\" rx=\"34\" ry=\"21\" fill=\"#B83232\"/><path d=\"M500 140 q20 -20 40 0 q20 20 40 0 q-10 40 -40 50 q-30 -10 -40 -50z\" fill=\"#D84B4B\"/><text x=\"110\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Pure water</text><text x=\"110\" y=\"334\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"#4F5F64\">swells, may burst</text><text x=\"320\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Saline</text><text x=\"320\" y=\"334\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"#4F5F64\">stays normal</text><text x=\"540\" y=\"300\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"800\" fill=\"#18262B\">Salty water</text><text x=\"540\" y=\"334\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"#4F5F64\">shrivels</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Red blood cells in three liquids.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\"><b>Animal cells</b> have only a thin membrane, so too much water can make them burst.</p>\n<p style=\"font-size:34px;line-height:1.5\"><b>Plant cells</b> have a stiff cell wall, so they get firm instead of bursting. That’s why sprayed lettuce is crisp.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">That’s why IV drips use saline (salt water), never pure water.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 9</p>\n\n</section>", "note": "Saline is about 0.9% salt, the same saltiness as blood, so water moves in and out equally."}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ONE TABLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Diffusion vs. osmosis</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">Compare</th><th style=\"width:33%;text-align:left\">Diffusion</th><th style=\"width:33%;text-align:left\">Osmosis</th></tr>\n<tr><td>What moves</td><td>Any particles</td><td>Only water</td></tr>\n<tr><td>Needs a membrane?</td><td>No</td><td>Yes</td></tr>\n<tr><td>Direction</td><td>Crowded → less crowded</td><td>Toward the saltier side</td></tr>\n<tr><td>Example</td><td>Perfume spreading in a room</td><td>Salted cucumber going limp</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">Remember:</b> osmosis is diffusion of water through a membrane.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 10</p>\n\n</section>", "note": "Ask students to add one more example to each column."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.1\">A cell with 1% salt is placed in 5% salt water. What happens?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Compare</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">in 1%<br>out 5%</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Saltier side</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">outside</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Water moves</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">out</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">Result</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">cell shrinks</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Water leaves, so the cell <span style=\"color:#2463B8\">shrinks</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 11</p>\n\n</section>", "note": "Students often stop at “the outside is saltier.” Push them to finish the chain: so water moves out, so the cell shrinks."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Does the salt move into the cell?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">The membrane lets <b>water</b> through easily, but salt hardly crosses. The salt stays put; the <b>water</b> is what moves.</p>\n<p style=\"font-size:34px;line-height:1.5\">That’s why salted cucumber gets watery instead of salty inside: water comes <b>out</b> to the salt.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Cells: Osmosis · 12</p>\n\n</section>", "note": "Students read “more salt” as “the salt moves.” Close it with one line: the salt stays; the water travels."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">A red blood cell is put in pure water. Which way does water move, and what happens?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">Why do grocery stores spray water on fresh vegetables?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">True or false: in osmosis, salt moves across the membrane.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Cells: Osmosis · 13</p>\n\n</section>", "note": "Let students answer on their own first. For Q1, remind them to find the saltier side."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">In; it swells</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">The cell is saltier, so it may even burst.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">To keep them crisp</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Water moves into the cells and makes them firm.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">False</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Water moves; the salt stays put.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Water moves toward the saltier side.<br><span style=\"color:#E58A55\">The salt stays; the water travels.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Cells: Osmosis · 14</p>\n\n</section>", "note": "Optional sentence frames: “The water moves ___ the cell because the concentration outside is ___.” “The strip in ___ became ___ because it ___ water.”"}]}, "bio-genetics-zh": {"title": "遺傳：顯性與隱性", "lang": "zh", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">生物</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">顯性<br>與隱性</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">為什麼孩子有時會出現<br>爸媽都沒有的特徵？</p>\n</div>\n<svg aria-label=\"兩朵紫色豌豆花雜交，生出四個後代：三朵紫色、一朵白色，旁邊是一個 2×2 方格\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<circle cx=\"170\" cy=\"98\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"220\" cy=\"134\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"202\" cy=\"193\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"138\" cy=\"193\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"120\" cy=\"134\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"170\" cy=\"150\" r=\"24\" fill=\"#E0B020\"/><circle cx=\"400\" cy=\"98\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"450\" cy=\"134\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"432\" cy=\"193\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"368\" cy=\"193\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"350\" cy=\"134\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"400\" cy=\"150\" r=\"24\" fill=\"#E0B020\"/><text x=\"285\" y=\"170\" text-anchor=\"middle\" font-size=\"56\" font-weight=\"900\" fill=\"#BFCDC9\">×</text><line x1=\"285\" y1=\"250\" x2=\"285\" y2=\"300\" stroke=\"#BFCDC9\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"285,320 296,300 274,300\" fill=\"#BFCDC9\"/><circle cx=\"120\" cy=\"364\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"155\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"142\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"98\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"85\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"120\" cy=\"400\" r=\"17\" fill=\"#E0B020\"/><circle cx=\"240\" cy=\"364\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"275\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"262\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"218\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"205\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"240\" cy=\"400\" r=\"17\" fill=\"#E0B020\"/><circle cx=\"360\" cy=\"364\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"395\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"382\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"338\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"325\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"360\" cy=\"400\" r=\"17\" fill=\"#E0B020\"/><circle cx=\"480\" cy=\"364\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"515\" cy=\"389\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"502\" cy=\"430\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"458\" cy=\"430\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"445\" cy=\"389\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"480\" cy=\"400\" r=\"17\" fill=\"#E0B020\"/><rect x=\"560\" y=\"60\" width=\"140\" height=\"140\" rx=\"12\" fill=\"none\" stroke=\"#E58A55\" stroke-width=\"5\"/><line x1=\"630\" y1=\"60\" x2=\"630\" y2=\"200\" stroke=\"#E58A55\" stroke-width=\"4\"/><line x1=\"560\" y1=\"130\" x2=\"700\" y2=\"130\" stroke=\"#E58A55\" stroke-width=\"4\"/>\n</svg>\n\n</section>", "note": "這一課給完全沒學過遺傳的同學。我們跟著孟德爾的豌豆走：一個藏起來的基因、一個簡單的方格，以及從中算出來的比例。"}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">兩朵紫花，能生出白花嗎？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M11 20A7 7 0 0 1 4 13c0-6 6-9 16-10-1 10-4 16-10 16zM4 21c3-5 7-8 11-10\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">親代</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">兩株豌豆都開<b style=\"color:#18262B\">紫色</b>的花。</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">後代</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">大約<b style=\"color:#18262B\">每 4 株就有 1 株</b>開白花。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">白色其實<b style=\"color:#B4521F\">一直藏在紫花親代裡</b>。來看看是怎麼回事。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 2</p>\n\n</section>", "note": "揭曉前先投票。避免用單雙眼皮或捲舌當例子，它們由多個基因控制，不是單純的顯隱性。"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">看懂 A 和 a</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">分辨顯性和隱性。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">畫棋盤方格</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">把親代各一個字母組合起來。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">算出比例</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">算出 1 : 2 : 1 和 3 : 1。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 3</p>\n\n</section>", "note": "三個目標對應三段：字母代表什麼、方格怎麼填、比例告訴我們什麼。"}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">開始之前</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先認識四個詞</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">基因</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">控制一個性狀（例如花色）的指令。每個生物有<b style=\"color:#18262B\">兩份</b>，爸媽各給一份。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">顯性（A）</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">只要有<b style=\"color:#18262B\">一份</b>就會表現出來。用大寫字母表示。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">隱性（a）</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">要有<b style=\"color:#18262B\">兩份</b>（aa）才會表現出來。用小寫字母表示。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">基因型／表現型</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">字母組合（Aa）／看得到的性狀（紫色）。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 4</p>\n\n</section>", "note": "強調寫法：大寫是顯性，同一個字母的小寫是隱性。基因型是寫出來的，表現型是看得到的。"}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"基因怎麼傳下去\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">基因怎麼傳下去</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">親代各傳一個字母給後代</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"母本和父本都是 Aa，各自分成 A 或 a；後代從雙方各拿到一個字母\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"20\" y=\"40\" width=\"200\" height=\"80\" rx=\"18\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"120\" y=\"94\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">Aa</text><text x=\"120\" y=\"30\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#4F5F64\">母本</text><line x1=\"90\" y1=\"124\" x2=\"66\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"60,200 74,188 58,182\" fill=\"#4F5F64\"/><line x1=\"150\" y1=\"124\" x2=\"174\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"180,200 182,182 166,188\" fill=\"#4F5F64\"/><circle cx=\"60\" cy=\"230\" r=\"30\" fill=\"#B4521F\"/><text x=\"60\" y=\"241\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#FFFFFF\">A</text><circle cx=\"180\" cy=\"230\" r=\"30\" fill=\"#2463B8\"/><text x=\"180\" y=\"241\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#FFFFFF\">a</text><rect x=\"420\" y=\"40\" width=\"200\" height=\"80\" rx=\"18\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"520\" y=\"94\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">Aa</text><text x=\"520\" y=\"30\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#4F5F64\">父本</text><line x1=\"490\" y1=\"124\" x2=\"466\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"460,200 474,188 458,182\" fill=\"#4F5F64\"/><line x1=\"550\" y1=\"124\" x2=\"574\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"580,200 582,182 566,188\" fill=\"#4F5F64\"/><circle cx=\"460\" cy=\"230\" r=\"30\" fill=\"#B4521F\"/><text x=\"460\" y=\"241\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#FFFFFF\">A</text><circle cx=\"580\" cy=\"230\" r=\"30\" fill=\"#2463B8\"/><text x=\"580\" y=\"241\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#FFFFFF\">a</text><line x1=\"220\" y1=\"290\" x2=\"276\" y2=\"322\" stroke=\"#B4521F\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"290,330 280,314 272,330\" fill=\"#B4521F\"/><line x1=\"420\" y1=\"290\" x2=\"364\" y2=\"322\" stroke=\"#B4521F\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"350,330 368,330 360,314\" fill=\"#B4521F\"/><rect x=\"250\" y=\"320\" width=\"140\" height=\"56\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"320\" y=\"358\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">A 或 a</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">親代都是 Aa，各自有一半機會傳 A、一半機會傳 a。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">親代有兩個字母，但只會傳<b>一個</b>下去。</p>\n<p style=\"font-size:34px;line-height:1.5\">傳哪一個完全靠機率，就像擲硬幣。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">後代 = 媽媽的一個字母 + 爸爸的一個字母。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 5</p>\n\n</section>", "note": "只帶一個字母的細胞叫做配子（卵和精子，植物則是胚珠和花粉）。這個名詞在這個階段可以不教。"}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">棋盤方格</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">一個 2 × 2 方格列出所有可能的後代</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Aa × Aa 的棋盤方格：AA 紫、Aa 紫、Aa 紫、aa 白\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"150\" y=\"10\" width=\"220\" height=\"60\" rx=\"12\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"260\" y=\"52\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">A</text><rect x=\"380\" y=\"10\" width=\"220\" height=\"60\" rx=\"12\" fill=\"#E1ECFA\" stroke=\"#E1ECFA\" stroke-width=\"3\"/><text x=\"490\" y=\"52\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">a</text><rect x=\"20\" y=\"80\" width=\"120\" height=\"140\" rx=\"12\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"80\" y=\"162\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">A</text><rect x=\"20\" y=\"230\" width=\"120\" height=\"140\" rx=\"12\" fill=\"#E1ECFA\" stroke=\"#E1ECFA\" stroke-width=\"3\"/><text x=\"80\" y=\"312\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">a</text><rect x=\"150\" y=\"80\" width=\"220\" height=\"140\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><circle cx=\"210\" cy=\"128\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"232\" cy=\"143\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"224\" cy=\"169\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"196\" cy=\"169\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"188\" cy=\"143\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"210\" cy=\"150\" r=\"10\" fill=\"#E0B020\"/><text x=\"305\" y=\"164\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">AA</text><rect x=\"380\" y=\"80\" width=\"220\" height=\"140\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><circle cx=\"440\" cy=\"128\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"462\" cy=\"143\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"454\" cy=\"169\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"426\" cy=\"169\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"418\" cy=\"143\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"440\" cy=\"150\" r=\"10\" fill=\"#E0B020\"/><text x=\"535\" y=\"164\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">Aa</text><rect x=\"150\" y=\"230\" width=\"220\" height=\"140\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><circle cx=\"210\" cy=\"278\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"232\" cy=\"293\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"224\" cy=\"319\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"196\" cy=\"319\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"188\" cy=\"293\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"210\" cy=\"300\" r=\"10\" fill=\"#E0B020\"/><text x=\"305\" y=\"314\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">Aa</text><rect x=\"380\" y=\"230\" width=\"220\" height=\"140\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"5\"/><circle cx=\"440\" cy=\"278\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"462\" cy=\"293\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"454\" cy=\"319\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"426\" cy=\"319\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"418\" cy=\"293\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"440\" cy=\"300\" r=\"10\" fill=\"#E0B020\"/><text x=\"535\" y=\"314\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">aa</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Aa × Aa</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">母本的字母寫在上方，父本的寫在左側。</p>\n<p style=\"font-size:34px;line-height:1.5\">每一格填入上方一個字母和左側一個字母。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">只有 <b>aa</b> 會表現白色的隱性性狀。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 6</p>\n\n</section>", "note": "回到開場：是的，兩株 Aa 紫花親代可以生出 aa 白花，每次的機率是 4 分之 1。"}, {"id": "formula", "html": "<section id=\"formula\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">比例</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">AA</p>\n<p style=\"font-size:32px;color:#BFCDC9\">1</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">:</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#7FB0F2\">Aa</p>\n<p style=\"font-size:32px;color:#BFCDC9\">2</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">:</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#F3F5F2\">aa</p>\n<p style=\"font-size:32px;color:#BFCDC9\">1</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:700;line-height:1.4\">紫花 : 白花 = 3 : 1</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">基因型比例 1 : 2 : 1。表現型比例 3 : 1，因為 AA 和 Aa 看起來都是紫色。開白花的機率 = 4 分之 1 = 25%。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">遺傳：顯性與隱性 · 7</p>\n\n</section>", "note": "孟德爾數了 705 株紫花和 224 株白花：大約 3 比 1。"}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">用硬幣試試看</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">擲兩枚硬幣，模擬兩個親代</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"全班擲 400 次的長條圖：AA 104、Aa 196、aa 100，都接近預期的 100、200、100\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<line x1=\"60\" y1=\"330\" x2=\"700\" y2=\"330\" stroke=\"#4F5F64\" stroke-width=\"4\"/><rect x=\"100\" y=\"226\" width=\"70\" height=\"104\" rx=\"8\" fill=\"#B4521F\"/><rect x=\"180\" y=\"230\" width=\"70\" height=\"100\" rx=\"8\" fill=\"#D3DCD8\"/><text x=\"175\" y=\"372\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">AA</text><rect x=\"310\" y=\"134\" width=\"70\" height=\"196\" rx=\"8\" fill=\"#B4521F\"/><rect x=\"390\" y=\"130\" width=\"70\" height=\"200\" rx=\"8\" fill=\"#D3DCD8\"/><text x=\"385\" y=\"372\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">Aa</text><rect x=\"520\" y=\"230\" width=\"70\" height=\"100\" rx=\"8\" fill=\"#B4521F\"/><rect x=\"600\" y=\"230\" width=\"70\" height=\"100\" rx=\"8\" fill=\"#D3DCD8\"/><text x=\"595\" y=\"372\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">aa</text><rect x=\"440\" y=\"20\" width=\"24\" height=\"24\" rx=\"4\" fill=\"#B4521F\"/><text x=\"474\" y=\"40\" text-anchor=\"start\" font-size=\"22\" font-weight=\"700\" fill=\"#18262B\">全班結果</text><rect x=\"440\" y=\"56\" width=\"24\" height=\"24\" rx=\"4\" fill=\"#D3DCD8\"/><text x=\"474\" y=\"76\" text-anchor=\"start\" font-size=\"22\" font-weight=\"700\" fill=\"#18262B\">預期</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">組合</th><th style=\"width:60%;text-align:left\">全班結果（400 次）</th></tr>\n<tr><td>AA</td><td><b>104（預期 100）</b></td></tr>\n<tr><td>Aa</td><td><b>196（預期 200）</b></td></tr>\n<tr><td>aa</td><td><b>100（預期 100）</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">正面 = A，反面 = a。擲幾次可能差很多，擲很多次就會接近 1 : 2 : 1。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 8</p>\n\n</section>", "note": "可選活動：兩人一組，擲兩枚貼了標籤的硬幣 20 次，記錄 AA、Aa、aa 的次數，再把全班結果加總寫在黑板上。提醒學生 A + a 和 a + A 都算 Aa。這裡的數字是一個示範班級的結果。"}, {"id": "concept3", "html": "<section id=\"concept3\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">藏起來的基因</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看起來一樣，字母卻不同</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"兩朵看起來一模一樣的紫花；一朵是 AA，另一朵是 Aa，藏著白色基因\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<circle cx=\"140\" cy=\"88\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"190\" cy=\"124\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"172\" cy=\"183\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"108\" cy=\"183\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"90\" cy=\"124\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"140\" cy=\"140\" r=\"24\" fill=\"#E0B020\"/><circle cx=\"480\" cy=\"88\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"530\" cy=\"124\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"512\" cy=\"183\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"448\" cy=\"183\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"430\" cy=\"124\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"480\" cy=\"140\" r=\"24\" fill=\"#E0B020\"/><rect x=\"70\" y=\"250\" width=\"140\" height=\"64\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"140\" y=\"295\" text-anchor=\"middle\" font-size=\"36\" font-weight=\"900\" fill=\"#18262B\">AA</text><rect x=\"410\" y=\"250\" width=\"140\" height=\"64\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"480\" y=\"295\" text-anchor=\"middle\" font-size=\"36\" font-weight=\"900\" fill=\"#18262B\">Aa</text><text x=\"140\" y=\"350\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#4F5F64\">兩個紫色基因</text><text x=\"480\" y=\"350\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">藏著白色基因</text><text x=\"310\" y=\"160\" text-anchor=\"middle\" font-size=\"64\" font-weight=\"900\" fill=\"#4F5F64\">=</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">光用看的分不出來。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">AA 和 Aa 都是紫色：<b>表現型</b>相同，<b>基因型</b>不同。</p>\n<p style=\"font-size:34px;line-height:1.5\">Aa 植物是<b>帶因者</b>：它藏著白色基因，還能傳給後代。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">想知道的話，讓它和白花（aa）雜交，看看會不會出現白花。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 9</p>\n\n</section>", "note": "這叫做試交。紫花親代如果是 AA，後代全是紫花；如果是 Aa，大約一半會是白花。"}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一張表看懂</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">基因型和表現型，差在哪裡？</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">比較</th><th style=\"width:33%;text-align:left\">基因型</th><th style=\"width:33%;text-align:left\">表現型</th></tr>\n<tr><td>是什麼</td><td>一對字母</td><td>看得到的性狀</td></tr>\n<tr><td>例子</td><td>AA, Aa, aa</td><td>紫色、白色</td></tr>\n<tr><td>看得到嗎？</td><td><span style=\"color:#B4521F\">看不到</span></td><td><span style=\"color:#2463B8\">看得到</span></td></tr>\n<tr><td>Aa × Aa 的比例</td><td>1 : 2 : 1</td><td>3 : 1</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">一句話記住：</b> 基因型是寫出來的，表現型是看得到的。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 10</p>\n\n</section>", "note": "問學生為什麼兩個比例的項數不同：因為 AA 和 Aa 合併成同一種表現型。"}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">例題</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">父本 Aa × 母本 aa：後代開白花（aa）的機率是多少？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">寫出字母</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">A、a<br>a、a</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">填方格</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">Aa Aa<br>aa aa</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">數 aa</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">4 格中 2 格</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">機率</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">2/4 = 1/2</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">開白花的機率 = <span style=\"color:#2463B8\">1/2（50%）</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 11</p>\n\n</section>", "note": "答 1/4 的學生可能直接套用了 Aa × Aa 的結果。堅持要他們先畫方格。"}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">已經生了 3 株紫花，第 4 株一定是白花嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">不一定。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">每個後代都是<b>新的機會</b>。不管前面生了什麼，每一株開白花的機率都是 4 分之 1。</p>\n<p style=\"font-size:34px;line-height:1.5\">就像擲硬幣：連續三次正面，第四次出現反面的機率也不會變大。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">遺傳：顯性與隱性 · 12</p>\n\n</section>", "note": "3 : 1 是後代很多時才會接近的比例，不是每四個就一定照這個比例。"}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:34px;line-height:1.5\">紫花 AA 和白花 aa 雜交，後代是什麼顏色？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:34px;line-height:1.5\">兩株 Aa 雜交，生出 aa 後代的機率是多少？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:34px;line-height:1.5\">是非題：兩株白花（aa）可以生出紫花後代。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">遺傳：顯性與隱性 · 13</p>\n\n</section>", "note": "先讓學生自己作答，每題都可以畫方格。"}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:700\">全是紫色</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">每個後代都是 Aa。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:700\">1/4 (25%)</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">四格中有一格是 aa。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:700\">錯</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">aa × aa 只會生出 aa。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">親代各給一個字母。<br><span style=\"color:#E58A55\">Aa × Aa 得到 1 : 2 : 1，也就是 3 紫 : 1 白。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">遺傳：顯性與隱性 · 14</p>\n\n</section>", "note": "可選出場單：「為什麼擲 20 次沒有剛好得到 1 : 2 : 1，全班合計卻比較接近？」（機率要在試驗次數很多時才會接近預期。）"}]}, "bio-genetics-en": {"title": "Genetics: Dominant & Recessive", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">BIOLOGY</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Dominant &amp;<br>Recessive</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">Why do children sometimes show a trait<br>neither parent has?</p>\n</div>\n<svg aria-label=\"Two purple pea flowers cross to make four offspring: three purple and one white, next to a two-by-two grid\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<circle cx=\"170\" cy=\"98\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"220\" cy=\"134\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"202\" cy=\"193\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"138\" cy=\"193\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"120\" cy=\"134\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"170\" cy=\"150\" r=\"24\" fill=\"#E0B020\"/><circle cx=\"400\" cy=\"98\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"450\" cy=\"134\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"432\" cy=\"193\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"368\" cy=\"193\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"350\" cy=\"134\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"400\" cy=\"150\" r=\"24\" fill=\"#E0B020\"/><text x=\"285\" y=\"170\" text-anchor=\"middle\" font-size=\"56\" font-weight=\"900\" fill=\"#BFCDC9\">×</text><line x1=\"285\" y1=\"250\" x2=\"285\" y2=\"300\" stroke=\"#BFCDC9\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"285,320 296,300 274,300\" fill=\"#BFCDC9\"/><circle cx=\"120\" cy=\"364\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"155\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"142\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"98\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"85\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"120\" cy=\"400\" r=\"17\" fill=\"#E0B020\"/><circle cx=\"240\" cy=\"364\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"275\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"262\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"218\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"205\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"240\" cy=\"400\" r=\"17\" fill=\"#E0B020\"/><circle cx=\"360\" cy=\"364\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"395\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"382\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"338\" cy=\"430\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"325\" cy=\"389\" r=\"30\" fill=\"#8E5BC2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"360\" cy=\"400\" r=\"17\" fill=\"#E0B020\"/><circle cx=\"480\" cy=\"364\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"515\" cy=\"389\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"502\" cy=\"430\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"458\" cy=\"430\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"445\" cy=\"389\" r=\"30\" fill=\"#F3F5F2\" stroke=\"#22343A\" stroke-width=\"3\"/><circle cx=\"480\" cy=\"400\" r=\"17\" fill=\"#E0B020\"/><rect x=\"560\" y=\"60\" width=\"140\" height=\"140\" rx=\"12\" fill=\"none\" stroke=\"#E58A55\" stroke-width=\"5\"/><line x1=\"630\" y1=\"60\" x2=\"630\" y2=\"200\" stroke=\"#E58A55\" stroke-width=\"4\"/><line x1=\"560\" y1=\"130\" x2=\"700\" y2=\"130\" stroke=\"#E58A55\" stroke-width=\"4\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied genetics. We follow Mendel’s pea plants: one hidden gene, a simple grid, and the ratios that come out of it."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Can two purple flowers have a white baby?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M11 20A7 7 0 0 1 4 13c0-6 6-9 16-10-1 10-4 16-10 16zM4 21c3-5 7-8 11-10\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">The parents</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Both pea plants have <b style=\"color:#18262B\">purple</b> flowers.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">The offspring</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">About <b style=\"color:#18262B\">1 in 4</b> seedlings grows white flowers.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">The white color was <b style=\"color:#B4521F\">hiding inside the purple parents</b>. Let’s find out how.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 2</p>\n\n</section>", "note": "Take a vote before revealing the answer. Avoid examples like eyelid folds or tongue rolling; they are controlled by several genes, not a simple dominant–recessive pair."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Read A and a</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Tell dominant from recessive.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M11 4a7 7 0 1 0 0 14 7 7 0 0 0 0-14zM21 21l-5-5\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Fill a Punnett square</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Combine one letter from each parent.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Find the ratios</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Get 1 : 2 : 1 and 3 : 1.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 3</p>\n\n</section>", "note": "The goals match the three parts: what the letters mean, how to fill the square, and what the ratios tell us."}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BEFORE YOU START</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Four words you need first</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Gene</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">An instruction for one trait, like flower color. You get <b style=\"color:#18262B\">two copies</b>, one from each parent.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Dominant (A)</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Shows up if you have <b style=\"color:#18262B\">at least one</b> copy. Written as a capital letter.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Recessive (a)</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Shows up only with <b style=\"color:#18262B\">two copies</b> (aa). Written in lowercase.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Genotype / phenotype</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">The letters (Aa) / the trait you can see (purple).</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 4</p>\n\n</section>", "note": "Stress the notation: a capital letter is dominant, the same letter in lowercase is recessive. Genotype is what you write; phenotype is what you see."}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"How genes are passed on\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">PASSING ON GENES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Each parent passes on one letter</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A mother and a father, both Aa, each split into an A or an a; the offspring gets one letter from each\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"20\" y=\"40\" width=\"200\" height=\"80\" rx=\"18\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"120\" y=\"94\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">Aa</text><text x=\"120\" y=\"30\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#4F5F64\">Mother</text><line x1=\"90\" y1=\"124\" x2=\"66\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"60,200 74,188 58,182\" fill=\"#4F5F64\"/><line x1=\"150\" y1=\"124\" x2=\"174\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"180,200 182,182 166,188\" fill=\"#4F5F64\"/><circle cx=\"60\" cy=\"230\" r=\"30\" fill=\"#B4521F\"/><text x=\"60\" y=\"241\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#FFFFFF\">A</text><circle cx=\"180\" cy=\"230\" r=\"30\" fill=\"#2463B8\"/><text x=\"180\" y=\"241\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#FFFFFF\">a</text><rect x=\"420\" y=\"40\" width=\"200\" height=\"80\" rx=\"18\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"520\" y=\"94\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">Aa</text><text x=\"520\" y=\"30\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#4F5F64\">Father</text><line x1=\"490\" y1=\"124\" x2=\"466\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"460,200 474,188 458,182\" fill=\"#4F5F64\"/><line x1=\"550\" y1=\"124\" x2=\"574\" y2=\"185\" stroke=\"#4F5F64\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"580,200 582,182 566,188\" fill=\"#4F5F64\"/><circle cx=\"460\" cy=\"230\" r=\"30\" fill=\"#B4521F\"/><text x=\"460\" y=\"241\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#FFFFFF\">A</text><circle cx=\"580\" cy=\"230\" r=\"30\" fill=\"#2463B8\"/><text x=\"580\" y=\"241\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"800\" fill=\"#FFFFFF\">a</text><line x1=\"220\" y1=\"290\" x2=\"276\" y2=\"322\" stroke=\"#B4521F\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"290,330 280,314 272,330\" fill=\"#B4521F\"/><line x1=\"420\" y1=\"290\" x2=\"364\" y2=\"322\" stroke=\"#B4521F\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"350,330 368,330 360,314\" fill=\"#B4521F\"/><rect x=\"250\" y=\"320\" width=\"140\" height=\"56\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"320\" y=\"358\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"800\" fill=\"#18262B\">A or a</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Each parent is Aa. Each passes on A or a, 50/50.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">A parent has two letters but passes on <b>only one</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">Which one is pure chance, like flipping a coin.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Offspring = one letter from mom + one from dad.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 5</p>\n\n</section>", "note": "The cells that carry one letter are called gametes (egg and sperm, or pollen and ovule in plants). The word is optional at this level."}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">THE PUNNETT SQUARE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">A 2 × 2 grid shows every possible offspring</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A Punnett square for Aa times Aa: AA purple, Aa purple, Aa purple, aa white\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"150\" y=\"10\" width=\"220\" height=\"60\" rx=\"12\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"260\" y=\"52\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">A</text><rect x=\"380\" y=\"10\" width=\"220\" height=\"60\" rx=\"12\" fill=\"#E1ECFA\" stroke=\"#E1ECFA\" stroke-width=\"3\"/><text x=\"490\" y=\"52\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">a</text><rect x=\"20\" y=\"80\" width=\"120\" height=\"140\" rx=\"12\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"80\" y=\"162\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">A</text><rect x=\"20\" y=\"230\" width=\"120\" height=\"140\" rx=\"12\" fill=\"#E1ECFA\" stroke=\"#E1ECFA\" stroke-width=\"3\"/><text x=\"80\" y=\"312\" text-anchor=\"middle\" font-size=\"34\" font-weight=\"900\" fill=\"#18262B\">a</text><rect x=\"150\" y=\"80\" width=\"220\" height=\"140\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><circle cx=\"210\" cy=\"128\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"232\" cy=\"143\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"224\" cy=\"169\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"196\" cy=\"169\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"188\" cy=\"143\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"210\" cy=\"150\" r=\"10\" fill=\"#E0B020\"/><text x=\"305\" y=\"164\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">AA</text><rect x=\"380\" y=\"80\" width=\"220\" height=\"140\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><circle cx=\"440\" cy=\"128\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"462\" cy=\"143\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"454\" cy=\"169\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"426\" cy=\"169\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"418\" cy=\"143\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"440\" cy=\"150\" r=\"10\" fill=\"#E0B020\"/><text x=\"535\" y=\"164\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">Aa</text><rect x=\"150\" y=\"230\" width=\"220\" height=\"140\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><circle cx=\"210\" cy=\"278\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"232\" cy=\"293\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"224\" cy=\"319\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"196\" cy=\"319\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"188\" cy=\"293\" r=\"19\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"210\" cy=\"300\" r=\"10\" fill=\"#E0B020\"/><text x=\"305\" y=\"314\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">Aa</text><rect x=\"380\" y=\"230\" width=\"220\" height=\"140\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"5\"/><circle cx=\"440\" cy=\"278\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"462\" cy=\"293\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"454\" cy=\"319\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"426\" cy=\"319\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"418\" cy=\"293\" r=\"19\" fill=\"#F3F5F2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"440\" cy=\"300\" r=\"10\" fill=\"#E0B020\"/><text x=\"535\" y=\"314\" text-anchor=\"middle\" font-size=\"40\" font-weight=\"900\" fill=\"#18262B\">aa</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Aa × Aa</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">Mother’s letters across the top, father’s down the side.</p>\n<p style=\"font-size:34px;line-height:1.5\">Fill each box with one letter from the top and one from the side.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Only <b>aa</b> shows the white, recessive trait.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 6</p>\n\n</section>", "note": "Back to the hook: yes, two purple Aa parents can have a white aa offspring, with a 1 in 4 chance each time."}, {"id": "formula", "html": "<section id=\"formula\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">THE RATIOS</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">AA</p>\n<p style=\"font-size:32px;color:#BFCDC9\">1</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">:</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#7FB0F2\">Aa</p>\n<p style=\"font-size:32px;color:#BFCDC9\">2</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">:</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#F3F5F2\">aa</p>\n<p style=\"font-size:32px;color:#BFCDC9\">1</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:800;line-height:1.4\">Purple : white = 3 : 1</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Genotype ratio 1 : 2 : 1. Phenotype ratio 3 : 1, because AA and Aa both look purple. Chance of white = 1 in 4 = 25%.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Genetics: Dominant &amp; Recessive · 7</p>\n\n</section>", "note": "Mendel counted 705 purple and 224 white plants: about 3 to 1."}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">TRY IT WITH COINS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Flip two coins to model two parents</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"Bar chart of a class’s 400 coin flips: AA 104, Aa 196, aa 100, each close to the expected 100, 200, 100\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<line x1=\"60\" y1=\"330\" x2=\"700\" y2=\"330\" stroke=\"#4F5F64\" stroke-width=\"4\"/><rect x=\"100\" y=\"226\" width=\"70\" height=\"104\" rx=\"8\" fill=\"#B4521F\"/><rect x=\"180\" y=\"230\" width=\"70\" height=\"100\" rx=\"8\" fill=\"#D3DCD8\"/><text x=\"175\" y=\"372\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">AA</text><rect x=\"310\" y=\"134\" width=\"70\" height=\"196\" rx=\"8\" fill=\"#B4521F\"/><rect x=\"390\" y=\"130\" width=\"70\" height=\"200\" rx=\"8\" fill=\"#D3DCD8\"/><text x=\"385\" y=\"372\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">Aa</text><rect x=\"520\" y=\"230\" width=\"70\" height=\"100\" rx=\"8\" fill=\"#B4521F\"/><rect x=\"600\" y=\"230\" width=\"70\" height=\"100\" rx=\"8\" fill=\"#D3DCD8\"/><text x=\"595\" y=\"372\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">aa</text><rect x=\"440\" y=\"20\" width=\"24\" height=\"24\" rx=\"4\" fill=\"#B4521F\"/><text x=\"474\" y=\"40\" text-anchor=\"start\" font-size=\"22\" font-weight=\"700\" fill=\"#18262B\">class result</text><rect x=\"440\" y=\"56\" width=\"24\" height=\"24\" rx=\"4\" fill=\"#D3DCD8\"/><text x=\"474\" y=\"76\" text-anchor=\"start\" font-size=\"22\" font-weight=\"700\" fill=\"#18262B\">expected</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">Pair</th><th style=\"width:60%;text-align:left\">Class result (400 flips)</th></tr>\n<tr><td>AA</td><td><b>104 (expected 100)</b></td></tr>\n<tr><td>Aa</td><td><b>196 (expected 200)</b></td></tr>\n<tr><td>aa</td><td><b>100 (expected 100)</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Heads = A, tails = a. A few flips can be lopsided; many flips get close to 1 : 2 : 1.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 8</p>\n\n</section>", "note": "Optional activity: pairs flip two labeled coins 20 times and tally AA, Aa and aa, then add up the class total on the board. Remind them that A + a and a + A both count as Aa. The numbers here are a sample class result."}, {"id": "concept3", "html": "<section id=\"concept3\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">HIDDEN GENES</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Same look, different letters</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Two purple flowers that look identical; one is AA and the other is Aa, carrying a hidden white gene\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<circle cx=\"140\" cy=\"88\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"190\" cy=\"124\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"172\" cy=\"183\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"108\" cy=\"183\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"90\" cy=\"124\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"140\" cy=\"140\" r=\"24\" fill=\"#E0B020\"/><circle cx=\"480\" cy=\"88\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"530\" cy=\"124\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"512\" cy=\"183\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"448\" cy=\"183\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"430\" cy=\"124\" r=\"43\" fill=\"#8E5BC2\" stroke=\"#18262B\" stroke-width=\"3\"/><circle cx=\"480\" cy=\"140\" r=\"24\" fill=\"#E0B020\"/><rect x=\"70\" y=\"250\" width=\"140\" height=\"64\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"140\" y=\"295\" text-anchor=\"middle\" font-size=\"36\" font-weight=\"900\" fill=\"#18262B\">AA</text><rect x=\"410\" y=\"250\" width=\"140\" height=\"64\" rx=\"14\" fill=\"#FBFCFA\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"480\" y=\"295\" text-anchor=\"middle\" font-size=\"36\" font-weight=\"900\" fill=\"#18262B\">Aa</text><text x=\"140\" y=\"350\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#4F5F64\">two purple genes</text><text x=\"480\" y=\"350\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"800\" fill=\"#B4521F\">white gene hiding</text><text x=\"310\" y=\"160\" text-anchor=\"middle\" font-size=\"64\" font-weight=\"900\" fill=\"#4F5F64\">=</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">You can’t tell them apart by looking.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">AA and Aa are both purple: same <b>phenotype</b>, different <b>genotype</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">An Aa plant is a <b>carrier</b>: it hides the white gene and can pass it on.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">To find out, cross it with a white (aa) plant and see if any white flowers appear.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 9</p>\n\n</section>", "note": "This is called a test cross. If the purple parent is AA, all offspring are purple; if it is Aa, about half are white."}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ONE TABLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Genotype vs. phenotype</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">Compare</th><th style=\"width:33%;text-align:left\">Genotype</th><th style=\"width:33%;text-align:left\">Phenotype</th></tr>\n<tr><td>What it is</td><td>The pair of letters</td><td>The trait you can see</td></tr>\n<tr><td>Example</td><td>AA, Aa, aa</td><td>Purple, white</td></tr>\n<tr><td>Can you see it?</td><td><span style=\"color:#B4521F\">No</span></td><td><span style=\"color:#2463B8\">Yes</span></td></tr>\n<tr><td>Ratio for Aa × Aa</td><td>1 : 2 : 1</td><td>3 : 1</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">Remember:</b> genotype is what you write; phenotype is what you see.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 10</p>\n\n</section>", "note": "Ask students why the two ratios have a different number of parts: AA and Aa merge into one phenotype."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.1\">Father Aa × mother aa: what is the chance of a white (aa) offspring?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Letters</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">A, a<br>a, a</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Fill square</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">Aa Aa<br>aa aa</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Count aa</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">2 of 4</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">Chance</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">2/4 = 1/2</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">Chance of white = <span style=\"color:#2463B8\">1/2 (50%)</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 11</p>\n\n</section>", "note": "Students who answer 1/4 probably reused the Aa × Aa result. Insist they draw the square first."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">After 3 purple plants, must the 4th be white?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">Every offspring is a <b>new chance</b>. Each one has its own 1 in 4 chance of being white, no matter what came before.</p>\n<p style=\"font-size:34px;line-height:1.5\">It’s like flipping a coin: three heads in a row doesn’t make the fourth flip more likely to be tails.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Genetics: Dominant &amp; Recessive · 12</p>\n\n</section>", "note": "A 3 : 1 ratio is what you approach over many offspring, not a guarantee for every group of four."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">A purple AA plant is crossed with a white aa plant. What color are the offspring?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">Two Aa plants are crossed. What is the chance of an aa offspring?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">True or false: two white (aa) plants can have a purple offspring.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Genetics: Dominant &amp; Recessive · 13</p>\n\n</section>", "note": "Let students answer on their own first, and let them draw a square for each."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">All purple</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Every offspring is Aa.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">1/4 (25%)</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">One box out of four is aa.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">False</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">aa × aa can only give aa.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">One letter from each parent.<br><span style=\"color:#E58A55\">Aa × Aa gives 1 : 2 : 1, or 3 purple : 1 white.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Genetics: Dominant &amp; Recessive · 14</p>\n\n</section>", "note": "Optional exit ticket: “Why didn’t 20 coin flips give exactly 1 : 2 : 1, while the class total came closer?” (Probability only gets close with many trials.)"}]}, "bio-ecology-zh": {"title": "生態：食物網與能量金字塔", "lang": "zh", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">生物</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">食物網與<br>能量金字塔</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">誰吃誰？能量去了哪裡？<br>從太陽一路追到狼。</p>\n</div>\n<svg aria-label=\"一座能量金字塔：底層是綠色的生產者，上面是橘色的各層，太陽照在上面\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<circle cx=\"610\" cy=\"90\" r=\"56\" fill=\"#FFC94D\"/><polygon points=\"360,70 230,200 490,200\" fill=\"#B4521F\"/><polygon points=\"230,210 490,210 590,330 130,330\" fill=\"#E58A55\"/><polygon points=\"130,340 590,340 690,460 30,460\" fill=\"#5B8C3A\"/><line x1=\"560\" y1=\"130\" x2=\"482\" y2=\"217\" stroke=\"#FFC94D\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"470,230 489,223 475,210\" fill=\"#FFC94D\"/>\n</svg>\n\n</section>", "note": "這一課給完全沒學過生態的同學。我們從黃石公園的真實故事開始，建立食物鏈和食物網的概念，最後學能量的 10% 規則。"}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">先想一個謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">狼被移除後，河邊的樹不見了。為什麼？</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 3 2 21h20L12 3zM12 10v5M12 18h.01\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">狼被移除</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">到 1920 年代，黃石公園的狼全被獵光了。<b style=\"color:#18262B\">麋鹿數量暴增。</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M11 20A7 7 0 0 1 4 13c0-6 6-9 16-10-1 10-4 16-10 16zM4 21c3-5 7-8 11-10\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700\">樹不見了</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">河岸邊的柳樹和白楊被<b style=\"color:#18262B\">啃到只剩樹樁</b>。</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">只拿走一種動物，整座公園都變了。<b style=\"color:#B4521F\">食物網</b>可以解釋為什麼。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 2</p>\n\n</section>", "note": "先讓學生兩人一組猜猜看。1995 年狼被重新引入黃石公園，河邊的樹開始恢復。"}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">學習目標</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">看完這份簡報，你會：</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">畫出食物鏈</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">箭頭方向畫對。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">看懂食物網</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">預測某種生物消失後會怎樣。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:700;line-height:1.2\">會用 10% 規則</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">算出每一層的能量。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 3</p>\n\n</section>", "note": "三個目標對應三段：食物鏈、食物網、能量金字塔。"}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">開始之前</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先認識四個詞</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">生產者</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">利用陽光自己製造養分，例如草和樹。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">消費者</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">吃其他生物來獲得能量，例如兔子和狼。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:700\">分解者</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">分解死去的生物，把養分還給土壤：細菌、真菌。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:700\">食物網</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">許多食物鏈連在一起，因為大多數動物不只吃一種東西。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 4</p>\n\n</section>", "note": "分解者常被忘記；提醒學生，食物網裡的每種生物死後都由分解者分解。"}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"食物鏈與食物網\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">食物鏈</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">箭頭跟著能量走</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"由上到下的食物鏈：太陽、草、兔子、狼，箭頭從前一個指向下一個\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"170\" y=\"20\" width=\"300\" height=\"66\" rx=\"16\" fill=\"#FFC94D\" stroke=\"#FFC94D\" stroke-width=\"3\"/><text x=\"320\" y=\"64\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">太陽</text><rect x=\"170\" y=\"112\" width=\"300\" height=\"66\" rx=\"16\" fill=\"#5B8C3A\" stroke=\"#5B8C3A\" stroke-width=\"3\"/><text x=\"320\" y=\"156\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#FFFFFF\">草</text><line x1=\"320\" y1=\"88\" x2=\"320\" y2=\"94\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"320,110 329,94 311,94\" fill=\"#4F5F64\"/><rect x=\"170\" y=\"204\" width=\"300\" height=\"66\" rx=\"16\" fill=\"#E58A55\" stroke=\"#E58A55\" stroke-width=\"3\"/><text x=\"320\" y=\"248\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">兔子</text><line x1=\"320\" y1=\"180\" x2=\"320\" y2=\"186\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"320,202 329,186 311,186\" fill=\"#4F5F64\"/><rect x=\"170\" y=\"296\" width=\"300\" height=\"66\" rx=\"16\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"320\" y=\"340\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#FFFFFF\">狼</text><line x1=\"320\" y1=\"272\" x2=\"320\" y2=\"278\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"320,294 329,278 311,278\" fill=\"#4F5F64\"/><text x=\"475\" y=\"220\" text-anchor=\"start\" font-size=\"24\" font-weight=\"800\" fill=\"#2463B8\">能量流向</text><line x1=\"540\" y1=\"250\" x2=\"540\" y2=\"314\" stroke=\"#2463B8\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"540,330 549,314 531,314\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">太陽 → 草 → 兔子 → 狼</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">能量從<b>太陽</b>開始，由生產者接住。</p>\n<p style=\"font-size:34px;line-height:1.5\">每個箭頭代表<b>「被……吃」</b>：草被兔子吃。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">箭頭從食物指向吃牠的生物。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 5</p>\n\n</section>", "note": "請學生把每個箭頭大聲讀成「被……吃」或「把能量給」。"}, {"id": "figure", "html": "<section id=\"figure\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">食物網</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">大多數動物不只吃一種東西</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"食物網：草被兔子、鹿、老鼠吃；兔子被狼和老鷹吃；鹿被狼吃；老鼠被老鷹和蛇吃；蛇被老鷹吃\" width=\"1500\" height=\"370\" viewBox=\"0 0 1500 370\">\n<line x1=\"714\" y1=\"300\" x2=\"439\" y2=\"235\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"426,232 437,243 441,228\" fill=\"#4F5F64\"/><line x1=\"760\" y1=\"300\" x2=\"760\" y2=\"246\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"760,232 752,246 768,246\" fill=\"#4F5F64\"/><line x1=\"806\" y1=\"300\" x2=\"1081\" y2=\"235\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"1094,232 1079,228 1083,243\" fill=\"#4F5F64\"/><line x1=\"392\" y1=\"170\" x2=\"458\" y2=\"111\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"468,102 452,106 463,117\" fill=\"#4F5F64\"/><line x1=\"442\" y1=\"170\" x2=\"824\" y2=\"104\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"838,102 822,97 825,112\" fill=\"#4F5F64\"/><line x1=\"726\" y1=\"170\" x2=\"527\" y2=\"106\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"514,102 525,114 529,99\" fill=\"#4F5F64\"/><line x1=\"1111\" y1=\"170\" x2=\"942\" y2=\"107\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"929,102 939,114 945,100\" fill=\"#4F5F64\"/><line x1=\"1152\" y1=\"170\" x2=\"1218\" y2=\"111\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"1228,102 1212,106 1223,117\" fill=\"#4F5F64\"/><line x1=\"1140\" y1=\"70\" x2=\"1016\" y2=\"70\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"1002,70 1016,78 1016,62\" fill=\"#4F5F64\"/><rect x=\"660\" y=\"300\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#5B8C3A\" stroke=\"#5B8C3A\" stroke-width=\"3\"/><text x=\"760\" y=\"340\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">草</text><rect x=\"280\" y=\"170\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"380\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">兔子</text><rect x=\"660\" y=\"170\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"760\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">鹿</text><rect x=\"1040\" y=\"170\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"1140\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">老鼠</text><rect x=\"1140\" y=\"40\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#E58A55\" stroke=\"#E58A55\" stroke-width=\"3\"/><text x=\"1240\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">蛇</text><rect x=\"800\" y=\"40\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"900\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">老鷹</text><rect x=\"380\" y=\"40\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"480\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">狼</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">每個箭頭都從食物指向吃牠的生物。</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\"><b>食物網</b>把許多條食物鏈連在一起。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">拿掉一種生物，影響會<b>擴散</b>到整張網。</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">連結越多的網越<b>穩定</b>：掠食者可以換別的食物吃。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 6</p>\n\n</section>", "note": "可選活動：八位同學拿角色卡（太陽、草、兔子、鹿、老鼠、蛇、老鷹、狼），把毛線從食物傳給吃牠的生物。老師說「狼不見了」，扮演狼的同學放手，問誰感覺到毛線鬆了。"}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">回到謎題</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">少了一個環節，整張網都會變</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"連鎖反應：狼減少、麋鹿增加、河邊的樹減少\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"120\" y=\"20\" width=\"280\" height=\"84\" rx=\"16\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"260\" y=\"74\" text-anchor=\"middle\" font-size=\"32\" font-weight=\"900\" fill=\"#18262B\">狼</text><text x=\"470\" y=\"82\" text-anchor=\"middle\" font-size=\"64\" font-weight=\"900\" fill=\"#B4521F\">↓</text><rect x=\"120\" y=\"140\" width=\"280\" height=\"84\" rx=\"16\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"260\" y=\"194\" text-anchor=\"middle\" font-size=\"32\" font-weight=\"900\" fill=\"#18262B\">麋鹿</text><text x=\"470\" y=\"202\" text-anchor=\"middle\" font-size=\"64\" font-weight=\"900\" fill=\"#2463B8\">↑</text><line x1=\"260\" y1=\"108\" x2=\"260\" y2=\"120\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"260,136 269,120 251,120\" fill=\"#4F5F64\"/><rect x=\"120\" y=\"260\" width=\"280\" height=\"84\" rx=\"16\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"260\" y=\"314\" text-anchor=\"middle\" font-size=\"32\" font-weight=\"900\" fill=\"#18262B\">河邊的樹</text><text x=\"470\" y=\"322\" text-anchor=\"middle\" font-size=\"64\" font-weight=\"900\" fill=\"#B4521F\">↓</text><line x1=\"260\" y1=\"228\" x2=\"260\" y2=\"240\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"260,256 269,240 251,240\" fill=\"#4F5F64\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">黃石公園，1920 年代到 1995 年</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">沒有狼 → 麋鹿沒有天敵 → <b>麋鹿數量暴增</b>。</p>\n<p style=\"font-size:34px;line-height:1.5\">麋鹿變多 → 小樹被吃光 → <b>河岸被沖刷</b>。</p>\n<p style=\"font-size:34px;font-weight:700;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">1995 年狼回來了，樹開始恢復。</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 7</p>\n\n</section>", "note": "科學家還在討論恢復有多少是單靠狼的功勞，但這個連鎖反應是食物網運作的經典例子。"}, {"id": "formula", "html": "<section id=\"formula\" data-section=\"能量金字塔\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:700;letter-spacing:4px;color:#E58A55\">10% 規則</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E3EDD6\">100%</p>\n<p style=\"font-size:32px;color:#BFCDC9\">草</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">→</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">10%</p>\n<p style=\"font-size:32px;color:#BFCDC9\">兔子</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">→</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#F3F5F2\">1%</p>\n<p style=\"font-size:32px;color:#BFCDC9\">狼</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:700;line-height:1.4\">每往上一層，只有大約 10% 的能量傳上去。</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">另外 90% 用在生活（呼吸、活動、保持體溫），以熱的形式散失，或留在沒被吃掉的部分。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">生態：食物網與能量金字塔 · 8</p>\n\n</section>", "note": "10% 是近似值，實際大約在 5% 到 20% 之間。這是課本和考試使用的標準數字。"}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">算算看</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">能量金字塔越往上越窄</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"能量金字塔：底層草 10,000 kJ，中層兔子 1,000 kJ，頂層狼 100 kJ\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<rect x=\"250\" y=\"40\" width=\"220\" height=\"90\" rx=\"12\" fill=\"#B4521F\"/><text x=\"360\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">狼</text><text x=\"360\" y=\"114\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#FFFFFF\">100 kJ</text><rect x=\"160\" y=\"150\" width=\"400\" height=\"90\" rx=\"12\" fill=\"#E58A55\"/><text x=\"360\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">兔子</text><text x=\"360\" y=\"224\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#18262B\">1,000 kJ</text><rect x=\"50\" y=\"260\" width=\"620\" height=\"90\" rx=\"12\" fill=\"#E3EDD6\"/><text x=\"360\" y=\"300\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">草</text><text x=\"360\" y=\"334\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#18262B\">10,000 kJ</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">層級</th><th style=\"width:60%;text-align:left\">能量</th></tr>\n<tr><td>1 · 草</td><td><b>10,000 kJ</b></td></tr>\n<tr><td>2 · 兔子</td><td><b>1,000 kJ</b></td></tr>\n<tr><td>3 · 狼</td><td><b>100 kJ</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td>4 · ？</td><td><b>10 kJ</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">所以頂層掠食者的數量<b>遠少於</b>植物。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 9</p>\n\n</section>", "note": "先遮住能量欄，讓學生自己填。問他們第 4 層可能是什麼生物，為什麼很難生存。"}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">一張表看懂</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">食物鏈和食物網，差在哪裡？</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">比較</th><th style=\"width:33%;text-align:left\">食物鏈</th><th style=\"width:33%;text-align:left\">食物網</th></tr>\n<tr><td>形狀</td><td>一條直線</td><td>很多交錯的連線</td></tr>\n<tr><td>呈現</td><td>一條能量路徑</td><td>所有路徑合在一起</td></tr>\n<tr><td>某種生物消失時</td><td><span style=\"color:#B4521F\">整條鏈斷掉</span></td><td><span style=\"color:#2463B8\">其他生物可能改吃別的</span></td></tr>\n<tr><td>真實的生態系</td><td>太簡化</td><td>比較接近真實</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">一句話記住：</b> 食物網是許多條食物鏈連在一起。</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 10</p>\n\n</section>", "note": "請學生從前面的食物網裡找出三條不同的食物鏈。"}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">例題</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.15\">草儲存了 50,000 kJ，吃兔子的老鷹能得到多少？</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:700\">第 1 層：草</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">50,000 kJ</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:700\">第 2 層：兔子</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">× 10%<br>= 5,000 kJ</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:700\">第 3 層：老鷹</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">× 10%<br>= 500 kJ</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:700\">答案</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">500 kJ</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:700;background:#E1ECFA;padding:28px 40px;border-radius:20px\">老鷹大約得到 <span style=\"color:#2463B8\">500 kJ</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 11</p>\n\n</section>", "note": "答 5,000 的學生少算了一層。請他們先把每一層都寫出來。"}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"破解迷思、小測驗與總結\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#FBF3EE\">最常見的迷思</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">箭頭是指向被吃的一方嗎？</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">不是。</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">箭頭代表<b>能量的流向</b>：從食物指向吃牠的生物。所以是草 → 兔子 → 狼，不是狼 → 兔子 → 草。</p>\n<p style=\"font-size:34px;line-height:1.5\">把每個箭頭都讀成<b>「被……吃」</b>，就不會畫反。</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">生態：食物網與能量金字塔 · 12</p>\n\n</section>", "note": "學生自己畫食物網時，請他們檢查每個箭頭都是從生產者往上指。"}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:700;letter-spacing:3px;color:#B4521F\">小測驗</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">先自己作答，再翻下一張對答案</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 1 題</p>\n<p style=\"font-size:34px;line-height:1.5\">「草 → 兔子」的箭頭代表什麼？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 2 題</p>\n<p style=\"font-size:34px;line-height:1.5\">田裡的老鼠全部消失了，蛇會怎樣？</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">第 3 題</p>\n<p style=\"font-size:34px;line-height:1.5\">為什麼食物鏈很少超過 4 或 5 層？</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">生態：食物網與能量金字塔 · 13</p>\n\n</section>", "note": "先讓學生自己作答。第 2 題請他們回頭看食物網。"}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Noto Sans TC', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.15\">答案與一句話總結</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 1 題</p>\n<p style=\"font-size:44px;font-weight:700\">被……吃</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">能量從草流向兔子。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 2 題</p>\n<p style=\"font-size:44px;font-weight:700\">數量減少</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">蛇失去了主要的食物來源。</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">第 3 題</p>\n<p style=\"font-size:44px;font-weight:700\">能量不夠</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">每一層大約損失 90%。</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">箭頭跟著能量走，從食物指向吃牠的生物。<br><span style=\"color:#E58A55\">每往上一層，只剩大約 10%。</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">生態：食物網與能量金字塔 · 14</p>\n\n</section>", "note": "可選句型練習：「如果___消失了，___會增加，因為___。」「___裡的能量，只有大約___% 會傳給___。」"}]}, "bio-ecology-en": {"title": "Ecology: Food Webs & Energy Pyramids", "lang": "en", "slides": [{"id": "cover", "html": "<section id=\"cover\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px;display:grid;grid-template-columns:1fr 720px;gap:64px;align-items:center\">\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">BIOLOGY</p>\n<h1 style=\"font-size:120px;font-weight:900;line-height:1.05;color:#F3F5F2\">Food Webs &amp;<br>Energy</h1>\n<p style=\"font-size:36px;line-height:1.45;color:#BFCDC9\">Who eats whom, and where does the energy go?<br>Follow it from the sun to the wolf.</p>\n</div>\n<svg aria-label=\"An energy pyramid with green producers at the bottom, then orange levels above, and the sun shining on it\" width=\"720\" height=\"480\" viewBox=\"0 0 720 480\">\n<circle cx=\"610\" cy=\"90\" r=\"56\" fill=\"#FFC94D\"/><polygon points=\"360,70 230,200 490,200\" fill=\"#B4521F\"/><polygon points=\"230,210 490,210 590,330 130,330\" fill=\"#E58A55\"/><polygon points=\"130,340 590,340 690,460 30,460\" fill=\"#5B8C3A\"/><line x1=\"560\" y1=\"130\" x2=\"482\" y2=\"217\" stroke=\"#FFC94D\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"470,230 489,223 475,210\" fill=\"#FFC94D\"/>\n</svg>\n\n</section>", "note": "This lesson is for students who have never studied ecology. We start with a real story from Yellowstone, build food chains and webs, and finish with the 10% rule for energy."}, {"id": "hook", "html": "<section id=\"hook\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">START WITH A PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Removing wolves made the riverside trees disappear. Why?</h2>\n</div>\n<div style=\"display:flex;gap:40px;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#F7E6DC;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:72px;height:72px\"><path d=\"M12 3 2 21h20L12 3zM12 10v5M12 18h.01\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Wolves removed</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">By the 1920s, every wolf in Yellowstone had been hunted. <b style=\"color:#18262B\">Elk numbers boomed.</b></p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;background:#E1ECFA;padding:56px;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#2463B8;width:72px;height:72px\"><path d=\"M11 20A7 7 0 0 1 4 13c0-6 6-9 16-10-1 10-4 16-10 16zM4 21c3-5 7-8 11-10\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800\">Trees vanished</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Willows and aspens along the rivers were <b style=\"color:#18262B\">eaten down</b> to stumps.</p>\n</div>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">Taking away one animal changed the whole park. <b style=\"color:#B4521F\">Food webs</b> explain why.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 2</p>\n\n</section>", "note": "Let students guess with a partner first. Wolves were brought back to Yellowstone in 1995, and the riverside trees began to recover."}, {"id": "goals", "html": "<section id=\"goals\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">LEARNING GOALS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">By the end of this deck, you can:</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Build a food chain</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Draw arrows the right way.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Read a food web</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Predict what happens when one species disappears.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex:none;color:#B4521F;width:64px;height:64px\"><path d=\"M3 3v18h18M7 16v-5M12 16V8M17 16V7\"/></svg>\n<h3 style=\"font-size:44px;font-weight:800;line-height:1.2\">Use the 10% rule</h3>\n<p style=\"font-size:32px;line-height:1.5;color:#4F5F64\">Work out energy at each level.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 3</p>\n\n</section>", "note": "The goals match the three parts: food chains, food webs, and energy pyramids."}, {"id": "basics", "html": "<section id=\"basics\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BEFORE YOU START</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Four words you need first</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Producer</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Makes its own food from sunlight, like grass and trees.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Consumer</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Gets energy by eating other living things, like rabbits and wolves.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #B4521F\">\n<h3 style=\"font-size:40px;font-weight:800\">Decomposer</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Breaks down dead things and returns nutrients to the soil: bacteria, fungi.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FBFCFA;padding:40px;border-radius:24px;border-left:12px solid #2463B8\">\n<h3 style=\"font-size:40px;font-weight:800\">Food web</h3>\n<p style=\"font-size:30px;line-height:1.5;color:#4F5F64\">Many food chains linked together, because most animals eat more than one thing.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 4</p>\n\n</section>", "note": "Decomposers are often forgotten; remind students they break down every organism in the web once it dies."}, {"id": "concept", "html": "<section id=\"concept\" data-section=\"Food chains and food webs\" data-transition=\"fade\" style=\"background:#E7EEEA;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">FOOD CHAINS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Arrows follow the energy</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"A food chain from top to bottom: sun, grass, rabbit, wolf, with arrows pointing from each to the next\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"170\" y=\"20\" width=\"300\" height=\"66\" rx=\"16\" fill=\"#FFC94D\" stroke=\"#FFC94D\" stroke-width=\"3\"/><text x=\"320\" y=\"64\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">Sun</text><rect x=\"170\" y=\"112\" width=\"300\" height=\"66\" rx=\"16\" fill=\"#5B8C3A\" stroke=\"#5B8C3A\" stroke-width=\"3\"/><text x=\"320\" y=\"156\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#FFFFFF\">Grass</text><line x1=\"320\" y1=\"88\" x2=\"320\" y2=\"94\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"320,110 329,94 311,94\" fill=\"#4F5F64\"/><rect x=\"170\" y=\"204\" width=\"300\" height=\"66\" rx=\"16\" fill=\"#E58A55\" stroke=\"#E58A55\" stroke-width=\"3\"/><text x=\"320\" y=\"248\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#18262B\">Rabbit</text><line x1=\"320\" y1=\"180\" x2=\"320\" y2=\"186\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"320,202 329,186 311,186\" fill=\"#4F5F64\"/><rect x=\"170\" y=\"296\" width=\"300\" height=\"66\" rx=\"16\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"320\" y=\"340\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"900\" fill=\"#FFFFFF\">Wolf</text><line x1=\"320\" y1=\"272\" x2=\"320\" y2=\"278\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"320,294 329,278 311,278\" fill=\"#4F5F64\"/><text x=\"475\" y=\"220\" text-anchor=\"start\" font-size=\"24\" font-weight=\"800\" fill=\"#2463B8\">energy flows</text><line x1=\"540\" y1=\"250\" x2=\"540\" y2=\"314\" stroke=\"#2463B8\" stroke-width=\"5\" stroke-linecap=\"round\"/><polygon points=\"540,330 549,314 531,314\" fill=\"#2463B8\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Sun → grass → rabbit → wolf</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">Energy starts with the <b>sun</b>; producers capture it.</p>\n<p style=\"font-size:34px;line-height:1.5\">Each arrow means <b>“is eaten by”</b>: grass is eaten by the rabbit.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Arrows point from the food to the eater.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 5</p>\n\n</section>", "note": "Have students read each arrow out loud as “is eaten by” or “gives energy to.”"}, {"id": "figure", "html": "<section id=\"figure\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">FOOD WEBS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Most animals eat more than one thing</h2>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;align-items:center\">\n<svg aria-label=\"A food web: grass feeds rabbit, deer and mouse; rabbit feeds wolf and hawk; deer feeds wolf; mouse feeds hawk and snake; snake feeds hawk\" width=\"1500\" height=\"370\" viewBox=\"0 0 1500 370\">\n<line x1=\"714\" y1=\"300\" x2=\"439\" y2=\"235\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"426,232 437,243 441,228\" fill=\"#4F5F64\"/><line x1=\"760\" y1=\"300\" x2=\"760\" y2=\"246\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"760,232 752,246 768,246\" fill=\"#4F5F64\"/><line x1=\"806\" y1=\"300\" x2=\"1081\" y2=\"235\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"1094,232 1079,228 1083,243\" fill=\"#4F5F64\"/><line x1=\"392\" y1=\"170\" x2=\"458\" y2=\"111\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"468,102 452,106 463,117\" fill=\"#4F5F64\"/><line x1=\"442\" y1=\"170\" x2=\"824\" y2=\"104\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"838,102 822,97 825,112\" fill=\"#4F5F64\"/><line x1=\"726\" y1=\"170\" x2=\"527\" y2=\"106\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"514,102 525,114 529,99\" fill=\"#4F5F64\"/><line x1=\"1111\" y1=\"170\" x2=\"942\" y2=\"107\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"929,102 939,114 945,100\" fill=\"#4F5F64\"/><line x1=\"1152\" y1=\"170\" x2=\"1218\" y2=\"111\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"1228,102 1212,106 1223,117\" fill=\"#4F5F64\"/><line x1=\"1140\" y1=\"70\" x2=\"1016\" y2=\"70\" stroke=\"#4F5F64\" stroke-width=\"4\" stroke-linecap=\"round\"/><polygon points=\"1002,70 1016,78 1016,62\" fill=\"#4F5F64\"/><rect x=\"660\" y=\"300\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#5B8C3A\" stroke=\"#5B8C3A\" stroke-width=\"3\"/><text x=\"760\" y=\"340\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">Grass</text><rect x=\"280\" y=\"170\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"380\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">Rabbit</text><rect x=\"660\" y=\"170\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"760\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">Deer</text><rect x=\"1040\" y=\"170\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#F7E6DC\" stroke=\"#F7E6DC\" stroke-width=\"3\"/><text x=\"1140\" y=\"210\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">Mouse</text><rect x=\"1140\" y=\"40\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#E58A55\" stroke=\"#E58A55\" stroke-width=\"3\"/><text x=\"1240\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">Snake</text><rect x=\"800\" y=\"40\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"900\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">Hawk</text><rect x=\"380\" y=\"40\" width=\"200\" height=\"60\" rx=\"14\" fill=\"#B4521F\" stroke=\"#B4521F\" stroke-width=\"3\"/><text x=\"480\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">Wolf</text>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Every arrow points from food to eater.</p>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:32px\">\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">A <b>food web</b> links many chains together.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">Remove one species and the change <b>ripples</b> through the web.</p>\n<p style=\"font-size:30px;line-height:1.5;background:#FBFCFA;padding:28px 32px;border:2px solid #D3DCD8;border-radius:20px\">Webs with more links are <b>more stable</b>: eaters can switch food.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 6</p>\n\n</section>", "note": "Optional activity: eight students hold role cards (Sun, Grass, Rabbit, Deer, Mouse, Snake, Hawk, Wolf) and pass yarn from each food to its eater. Say “the wolf is gone” and have the wolf let go; ask who feels the yarn go slack."}, {"id": "concept2", "html": "<section id=\"concept2\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">BACK TO THE PUZZLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">One missing link changes the whole web</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:640px 1fr;gap:64px;align-items:center;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:16px;align-items:center\">\n<svg aria-label=\"Chain reaction: wolves go down, elk go up, riverside trees go down\" width=\"640\" height=\"380\" viewBox=\"0 0 640 380\">\n<rect x=\"120\" y=\"20\" width=\"280\" height=\"84\" rx=\"16\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"260\" y=\"74\" text-anchor=\"middle\" font-size=\"32\" font-weight=\"900\" fill=\"#18262B\">Wolves</text><text x=\"470\" y=\"82\" text-anchor=\"middle\" font-size=\"64\" font-weight=\"900\" fill=\"#B4521F\">↓</text><rect x=\"120\" y=\"140\" width=\"280\" height=\"84\" rx=\"16\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"260\" y=\"194\" text-anchor=\"middle\" font-size=\"32\" font-weight=\"900\" fill=\"#18262B\">Elk</text><text x=\"470\" y=\"202\" text-anchor=\"middle\" font-size=\"64\" font-weight=\"900\" fill=\"#2463B8\">↑</text><line x1=\"260\" y1=\"108\" x2=\"260\" y2=\"120\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"260,136 269,120 251,120\" fill=\"#4F5F64\"/><rect x=\"120\" y=\"260\" width=\"280\" height=\"84\" rx=\"16\" fill=\"#FBFCFA\" stroke=\"#D3DCD8\" stroke-width=\"3\"/><text x=\"260\" y=\"314\" text-anchor=\"middle\" font-size=\"32\" font-weight=\"900\" fill=\"#18262B\">Trees</text><text x=\"470\" y=\"322\" text-anchor=\"middle\" font-size=\"64\" font-weight=\"900\" fill=\"#B4521F\">↓</text><line x1=\"260\" y1=\"228\" x2=\"260\" y2=\"240\" stroke=\"#4F5F64\" stroke-width=\"6\" stroke-linecap=\"round\"/><polygon points=\"260,256 269,240 251,240\" fill=\"#4F5F64\"/>\n</svg>\n<p style=\"font-size:24px;color:#4F5F64\">Yellowstone, 1920s to 1995</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-size:34px;line-height:1.5\">No wolves → elk had no predator → <b>elk numbers boomed</b>.</p>\n<p style=\"font-size:34px;line-height:1.5\">More elk → young trees eaten → <b>riverbanks washed away</b>.</p>\n<p style=\"font-size:34px;font-weight:800;line-height:1.4;background:#FBFCFA;padding:24px 32px;border-radius:16px\">Wolves returned in 1995, and the trees began to recover.</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 7</p>\n\n</section>", "note": "Scientists still debate how much of the recovery is due to wolves alone, but the chain reaction is a classic example of a food web at work."}, {"id": "formula", "html": "<section id=\"formula\" data-section=\"Energy pyramids\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px;justify-content:center\">\n<p style=\"font-size:32px;font-weight:800;letter-spacing:4px;color:#E58A55\">THE 10% RULE</p>\n<div style=\"display:flex;align-items:flex-end;gap:48px\">\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E3EDD6\">100%</p>\n<p style=\"font-size:32px;color:#BFCDC9\">grass</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">→</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#E58A55\">10%</p>\n<p style=\"font-size:32px;color:#BFCDC9\">rabbit</p>\n</div>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:140px;line-height:1.1;color:#BFCDC9\">→</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:8px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:160px;font-weight:700;line-height:1;color:#F3F5F2\">1%</p>\n<p style=\"font-size:32px;color:#BFCDC9\">wolf</p>\n</div>\n</div>\n<p style=\"font-size:48px;font-weight:800;line-height:1.4\">Only about 10% of the energy passes up each level.</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">The other 90% is used for living (breathing, moving, keeping warm) and lost as heat, or stays in parts that aren’t eaten.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Ecology: Food Webs &amp; Energy Pyramids · 8</p>\n\n</section>", "note": "10% is an approximation; real values range from about 5 to 20%. It is the standard figure in textbooks and tests."}, {"id": "numbers", "html": "<section id=\"numbers\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">TRY THE NUMBERS</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">An energy pyramid gets narrow fast</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:720px 1fr;gap:64px;align-items:center;flex:1\">\n<svg aria-label=\"Energy pyramid: grass 10,000 kJ at the bottom, rabbit 1,000 kJ in the middle, wolf 100 kJ at the top\" width=\"720\" height=\"400\" viewBox=\"0 0 720 400\">\n<rect x=\"250\" y=\"40\" width=\"220\" height=\"90\" rx=\"12\" fill=\"#B4521F\"/><text x=\"360\" y=\"80\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#FFFFFF\">Wolf</text><text x=\"360\" y=\"114\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#FFFFFF\">100 kJ</text><rect x=\"160\" y=\"150\" width=\"400\" height=\"90\" rx=\"12\" fill=\"#E58A55\"/><text x=\"360\" y=\"190\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">Rabbit</text><text x=\"360\" y=\"224\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#18262B\">1,000 kJ</text><rect x=\"50\" y=\"260\" width=\"620\" height=\"90\" rx=\"12\" fill=\"#E3EDD6\"/><text x=\"360\" y=\"300\" text-anchor=\"middle\" font-size=\"28\" font-weight=\"900\" fill=\"#18262B\">Grass</text><text x=\"360\" y=\"334\" text-anchor=\"middle\" font-size=\"24\" font-weight=\"700\" fill=\"#18262B\">10,000 kJ</text>\n</svg>\n<table style=\"font-size:32px;color:#18262B\">\n<tr><th style=\"width:40%;text-align:left\">Level</th><th style=\"width:60%;text-align:left\">Energy</th></tr>\n<tr><td>1 · Grass</td><td><b>10,000 kJ</b></td></tr>\n<tr><td>2 · Rabbit</td><td><b>1,000 kJ</b></td></tr>\n<tr><td>3 · Wolf</td><td><b>100 kJ</b></td></tr>\n<tr style=\"background:#F7E6DC\"><td>4 · ?</td><td><b>10 kJ</b></td></tr>\n</table>\n</div>\n<p style=\"font-size:32px;line-height:1.5\">That’s why there are <b>far fewer</b> top predators than plants.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 9</p>\n\n</section>", "note": "Cover the energy column and let students fill it in. Ask what could be at level 4, and why it would struggle to survive."}, {"id": "compare", "html": "<section id=\"compare\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">ONE TABLE</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Food chain vs. food web</h2>\n</div>\n<table style=\"font-size:30px;color:#18262B\">\n<tr><th style=\"width:34%;text-align:left\">Compare</th><th style=\"width:33%;text-align:left\">Food chain</th><th style=\"width:33%;text-align:left\">Food web</th></tr>\n<tr><td>Shape</td><td>One straight line</td><td>Many crossing links</td></tr>\n<tr><td>Shows</td><td>One path of energy</td><td>All the paths together</td></tr>\n<tr><td>If one species vanishes</td><td><span style=\"color:#B4521F\">The chain breaks</span></td><td><span style=\"color:#2463B8\">Others may switch food</span></td></tr>\n<tr><td>Real ecosystems</td><td>Too simple</td><td>Closer to reality</td></tr>\n</table>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:32px;line-height:1.5\"><b style=\"color:#B4521F\">Remember:</b> a food web is many food chains linked together.</p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 10</p>\n\n</section>", "note": "Ask students to trace three separate chains inside the food web from earlier."}, {"id": "example", "html": "<section id=\"example\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">WORKED EXAMPLE</p>\n<h2 style=\"font-size:64px;font-weight:900;line-height:1.1\">Grass stores 50,000 kJ. How much reaches a hawk that eats rabbits?</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:32px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">1</p>\n<h3 style=\"font-size:36px;font-weight:800\">Level 1: grass</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">50,000 kJ</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">2</p>\n<h3 style=\"font-size:36px;font-weight:800\">Level 2: rabbit</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">× 10%<br>= 5,000 kJ</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">3</p>\n<h3 style=\"font-size:36px;font-weight:800\">Level 3: hawk</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">× 10%<br>= 500 kJ</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:20px;background:#FBFCFA;padding:40px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">4</p>\n<h3 style=\"font-size:36px;font-weight:800\">Answer</h3>\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;line-height:1.6\">500 kJ</p>\n</div>\n</div>\n<p style=\"font-size:44px;font-weight:800;background:#E1ECFA;padding:28px 40px;border-radius:20px\">The hawk gets about <span style=\"color:#2463B8\">500 kJ</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 11</p>\n\n</section>", "note": "Students who answer 5,000 skipped a level. Have them write out every level first."}, {"id": "myth", "html": "<section id=\"myth\" data-section=\"Myth, quiz and summary\" data-transition=\"fade\" style=\"background:#A84B1B;color:#FBF3EE;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#FBF3EE\">THE MOST COMMON MYTH</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Do arrows point to what gets eaten?</h2>\n</div>\n<p style=\"font-size:160px;font-weight:900;line-height:1.05\">No.</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:48px\">\n<p style=\"font-size:34px;line-height:1.5\">Arrows show the <b>flow of energy</b>: from the food to the eater. So it’s grass → rabbit → wolf, not wolf → rabbit → grass.</p>\n<p style=\"font-size:34px;line-height:1.5\">Read every arrow as <b>“is eaten by”</b> and you’ll never get it backward.</p>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#FBF3EE\">Ecology: Food Webs &amp; Energy Pyramids · 12</p>\n\n</section>", "note": "When students draw their own webs, have them check that every arrow points up from the producers."}, {"id": "quiz", "html": "<section id=\"quiz\" data-transition=\"fade\" style=\"background:#F3F5F2;color:#18262B;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px\">\n<p style=\"font-size:24px;font-weight:800;letter-spacing:3px;color:#B4521F\">QUICK CHECK</p>\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answer first, then check the next slide</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px;flex:1\">\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q1</p>\n<p style=\"font-size:34px;line-height:1.5\">In “grass → rabbit,” what does the arrow mean?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q2</p>\n<p style=\"font-size:34px;line-height:1.5\">All the mice disappear from a field. What happens to the snakes?</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:24px;background:#FBFCFA;padding:48px;border:2px solid #D3DCD8;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:44px;font-weight:700;color:#B4521F\">Q3</p>\n<p style=\"font-size:34px;line-height:1.5\">Why do food chains rarely have more than 4 or 5 levels?</p>\n</div>\n</div>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#4F5F64\">Ecology: Food Webs &amp; Energy Pyramids · 13</p>\n\n</section>", "note": "Let students answer on their own first. For Q2, have them look back at the food web."}, {"id": "answers", "html": "<section id=\"answers\" data-transition=\"fade\" style=\"background:#18262B;color:#F3F5F2;font-family:'Nunito Sans', Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:56px\">\n<h2 style=\"font-size:72px;font-weight:900;line-height:1.1\">Answers and the big idea</h2>\n<div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q1</p>\n<p style=\"font-size:44px;font-weight:800\">Is eaten by</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Energy flows from grass to rabbit.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q2</p>\n<p style=\"font-size:44px;font-weight:800\">They decline</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">Snakes lose a main food source.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:16px;background:#22343A;padding:40px;border-radius:24px\">\n<p style=\"font-family:'JetBrains Mono', 'Courier New', monospace;font-size:32px;font-weight:700;color:#E58A55\">Q3</p>\n<p style=\"font-size:44px;font-weight:800\">Energy runs out</p>\n<p style=\"font-size:28px;line-height:1.5;color:#BFCDC9\">About 90% is lost at each level.</p>\n</div>\n</div>\n<div style=\"flex:1\"></div>\n<p style=\"font-size:52px;font-weight:900;line-height:1.35\">Arrows follow the energy, from food to eater.<br><span style=\"color:#E58A55\">Only about 10% passes up each level.</span></p>\n<p style=\"position:absolute;left:128px;bottom:64px;width:900px;font-size:24px;color:#BFCDC9\">Ecology: Food Webs &amp; Energy Pyramids · 14</p>\n\n</section>", "note": "Optional sentence frames: “If the ___ disappears, the ___ will increase because ___.” “Only about ___% of the energy in ___ passes to ___.”"}]}};
window.DECK_FONTS = ["https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@500;700&display=swap", "https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;700;900&display=swap", "https://fonts.googleapis.com/css2?family=Nunito+Sans:wght@400;700;800;900&display=swap"];
